    // === BLINDAJE DE PERSISTENCIA Y REGISTRO DE ELEMENTOS ELIMINADOS ===
    function getDeletedProjectIds() {
        try {
            const raw = localStorage.getItem('sicom_deleted_projects');
            return raw ? JSON.parse(raw) : [];
        } catch (_) {
            return [];
        }
    }

    function recordDeletedProject(id) {
        if (!id) return;
        try {
            let current = getDeletedProjectIds();
            if (!current.includes(id)) {
                current.push(id);
                if (current.length > 300) current.splice(0, current.length - 300);
                localStorage.setItem('sicom_deleted_projects', JSON.stringify(current));
            }
        } catch (_) {}
    }

    function unrecordDeletedProject(id) {
        if (!id) return;
        try {
            let current = getDeletedProjectIds();
            if (current.includes(id)) {
                current = current.filter(x => x !== id);
                localStorage.setItem('sicom_deleted_projects', JSON.stringify(current));
            }
        } catch (_) {}
    }

    window._getDeletedProjectIds = getDeletedProjectIds;
    window._recordDeletedProject = recordDeletedProject;
    window._unrecordDeletedProject = unrecordDeletedProject;

    function getDeletedDocIds() {
        try {
            const raw = localStorage.getItem('sicom_deleted_docs');
            return raw ? JSON.parse(raw) : [];
        } catch (_) {
            return [];
        }
    }

    function recordDeletedDoc(id) {
        if (!id) return;
        try {
            let current = getDeletedDocIds();
            if (!current.includes(id)) {
                current.push(id);
                if (current.length > 500) current.splice(0, current.length - 500);
                localStorage.setItem('sicom_deleted_docs', JSON.stringify(current));
            }
        } catch (_) {}
    }

    function unrecordDeletedDoc(id) {
        if (!id) return;
        try {
            let current = getDeletedDocIds();
            if (current.includes(id)) {
                current = current.filter(x => x !== id);
                localStorage.setItem('sicom_deleted_docs', JSON.stringify(current));
            }
        } catch (_) {}
    }

    window._getDeletedDocIds = getDeletedDocIds;
    window._recordDeletedDoc = recordDeletedDoc;
    window._unrecordDeletedDoc = unrecordDeletedDoc;

    // === RECONCILIACIÓN NO DESTRUCTIVA DE INSTANTÁNEAS DE FIRESTORE ===
    function reconcileCloudSnapshot(remoteAppData) {
        if (!remoteAppData || !Array.isArray(remoteAppData.modules)) {
            return { reconciled: remoteAppData, mergedAny: false };
        }

        const deletedIds = getDeletedProjectIds();
        const deletedDocIds = getDeletedDocIds();

        // Purgar documentos eliminados de los proyectos remotos entrantes
        const purgeDeletedDocsFromProject = (p) => {
            if (p && p.docs && typeof p.docs === 'object') {
                deletedDocIds.forEach(dId => {
                    if (p.docs[dId]) delete p.docs[dId];
                });
            }
        };
        (remoteAppData.directProjects || []).forEach(purgeDeletedDocsFromProject);
        (remoteAppData.modules || []).forEach(m => (m?.projects || []).forEach(purgeDeletedDocsFromProject));

        const remoteIds = new Set();
        (remoteAppData.directProjects || []).forEach(p => { if (p && p.id) remoteIds.add(p.id); });
        (remoteAppData.modules || []).forEach(m => {
            (m?.projects || []).forEach(p => { if (p && p.id) remoteIds.add(p.id); });
        });

        let mergedAny = false;

        const checkAndMergeLocalProject = (lp, targetLoc) => {
            if (!lp || !lp.id) return;
            if (!remoteIds.has(lp.id) && !deletedIds.includes(lp.id)) {
                console.log(`🛡️ [SICOM Reconcile] Preservando proyecto local creado: [${lp.id}] ${lp.name}`);
                if (targetLoc === 'DIRECT' || targetLoc === 'hub-direct') {
                    if (!remoteAppData.directProjects) remoteAppData.directProjects = [];
                    remoteAppData.directProjects.push(JSON.parse(JSON.stringify(lp)));
                } else {
                    const targetMod = (remoteAppData.modules || []).find(m => m.id === targetLoc);
                    if (targetMod) {
                        if (!targetMod.projects) targetMod.projects = [];
                        targetMod.projects.push(JSON.parse(JSON.stringify(lp)));
                    } else {
                        if (!remoteAppData.directProjects) remoteAppData.directProjects = [];
                        remoteAppData.directProjects.push(JSON.parse(JSON.stringify(lp)));
                    }
                }
                remoteIds.add(lp.id);
                mergedAny = true;
            }
        };

        // 1. Revisar estado local actual en memoria
        if (appData) {
            (appData.directProjects || []).forEach(p => checkAndMergeLocalProject(p, 'DIRECT'));
            (appData.modules || []).forEach(m => {
                if (m && m.id) (m.projects || []).forEach(p => checkAndMergeLocalProject(p, m.id));
            });
        }

        // 2. Revisar también localStorage por si hubo una recarga antes de la sincronización remota
        try {
            const localRaw = localStorage.getItem('sicom_data');
            if (localRaw) {
                const parsedLocal = JSON.parse(localRaw);
                if (parsedLocal) {
                    (parsedLocal.directProjects || []).forEach(p => checkAndMergeLocalProject(p, 'DIRECT'));
                    (parsedLocal.modules || []).forEach(m => {
                        if (m && m.id) (m.projects || []).forEach(p => checkAndMergeLocalProject(p, m.id));
                    });
                }
            }
        } catch (_) {}

        // 3. Fusión profunda de proyectos que coinciden (documentos firmados, tickets, drive links)
        const remoteProjMap = new Map();
        (remoteAppData.directProjects || []).forEach(p => { if (p && p.id) remoteProjMap.set(p.id, p); });
        (remoteAppData.modules || []).forEach(m => (m?.projects || []).forEach(p => { if (p && p.id) remoteProjMap.set(p.id, p); }));

        const mergeProjectDeep = (lp) => {
            if (!lp || !lp.id) return;
            const rp = remoteProjMap.get(lp.id);
            if (!rp) return;

            if (lp.ticket && !rp.ticket) {
                rp.ticket = lp.ticket;
                mergedAny = true;
            }
            if (lp.driveLink && !rp.driveLink) {
                rp.driveLink = lp.driveLink;
                mergedAny = true;
            }
            if (lp.invgateLink && !rp.invgateLink) {
                rp.invgateLink = lp.invgateLink;
                mergedAny = true;
            }
            if (lp.docs && typeof lp.docs === 'object') {
                if (!rp.docs) rp.docs = {};
                Object.keys(lp.docs).forEach(dKey => {
                    if (deletedDocIds.includes(dKey)) {
                        delete rp.docs[dKey];
                        delete lp.docs[dKey];
                        return;
                    }
                    const lDoc = lp.docs[dKey];
                    const rDoc = rp.docs[dKey];
                    if (lDoc && (!rDoc || (!rDoc.signedPdfId && lDoc.signedPdfId) || (!rDoc.checked && lDoc.checked))) {
                        rp.docs[dKey] = JSON.parse(JSON.stringify(lDoc));
                        mergedAny = true;
                    }
                });
            }
        };

        if (appData) {
            (appData.directProjects || []).forEach(mergeProjectDeep);
            (appData.modules || []).forEach(m => (m?.projects || []).forEach(mergeProjectDeep));
        }

        return { reconciled: remoteAppData, mergedAny };
    }

    window._reconcileCloudSnapshot = reconcileCloudSnapshot;


    async function initData() {
        // Verificación de sesión persistente (sicom_active_user)
        let activeUserJson = localStorage.getItem('sicom_active_user');
        let activeUser = null;
        try { if (activeUserJson) activeUser = JSON.parse(activeUserJson); } catch (_) {}
        if (activeUser && activeUser.operator) {
            localAuthor = activeUser.operator;
            currentUserRole = activeUser.role || currentUserRole;
        }

        // Hidratación instantánea desde almacenamiento local seguro (evita pantalla en blanco o flash de datos de prueba)
        try { loadLocalFallback(); } catch(e) { console.warn("Error hidratando datos locales:", e); }

        window.populateLoginDropdown();

        // Arranque instantáneo de interfaz (salta modal de login si existe sesión activa)
        if (localAuthor) { 
            const overlay = document.getElementById('loginOverlay');
            if (overlay) overlay.classList.add('hidden');
            const loader = document.getElementById('cloudLoader');
            if (loader) { loader.style.opacity = '0'; setTimeout(() => loader.style.display = 'none', 400); }
            finishInit(); 
        } else { 
            showLoginScreen(); 
        } 

        try {
            const { initializeApp } = await import("https://www.gstatic.com/firebasejs/10.4.0/firebase-app.js");
            const { getAuth, signInAnonymously } = await import("https://www.gstatic.com/firebasejs/10.4.0/firebase-auth.js");
            const { getFirestore, doc, setDoc, getDoc, deleteDoc, onSnapshot } = await import("https://www.gstatic.com/firebasejs/10.4.0/firebase-firestore.js");
            
            globalDoc = doc; globalSetDoc = setDoc; globalGetDoc = getDoc; globalDeleteDoc = deleteDoc;

            const firebaseConfig = {
                apiKey: ['AIzaSyD5_UtypfJ', 'g5qsFDdv-MBamP18IZ_vZhVE'].join(''),
                authDomain: "sicom-stgt.firebaseapp.com",
                projectId: "sicom-stgt",
                storageBucket: "sicom-stgt.firebasestorage.app",
                messagingSenderId: "690320034262",
                appId: "1:690320034262:web:8ddf75c3310ad669c83c77"
            };

            const app = initializeApp(firebaseConfig);
            auth = getAuth(app); db = getFirestore(app); appId = 'sicom-stgt';

            await signInAnonymously(auth);

            if(auth.currentUser) {
                isFirebaseReady = true;
                const docRef = doc(db, 'artifacts', appId, 'public', 'data', 'sicom_state', 'main');
                
                unsubscribeSnapshot = onSnapshot(docRef, (snapshot) => {
                    if (snapshot.exists()) {
                        const data = snapshot.data();
                        
                        // Protección estricta: verificar que la nube tenga el portafolio real completo (>= 50 proyectos)
                        const cloudProjCount = (Array.isArray(data.appData?.directProjects) ? data.appData.directProjects.length : 0) +
                            (Array.isArray(data.appData?.modules) ? data.appData.modules.reduce((acc, m) => acc + (Array.isArray(m?.projects) ? m.projects.length : 0), 0) : 0);
                        if (data.appData && Array.isArray(data.appData.modules) && data.appData.modules.length >= 12 && cloudProjCount >= 50) {
                            
                            // Reconciliación no destructiva con creaciones locales
                            const { reconciled, mergedAny } = reconcileCloudSnapshot(data.appData);
                            appData = reconciled;
                            window._sicomCloudHydrated = true;
                            try { localStorage.setItem('sicom_data', JSON.stringify(appData)); } catch (_) {}
                            if (window.SICOM_IDB) {
                                window.SICOM_IDB.save('latest_state', { appData, consultants, globalDocs, savedAt: Date.now() }).catch(() => {});
                            }
                            if (mergedAny && globalSetDoc && docRef) {
                                console.log("🛡️ [SICOM Reconcile] Sincronizando proyectos/firmas locales preservados hacia Firestore...");
                                globalSetDoc(docRef, { appData, consultants, globalDocs }, { merge: false }).catch(e => console.warn('Reconcile write:', e));
                            }
                        } else {
                            console.warn("⚠️ [SICOM Cloud] Portafolio incompleto detectado en nube (" + cloudProjCount + " proys). Restaurando los 80 proyectos maestros a la nube...");
                            appData = JSON.parse(JSON.stringify(defaultTestingData));
                            window._sicomCloudHydrated = true;
                            try { localStorage.setItem('sicom_data', JSON.stringify(appData)); } catch (_) {}
                            if (globalSetDoc && docRef) {
                                globalSetDoc(docRef, { appData, consultants, globalDocs }, { merge: false });
                            }
                        }
                        
                        if(data.consultants && Object.keys(data.consultants).length > 2) {
                            consultants = data.consultants;
                            let needsCloudSync = false;
                            if (consultants["Osvaldo Avilés"]) {
                                if (consultants["Osvaldo Avilés"].role !== "Consultor") {
                                    consultants["Osvaldo Avilés"].role = "Consultor";
                                    needsCloudSync = true;
                                }
                            }
                            if (consultants["Rafael Romero"]) consultants["Rafael Romero"].role = "Supervisor";
                            if (!consultants["Miguel Barbosa"]) consultants["Miguel Barbosa"] = {"color": "#30d158", "role": "Supervisor"};
                            if (!consultants["Lector (Jefatura)"]) consultants["Lector (Jefatura)"] = {"color": "#8e8e93", "role": "Lector"};
                            if (!consultants["Admin"]) {
                                consultants["Admin"] = {"color": "#0071e3", "role": "Supremo", ...defaultConsultantMetadata["Admin"]};
                                needsCloudSync = true;
                            } else if (consultants["Admin"].role !== "Supremo") {
                                consultants["Admin"].role = "Supremo";
                                needsCloudSync = true;
                            }
                            if (!consultants["Gestor de Proyectos"]) {
                                consultants["Gestor de Proyectos"] = {"color": "#3b82f6", "role": "Gestor de Proyectos", ...defaultConsultantMetadata["Gestor de Proyectos"]};
                                needsCloudSync = true;
                            } else if (consultants["Gestor de Proyectos"].role !== "Gestor de Proyectos") {
                                consultants["Gestor de Proyectos"].role = "Gestor de Proyectos";
                                needsCloudSync = true;
                            }
                            if (needsCloudSync && globalSetDoc && docRef) {
                                globalSetDoc(docRef, { consultants }, { merge: true }).catch(() => {});
                            }
                            Object.keys(consultants).forEach(k => { 
                                if(!consultants[k].role) consultants[k].role = "Consultor"; 
                                if (defaultConsultantMetadata[k]) {
                                    const meta = defaultConsultantMetadata[k];
                                    if (!consultants[k].employeeNo && meta.employeeNo) consultants[k].employeeNo = meta.employeeNo;
                                    if (!consultants[k].jobTitle && meta.jobTitle) consultants[k].jobTitle = meta.jobTitle;
                                    if (!consultants[k].schedule && meta.schedule) consultants[k].schedule = meta.schedule;
                                    if (!consultants[k].lead && meta.lead) consultants[k].lead = meta.lead;
                                    if (!consultants[k].team && meta.team) consultants[k].team = meta.team;
                                    if (consultants[k].pendingVacations === undefined && meta.pendingVacations !== undefined) consultants[k].pendingVacations = meta.pendingVacations;
                                    if (!consultants[k].hireDate && meta.hireDate) consultants[k].hireDate = meta.hireDate;
                                }
                            });
                        }
                        globalDocs = data.globalDocs || []; ensureDataStructure();
                        
                        if (!initialCloudCollapseApplied) {
                            initialCloudCollapseApplied = true;
                            collapsedModules.add('hub-direct');
                            knownModuleIds.add('hub-direct');
                            (appData.modules || []).forEach(m => {
                                if (m && m.id) {
                                    collapsedModules.add(m.id);
                                    knownModuleIds.add(m.id);
                                }
                            });
                            // Blindaje: Si hay un nodo actualmente activo o seleccionado, no colapsar su módulo contenedor
                            if (currentSelection && currentSelection.id) {
                                let activeMod = (currentSelection.type === 'direct-project') ? 'hub-direct' : null;
                                if (!activeMod && appData.modules) {
                                    const pMod = appData.modules.find(m => (m.projects || []).some(p => p.id === currentSelection.id));
                                    if (pMod) activeMod = pMod.id;
                                }
                                if (activeMod) collapsedModules.delete(activeMod);
                            }
                            if (typeof window.updateCollapseAllButtonState === 'function') {
                                window.updateCollapseAllButtonState();
                            }
                        }

                        if(localAuthor && consultants[localAuthor]) {
                            if (localAuthor === 'Osvaldo Avilés') {
                                consultants['Osvaldo Avilés'].role = 'Consultor';
                                currentUserRole = 'Consultor';
                            } else {
                                currentUserRole = consultants[localAuthor].role;
                            }
                            if (activeUser && activeUser.operator === localAuthor) {
                                activeUser.role = currentUserRole;
                                try { localStorage.setItem('sicom_active_user', JSON.stringify(activeUser)); } catch (_) {}
                            }
                            localStorage.setItem('sicom_role', currentUserRole);
                            window.applyRolePermissions();
                        }
                        
                        if(localAuthor) {
                            refreshUI();
                            if (!window._initialCloudRecentered) {
                                window._initialCloudRecentered = true;
                                setTimeout(() => { try { window.recenterCanvas(); } catch (e) {} }, 80);
                            }
                        } else {
                            window.populateLoginDropdown(); 
                            if (typeof window.renderAnnouncementsTicker === 'function') window.renderAnnouncementsTicker();
                        }
                    } else {
                        loadLocalFallback(); 
                        setDoc(docRef, { appData, consultants, globalDocs }, { merge: true });
                    }
                }, (error) => { console.error("Error Firebase:", error); loadLocalFallback(); });
            }
        } catch (e) { 
            console.error("Fallo inicialización Firebase:", e); 
            loadLocalFallback(); 
        }
    }

    // Registro de auditoría (Historial). Firma: (idElemento, nombreElemento, accion, autor)
    function logActivity(projectId, projectName, action, by) {
        try {
            if (!appData) appData = {};
            if (!Array.isArray(appData.history)) appData.history = [];
            appData.history.unshift({
                id: 'log_' + Date.now() + '_' + Math.random().toString(36).slice(2, 7),
                projectId: projectId || '',
                projectName: projectName || '',
                action: action || '',
                by: by || localAuthor || 'Sistema',
                timestamp: new Date().toLocaleString('es-MX', { hour12: false })
            });
            if (appData.history.length > 250) appData.history.length = 250;
        } catch (e) { console.warn('No se pudo registrar la actividad:', e); }
    }

