            if (!sel) return;
            sel.innerHTML = '<option value="">(Sin asignar)</option>' + consNames.map(c => `<option value="${escapeHtml(c)}" ${c === val ? 'selected' : ''}>${escapeHtml(c)}</option>`).join('');
            sel.disabled = isLector;
