    window.openEditConsultantModal = function(name) {
        if (!consultants[name]) return;
        const cData = consultants[name];
        document.getElementById('editConsOldName').value = name;
        document.getElementById('editConsName').value = name;
        document.getElementById('editConsTitle').value = cData.jobTitle || cData.title || '';
        document.getElementById('editConsRole').value = cData.role || 'Consultor';
        document.getElementById('editConsColor').value = cData.color || '#ee6018';
        document.getElementById('editConsColorHex').value = (cData.color || '#ee6018').toUpperCase();
        document.getElementById('editConsModalTitle').textContent = `Perfil: ${name}`;

        if (document.getElementById('editConsEmployeeNo')) {
            document.getElementById('editConsEmployeeNo').value = cData.employeeNo || defaultConsultantMetadata[name]?.employeeNo || '';
        }
        if (document.getElementById('editConsSchedule')) {
            document.getElementById('editConsSchedule').value = cData.schedule || defaultConsultantMetadata[name]?.schedule || '09:00 a 18:30';
        }
        if (document.getElementById('editConsTeam')) {
            document.getElementById('editConsTeam').value = cData.team || defaultConsultantMetadata[name]?.team || '';
        }
        if (document.getElementById('editConsPendingVacations')) {
            document.getElementById('editConsPendingVacations').value = cData.pendingVacations !== undefined ? cData.pendingVacations : (defaultConsultantMetadata[name]?.pendingVacations || 4);
        }
        let rawHire = cData.hireDate || defaultConsultantMetadata[name]?.hireDate || '';
        if (rawHire && rawHire.includes('/')) {
            const p = rawHire.split('/');
            if (p.length === 3) rawHire = `${p[2]}-${String(p[1]).padStart(2,'0')}-${String(p[0]).padStart(2,'0')}`;
        }
        if (document.getElementById('editConsHireDate')) {
            document.getElementById('editConsHireDate').value = rawHire;
            if (typeof window.previewConsLftDays === 'function') window.previewConsLftDays(rawHire);
        }

        // Cargar días de Home Office habituales (1=Lun ... 5=Vie)
        const currentHoDays = cData.homeOfficeDays || (defaultConsultantMetadata[name]?.homeOfficeDays || (typeof window.getDefaultHoDaysForName === 'function' ? window.getDefaultHoDaysForName(name) : [1, 3]));
        for (let d = 1; d <= 5; d++) {
            const cb = document.getElementById('editConsHo' + d);
            if (cb) cb.checked = Array.isArray(currentHoDays) && currentHoDays.includes(d);
        }

        const leadSel = document.getElementById('editConsLead');
        if (leadSel) {
            const currentLead = cData.lead || defaultConsultantMetadata[name]?.lead || '';
            leadSel.innerHTML = '<option value="">-- Sin jefe inmediato (Dirección) --</option>' +
                Object.keys(consultants).filter(k => k !== name && k !== 'Lector (Jefatura)').map(k => {
                    const kRole = consultants[k]?.role || '';
                    return `<option value="${escapeHtml(k)}" ${k === currentLead ? 'selected' : ''}>${escapeHtml(k)} (${kRole})</option>`;
                }).join('');
        }

        if (typeof window.renderVacationLedgerHistory === 'function') {
            window.renderVacationLedgerHistory(name);
        }
        
        const m = document.getElementById('editConsultantModal');
        if (m) {
            m.classList.remove('hidden');
            if (typeof window.pushNavigationState === 'function') window.pushNavigationState('editConsultantModal');
            setTimeout(() => m.classList.remove('opacity-0'), 10);
        }
    };

    window.renderVacationLedgerHistory = function(name) {
        const cont = document.getElementById('editConsVacationLedgerList');
        if (!cont) return;
        const ledger = (consultants[name] && Array.isArray(consultants[name].vacationLedger)) ? consultants[name].vacationLedger : [];
        if (ledger.length === 0) {
            cont.innerHTML = '<p class="text-[10px] font-mono text-[#8a8380] py-1">Sin movimientos registrados aún.</p>';
            return;
        }

        cont.innerHTML = ledger.slice().reverse().map(m => {
            const isReversal = m.type === 'REVERSAL';
            const isAccrual = m.type === 'ACCRUAL';
            const badgeClass = isReversal 
                ? 'bg-[#30d158]/15 text-[#30d158] border-[#30d158]/30' 
                : (isAccrual ? 'bg-[#ee6018]/15 text-[#ee6018] border-[#ee6018]/30' : 'bg-[#ff453a]/15 text-[#ff453a] border-[#ff453a]/30');
            const sign = isReversal || isAccrual ? '+' : '-';
            const daysCount = m.daysRestored || m.daysAccrued || m.daysDeducted || m.days || 1;
            const periodStr = m.startDate && m.endDate ? `${m.startDate} al ${m.endDate}` : (m.date || '');
            const timeStr = m.timestamp ? new Date(m.timestamp).toLocaleDateString('es-MX', { hour: '2-digit', minute: '2-digit' }) : '';

            return `
            <div class="p-1.5 bg-[#171513] border border-[#252220] rounded-[3px] flex items-center justify-between text-[10px] font-mono">
                <div class="flex items-center gap-1.5 min-w-0">
                    <span class="px-1 py-0.2 rounded-[3px] border text-[9px] uppercase font-bold ${badgeClass}">${m.type || 'MOVIMIENTO'}</span>
                    <span class="text-[#eeeeee] truncate">${sign}${daysCount} d ${periodStr ? `(${escapeHtml(periodStr)})` : ''}</span>
                </div>
                <div class="flex items-center gap-2 text-[#8a8380] shrink-0">
                    <span>${m.previousBalance ?? '?'} ➔ <strong class="text-[#eeeeee]">${m.newBalance ?? '?'} d</strong></span>
                    ${timeStr ? `<span class="hidden sm:inline">${timeStr}</span>` : ''}
                </div>
            </div>`;
        }).join('');
    };

    window.previewConsLftDays = function(val) {
        const label = document.getElementById('editConsLftDaysLabel');
        const valSpan = document.getElementById('editConsLftDaysVal');
        const rowApply = document.getElementById('btnApplyLftVacationsRow');
        if (!val) {
            if (label) label.classList.add('hidden');
            if (rowApply) rowApply.classList.add('hidden');
            return;
        }
        const days = typeof window.calculateLftVacationDays === 'function' ? window.calculateLftVacationDays(val) : 0;
        if (valSpan) valSpan.textContent = days;
        if (label) label.classList.remove('hidden');
        if (rowApply) rowApply.classList.remove('hidden');
    };

    window.applyLftDaysToPendingVacations = function() {
        const hireDateVal = document.getElementById('editConsHireDate')?.value;
        const days = typeof window.calculateLftVacationDays === 'function' ? window.calculateLftVacationDays(hireDateVal) : 0;
        const input = document.getElementById('editConsPendingVacations');
        if (input) {
            input.value = days;
            if (typeof window.showToast === 'function') window.showToast(`Días correspondientes por Ley LFT (${days} días) asignados`, false);
        }
    };

    window.closeEditConsultantModal = function() {
        const m = document.getElementById('editConsultantModal');
        if (m) {
            m.classList.add('opacity-0');
            setTimeout(() => m.classList.add('hidden'), 200);
        }
    };

    window.confirmEditConsultant = function() {
        if (currentUserRole === 'Lector') return;
        const oldName = document.getElementById('editConsOldName').value;
        const newName = document.getElementById('editConsName').value.trim();
        const newTitle = document.getElementById('editConsTitle').value.trim();
        const newRole = document.getElementById('editConsRole').value;
        const newColor = document.getElementById('editConsColor').value;

        if (!newName) {
            window.showToast("⚠️ El nombre no puede estar vacío", true);
            return;
        }

        if (newName !== oldName) {
            if (consultants[newName]) {
                window.showToast("⚠️ Ya existe un operador con ese nombre", true);
                return;
            }
            consultants[newName] = Object.assign({}, consultants[oldName]);
            delete consultants[oldName];

            (appData.directProjects || []).forEach(p => {
                let idx = (p.consultants || []).indexOf(oldName);
                if (idx !== -1) p.consultants[idx] = newName;
            });
            (appData.modules || []).forEach(m => {
                (m.projects || []).forEach(p => {
                    let idx = (p.consultants || []).indexOf(oldName);
                    if (idx !== -1) p.consultants[idx] = newName;
                });
            });

            if (activeFilterConsultant === oldName) activeFilterConsultant = newName;
            activeFilterConsultants = activeFilterConsultants.map(c => c === oldName ? newName : c);
            if (localAuthor === oldName) {
                localAuthor = newName;
                localStorage.setItem('sicom_author', newName);
            }
        }

        const targetName = (newName !== oldName) ? newName : oldName;
        consultants[targetName].title = newTitle;
        consultants[targetName].jobTitle = newTitle;
        consultants[targetName].role = newRole;
        consultants[targetName].color = newColor;
        if (localAuthor === targetName) {
            currentUserRole = newRole;
            localStorage.setItem('sicom_role', newRole);
            if (typeof window.applyRolePermissions === 'function') window.applyRolePermissions();
        }

        if (document.getElementById('editConsEmployeeNo')) {
            consultants[targetName].employeeNo = document.getElementById('editConsEmployeeNo').value.trim();
        }
        if (document.getElementById('editConsSchedule')) {
            consultants[targetName].schedule = document.getElementById('editConsSchedule').value.trim();
        }
        if (document.getElementById('editConsLead')) {
            consultants[targetName].lead = document.getElementById('editConsLead').value;
        }
        if (document.getElementById('editConsTeam')) {
            consultants[targetName].team = document.getElementById('editConsTeam').value.trim();
        }
        if (document.getElementById('editConsPendingVacations')) {
            consultants[targetName].pendingVacations = parseInt(document.getElementById('editConsPendingVacations').value) || 0;
        }
        if (document.getElementById('editConsHireDate')) {
            consultants[targetName].hireDate = document.getElementById('editConsHireDate').value.trim();
        }

        // Guardar días de Home Office configurados
        consultants[targetName].homeOfficeDays = [1, 2, 3, 4, 5].filter(d => document.getElementById('editConsHo' + d)?.checked);

        window.saveData(false);
        window.populateConsultantSelects();
        window.renderRegisteredConsultantsList();
        if (isDrawerOpen && currentSelection && currentSelection.id) window.handleGlobalEditSelectionChange();
        window.renderMindMap();
        window.closeEditConsultantModal();
        window.showToast(`Perfil de "${targetName}" guardado`, false);
    };

