    window.populateGlobalEditSelector = function() {
        if (typeof window.renderDrawerRecentProjects === "function") window.renderDrawerRecentProjects();
      const s = document.getElementById('globalEditSelector'); 
      if (!s) return;
      s.innerHTML = `<option value="" class="bg-black text-gray-400">-- Selecciona en el mapa --</option><optgroup label="Núcleo" class="text-white bg-white/10"><option value="core|sicom" class="bg-black text-white">🌐 SICOM</option><option value="direct-hub|hub-direct" class="bg-black text-white">⚡ ${escapeHtml(appData.directHub ? appData.directHub.name : 'PROYECTOS DIRECTOS SICOM')}</option></optgroup>`;
      if (appData.directProjects && appData.directProjects.length > 0) {
        s.innerHTML += `<optgroup label="Directos" class="bg-black text-gray-300">${appData.directProjects.map(p => `<option value="direct-project|${p.id}" class="bg-black text-white">└ ${escapeHtml(p.name)}</option>`).join('')}</optgroup>`;
      }
      if (appData.modules) {
        appData.modules.forEach(m => { 
          s.innerHTML += `<option value="module|${m.id}" class="bg-white/10 text-white font-bold">📦 ${escapeHtml(m.name)}</option>`; 
          if (m.projects && m.projects.length > 0) {
            s.innerHTML += `<optgroup label="Proyectos: ${escapeHtml(m.name)}" class="bg-black text-gray-400">${m.projects.map(p => `<option value="project|${p.id}" class="bg-black text-white">└ ${escapeHtml(p.name)}</option>`).join('')}</optgroup>`;
          }
        });
      }
      if (currentSelection && currentSelection.id) {
        s.value = `${currentSelection.type}|${currentSelection.id}`;
        window.updateEditActiveItemDisplay(currentSelection.type, currentSelection.id);
      }
    };

    window.updateEditActiveItemDisplay = function(type, id) {
      const disp = document.getElementById('editCurrentActiveDisplay');
      const searchBox = document.getElementById('editSearchBoxWrapper');
      if (!disp) return;
      if (!type || !id) {
        disp.classList.add('hidden');
        if (searchBox) searchBox.classList.remove('hidden');
        return;
      }
      let item = null;
      let typeName = 'PROYECTO';
      let parentModName = '';
      let color = '#eeeeee';

      if (type === 'core') {
        item = appData.core;
        typeName = 'NÚCLEO';
        parentModName = 'SISTEMA GENERAL';
        color = '#38bdf8';
      } else if (type === 'direct-hub') {
        item = appData.directHub || { name: 'PROYECTOS DIRECTOS SICOM' };
        typeName = 'AGRUPADOR';
        parentModName = 'DIRECTOS';
        color = (appData.directHub && appData.directHub.color) || '#f59e0b';
      } else if (type === 'module') {
        item = (appData.modules || []).find(m => m.id === id);
        typeName = 'MÓDULO';
        parentModName = 'MÓDULO BASE';
        color = (item && item.color) || '#ee6018';
      } else if (type === 'direct-project') {
        item = (appData.directProjects || []).find(p => p.id === id);
        typeName = 'DIRECTO';
        parentModName = (appData.directHub && appData.directHub.name) || 'PROYECTOS DIRECTOS';
        color = (appData.directHub && appData.directHub.color) || '#f59e0b';
      } else if (type === 'project') {
        (appData.modules || []).forEach(m => {
          const found = (m.projects || []).find(p => p.id === id);
          if (found) {
            item = found;
            parentModName = m.name;
            color = m.color || '#0071e3';
          }
        });
      }

      if (!item) {
        disp.classList.add('hidden');
        if (searchBox) searchBox.classList.remove('hidden');
        return;
      }

      const dot = document.getElementById('editActiveDot');
      if (dot) dot.style.backgroundColor = color;
      const tag = document.getElementById('editActiveTypeTag');
      if (tag) tag.textContent = typeName;
      const parentTag = document.getElementById('editActiveParentModule');
      if (parentTag) parentTag.textContent = parentModName ? `· ${parentModName}` : '';
      const title = document.getElementById('editActiveItemTitle');
      if (title) title.textContent = item.name || 'Sin nombre';

      disp.classList.remove('hidden');
      if (searchBox) searchBox.classList.add('hidden');
    };

    window.handleEditLiveSearch = function(query) {
      const dropdown = document.getElementById('editSearchResultsDropdown');
      const clearBtn = document.getElementById('btnClearEditSearch');
      if (!dropdown) return;
      const q = (query || '').toLowerCase().trim();

      if (clearBtn) {
        if (q) clearBtn.classList.remove('hidden');
        else clearBtn.classList.add('hidden');
      }

      const items = [];
      
      // 1. Core
      items.push({
        type: 'core',
        id: 'sicom',
        name: (appData.core && appData.core.name) || 'SICOM',
        parentName: 'Núcleo Central',
        color: '#38bdf8',
        icon: '🌐',
        badge: 'NÚCLEO'
      });

      // 2. Direct Hub
      const hub = appData.directHub || { id: 'hub-direct', name: 'PROYECTOS DIRECTOS SICOM', color: '#f59e0b' };
      items.push({
        type: 'direct-hub',
        id: hub.id || 'hub-direct',
        name: hub.name,
        parentName: 'Agrupador Directo',
        color: hub.color || '#f59e0b',
        icon: '⚡',
        badge: 'AGRUPADOR'
      });

      // 3. Direct Projects
      (appData.directProjects || []).forEach(p => {
        items.push({
          type: 'direct-project',
          id: p.id,
          name: p.name,
          parentName: hub.name,
          color: hub.color || '#f59e0b',
          icon: '⚡',
          badge: 'DIRECTO'
        });
      });

      // 4. Modules and their projects
      (appData.modules || []).forEach(m => {
        items.push({
          type: 'module',
          id: m.id,
          name: m.name,
          parentName: 'Módulo Base',
          color: m.color || '#0071e3',
          icon: '📦',
          badge: 'MÓDULO'
        });
        (m.projects || []).forEach(p => {
          items.push({
            type: 'project',
            id: p.id,
            name: p.name,
            parentName: m.name,
            color: m.color || '#0071e3',
            icon: '📦',
            badge: 'PROYECTO'
          });
        });
      });

      const filtered = q 
        ? items.filter(it => it.name.toLowerCase().includes(q) || it.parentName.toLowerCase().includes(q))
        : items;

      if (filtered.length === 0) {
        dropdown.innerHTML = `<div class="p-3 text-center text-[#8a8380] font-mono text-[11px] uppercase">No se encontraron coincidencias para "${escapeHtml(q)}"</div>`;
        dropdown.classList.remove('hidden');
        return;
      }

      dropdown.innerHTML = filtered.map(it => {
        const isCurrent = (currentSelection && currentSelection.id === it.id && currentSelection.type === it.type);
        return `
          <button type="button" onclick="window.selectEditItem('${it.type}', '${it.id}')" class="w-full text-left p-2 rounded-[3px] flex items-center justify-between gap-2.5 transition group ${isCurrent ? 'bg-[#ee6018]/15 border border-[#ee6018]/50 text-[#fafafa]' : 'hover:bg-[#1d1a18] text-[#eeeeee] border border-transparent'}">
            <div class="flex items-center gap-2 min-w-0 flex-1">
              <span class="w-2 h-2 rounded-full shrink-0" style="background-color: ${it.color}"></span>
              <span class="text-xs shrink-0">${it.icon}</span>
              <span class="text-xs font-mono truncate group-hover:text-[#fafafa]">${escapeHtml(it.name)}</span>
            </div>
            <div class="flex items-center gap-1.5 shrink-0">
              <span class="text-[9px] font-mono text-[#8a8380] truncate max-w-[120px] hidden sm:inline">${escapeHtml(it.parentName)}</span>
              <span class="text-[8px] font-mono uppercase px-1.5 py-0.5 rounded-[3px] bg-[#101010] border border-[#3d3a39] text-[#8a8380] group-hover:text-[#eeeeee]">${it.badge}</span>
            </div>
          </button>
        `;
      }).join('');

      dropdown.classList.remove('hidden');
    };

    window.selectEditItem = function(type, id) {
      const dropdown = document.getElementById('editSearchResultsDropdown');
      if (dropdown) dropdown.classList.add('hidden');
      const searchInp = document.getElementById('editSearchInput');
      if (searchInp) searchInp.value = '';
      const clearBtn = document.getElementById('btnClearEditSearch');
      if (clearBtn) clearBtn.classList.add('hidden');
      const searchBox = document.getElementById('editSearchBoxWrapper');
      if (searchBox) searchBox.classList.add('hidden');

      const ges = document.getElementById('globalEditSelector');
      if (ges) ges.value = `${type}|${id}`;
      window.selectNode(type, id);
    };

    window.focusEditSearch = function() {
      const disp = document.getElementById('editCurrentActiveDisplay');
      if (disp) disp.classList.add('hidden');
      const searchBox = document.getElementById('editSearchBoxWrapper');
      if (searchBox) searchBox.classList.remove('hidden');
      const inp = document.getElementById('editSearchInput');
      if (inp) {
        inp.value = '';
        inp.focus();
        window.handleEditLiveSearch('');
      }
    };

    window.clearEditSearch = function() {
      const inp = document.getElementById('editSearchInput');
      if (inp) inp.value = '';
      const dropdown = document.getElementById('editSearchResultsDropdown');
      if (dropdown) dropdown.classList.add('hidden');
      const clearBtn = document.getElementById('btnClearEditSearch');
      if (clearBtn) clearBtn.classList.add('hidden');
    };

    window.loadCurrentSelectionToEdit = function() {
      if (currentSelection && currentSelection.id) {
        window.selectEditItem(currentSelection.type, currentSelection.id);
      }
    };

    window.handleEditSearchFocus = function() {
      const inp = document.getElementById('editSearchInput');
      window.handleEditLiveSearch(inp ? inp.value : '');
    };

    window.populateSecondaryModulesChecklist = function(prefix, primaryModId, selectedIds = []) {
      const container = document.getElementById(`${prefix}SecondaryModulesList`);
      if (!container) return;
      const selSet = new Set(Array.isArray(selectedIds) ? selectedIds : []);
      
      const options = [];
      const directId = 'DIRECT';
      if (primaryModId !== directId) {
        options.push({
          id: directId,
          name: appData.directHub ? appData.directHub.name : 'PROYECTOS DIRECTOS SICOM',
          color: (appData.directHub && appData.directHub.color) ? appData.directHub.color : '#f59e0b',
          icon: '⚡'
        });
      }
      
      (appData.modules || []).forEach(m => {
        if (m && m.id && m.id !== primaryModId) {
          options.push({
            id: m.id,
            name: m.name || 'Módulo',
            color: m.color || '#0071e3',
            icon: '📦'
          });
        }
      });

      if (options.length === 0) {
        container.innerHTML = '<div class="text-[10px] font-mono text-[#8a8380] italic py-1 px-0.5">No hay otros módulos disponibles para vincular.</div>';
        const secBadge = document.getElementById(`${prefix}SecBadge`);
        if (secBadge) {
          secBadge.textContent = 'Ninguna';
          secBadge.className = 'font-mono text-[9px] uppercase px-1.5 py-0.2 rounded-[3px] bg-[#1d1a18] text-[#8a8380] border border-[#3d3a39]';
        }
        return;
      }

      const secBadge = document.getElementById(`${prefix}SecBadge`);
      if (secBadge) {
        const count = selSet.size;
        if (count === 0) {
          secBadge.textContent = 'Ninguna';
          secBadge.className = 'font-mono text-[9px] uppercase px-1.5 py-0.2 rounded-[3px] bg-[#1d1a18] text-[#8a8380] border border-[#3d3a39]';
        } else {
          secBadge.textContent = `${count} ${count === 1 ? 'módulo' : 'módulos'}`;
          secBadge.className = 'font-mono text-[9px] uppercase px-1.5 py-0.2 rounded-[3px] bg-[#ee6018]/15 text-[#fafafa] border border-[#ee6018]';
        }
      }

      container.innerHTML = options.map(opt => {
        const isChecked = selSet.has(opt.id) || (opt.id === 'DIRECT' && selSet.has('hub-direct'));
        return `
          <label class="sec-mod-toggle-chip inline-flex items-center gap-1.5 font-mono text-[10px] uppercase px-2.5 py-1.5 rounded-[3px] cursor-pointer transition select-none border ${isChecked ? 'bg-[#ee6018]/15 border-[#ee6018] text-[#fafafa] font-medium' : 'bg-[#101010] border-[#3d3a39] text-[#8a8380] hover:text-[#eeeeee] hover:border-[#4d4947]'}" style="${isChecked ? `border-color: ${opt.color || '#ee6018'};` : ''}">
            <input type="checkbox" value="${escapeHtml(opt.id)}" class="${prefix}SecMod-chk sr-only" ${isChecked ? 'checked' : ''} onchange="window.handleSecondaryModuleCheckboxChange('${prefix}')">
            <span class="w-1.5 h-1.5 rounded-full shrink-0" style="background-color: ${opt.color}"></span>
            <span>${opt.icon} ${escapeHtml(opt.name)}</span>
            ${isChecked ? `<span class="text-[8px] px-1 py-0.2 rounded bg-[#ee6018]/25 text-[#ee6018] font-bold">✓</span>` : ''}
          </label>
        `;
      }).join('');
    };

    window.handleSecondaryModuleCheckboxChange = function(prefix) {
      const selectId = (prefix === 'editProj') ? 'editProjectLocation' : 'newProjLocation';
      const locSel = document.getElementById(selectId);
      const primaryId = locSel ? locSel.value : 'DIRECT';
      const checked = Array.from(document.querySelectorAll(`.${prefix}SecMod-chk:checked`)).map(cb => cb.value);
      window.populateSecondaryModulesChecklist(prefix, primaryId, checked);
    };

    window.renderLocationChips = function(prefix, selectedLocId) {
      const chipsCont = document.getElementById(`${prefix}LocationChips`);
      const badge = document.getElementById(`${prefix}LocActiveBadge`);
      if (!chipsCont) return;

      const options = [
        {
          id: 'DIRECT',
          name: appData.directHub ? appData.directHub.name : 'PROYECTOS DIRECTOS SICOM',
          color: (appData.directHub && appData.directHub.color) || '#f59e0b',
          icon: '⚡'
        }
      ];

      (appData.modules || []).forEach(m => {
        options.push({
          id: m.id,
          name: m.name,
          color: m.color || '#0071e3',
          icon: '📦'
        });
      });

      const current = selectedLocId || 'DIRECT';
      const activeOpt = options.find(o => o.id === current) || options[0];

      if (badge && activeOpt) {
        badge.textContent = activeOpt.name;
        badge.style.borderColor = activeOpt.color;
      }

      chipsCont.innerHTML = options.map(opt => {
        const isSel = (opt.id === current);
        return `
          <button type="button" onclick="window.selectProjectBaseLocation('${prefix}', '${opt.id}')" class="loc-chip inline-flex items-center gap-1.5 font-mono text-[10px] uppercase px-2.5 py-1.5 rounded-[3px] transition border ${isSel ? 'bg-[#eeeeee] text-[#101010] font-semibold border-[#eeeeee]' : 'bg-[#101010] border-[#3d3a39] text-[#8a8380] hover:text-[#eeeeee] hover:border-[#4d4947]'}" title="Asignar como módulo base">
            <span class="w-1.5 h-1.5 rounded-full shrink-0" style="background-color: ${opt.color}"></span>
            <span>${opt.icon} ${escapeHtml(opt.name)}</span>
            ${isSel ? `<span class="text-[8px] px-1 py-0.2 rounded bg-[#101010]/20 text-[#101010] font-bold">BASE</span>` : ''}
          </button>
        `;
      }).join('');
    };

    window.selectProjectBaseLocation = function(prefix, locId) {
      const selectId = (prefix === 'editProj') ? 'editProjectLocation' : 'newProjLocation';
      const s = document.getElementById(selectId);
      if (s) {
        s.value = locId;
        const checkedSec = Array.from(document.querySelectorAll(`.${prefix}SecMod-chk:checked`)).map(cb => cb.value);
        window.populateSecondaryModulesChecklist(prefix, locId, checkedSec);
      }
      window.renderLocationChips(prefix, locId);
    };

    window.populateCompanyChecklist = function(prefix, selectedCompanies = []) {
      const container = document.getElementById(`${prefix}CompaniesList`);
      if (!container) return;
      const selSet = new Set((Array.isArray(selectedCompanies) ? selectedCompanies : []).map(c => String(c).trim().toUpperCase()));
      
      const allComps = window.getAllKnownCompanies ? window.getAllKnownCompanies() : ['AFR', 'AVM', 'TEO', 'TNO', 'ZIN', 'GENERAL'];
      selSet.forEach(c => {
        if (c && !allComps.includes(c)) allComps.push(c);
      });

      const compBadge = document.getElementById(`${prefix}CompBadge`);
      if (compBadge) {
        const count = selSet.size;
        if (count === 0) {
          compBadge.textContent = '0';
          compBadge.className = 'font-mono text-[9px] uppercase px-1.5 py-0.2 rounded-[3px] bg-[#1d1a18] text-[#8a8380] border border-[#3d3a39]';
        } else if (count <= 2) {
          compBadge.textContent = Array.from(selSet).join(', ');
          compBadge.className = 'font-mono text-[9px] uppercase px-1.5 py-0.2 rounded-[3px] bg-[#ee6018]/15 text-[#ee6018] border border-[#ee6018]/40';
        } else {
          compBadge.textContent = `${count} empresas`;
          compBadge.className = 'font-mono text-[9px] uppercase px-1.5 py-0.2 rounded-[3px] bg-[#ee6018]/15 text-[#ee6018] border border-[#ee6018]/40';
        }
      }

      container.innerHTML = allComps.map(comp => {
        const isChecked = selSet.has(comp);
        const style = window.getCompanyStyle ? window.getCompanyStyle(comp) : { color: '#ee6018', bg: 'rgba(238,96,24,0.15)', border: 'rgba(238,96,24,0.3)' };
        return `
          <label class="inline-flex items-center gap-1.5 font-mono text-[10px] uppercase px-2.5 py-1.5 rounded-[3px] cursor-pointer transition select-none border ${isChecked ? 'bg-[#ee6018]/15 border-[#ee6018] text-[#fafafa] font-medium' : 'bg-[#101010] border-[#3d3a39] text-[#8a8380] hover:text-[#eeeeee] hover:border-[#4d4947]'}">
            <input type="checkbox" value="${escapeHtml(comp)}" class="${prefix}Comp-chk sr-only" ${isChecked ? 'checked' : ''} onchange="window.handleCompanyCheckboxChange('${prefix}')">
            <span class="w-1.5 h-1.5 rounded-full shrink-0" style="background-color: ${style.color || '#ee6018'}"></span>
            <span>${escapeHtml(comp)}</span>
            ${isChecked ? `<span class="text-[8px] px-1 py-0.2 rounded bg-[#ee6018]/25 text-[#ee6018] font-bold">✓</span>` : ''}
          </label>
        `;
      }).join('');
    };

    window.handleCompanyCheckboxChange = function(prefix) {
      const checked = Array.from(document.querySelectorAll(`.${prefix}Comp-chk:checked`)).map(cb => cb.value.trim().toUpperCase());
      window.populateCompanyChecklist(prefix, checked);
    };

    window.addCustomCompany = function(prefix) {
      const input = document.getElementById(`${prefix}CustomComp`);
      if (!input) return;
      const val = input.value.trim().toUpperCase();
      if (!val) {
        window.showToast("⚠️ Ingresa el nombre de la empresa", true);
        return;
      }
      input.value = '';
      const currentChecked = Array.from(document.querySelectorAll(`.${prefix}Comp-chk:checked`)).map(cb => cb.value.trim().toUpperCase());
      if (!currentChecked.includes(val)) currentChecked.push(val);
      window.populateCompanyChecklist(prefix, currentChecked);
    };

    window.populateEditProjectLocationSelect = function(currentLoc) { 
      const s = document.getElementById('editProjectLocation'); 
      if (!s) return; 
      s.innerHTML = `<option value="DIRECT">⚡ Directo</option>` + (appData.modules || []).map(m => `<option value="${m.id}">📦 ${escapeHtml(m.name)}</option>`).join(''); 
      const chosen = currentLoc || s.value || 'DIRECT';
      s.value = chosen;
      window.renderLocationChips('editProj', chosen);
    };
    
    window.populateNewProjectLocationSelect = function(preselectedId) { 
      const s = document.getElementById('newProjLocation'); 
      if (!s) return; 
      const prevVal = preselectedId || s.value || 'DIRECT';
      s.innerHTML = `<option value="DIRECT">⚡ Directo</option>` + (appData.modules || []).map(m => `<option value="${m.id}">📦 ${escapeHtml(m.name)}</option>`).join(''); 
      if (prevVal && Array.from(s.options).some(o => o.value === prevVal)) {
        s.value = prevVal;
      }
      window.renderLocationChips('newProj', s.value);
      const checked = Array.from(document.querySelectorAll('.newProjSecMod-chk:checked')).map(cb => cb.value);
      window.populateSecondaryModulesChecklist('newProj', s.value, checked);
      const checkedComps = Array.from(document.querySelectorAll('.newProjComp-chk:checked')).map(cb => cb.value);
      window.populateCompanyChecklist('newProj', checkedComps);
    };

    window.openCreateProjectForModule = function(moduleId) {
      if (currentUserRole === 'Lector') return;
      window.closeInfoCardSafe();
      window.openConfigDrawer();
      window.switchTab('new');
      window.setCreateType('project');
      window.populateNewProjectLocationSelect(moduleId);
      setTimeout(() => {
        const inp = document.getElementById('newProjName');
        if (inp) inp.focus();
      }, 350);
    };
    window.populateConsultantSelects = function() {
      const all = Object.keys(consultants).filter(k => consultants[k].role !== 'Lector');
      const mkChips = (pr) => all.map(n => {
        const cColor = consultants[n]?.color || '#ee6018';
        return `<label class="filter-chip cursor-pointer select-none inline-flex items-center gap-1.5 py-1.5 px-2.5 rounded-[4px] border border-[#3d3a39] bg-[#1a1816] hover:bg-[#24211f] text-[11px] font-mono uppercase text-[#cccccc] transition">
          <input type="checkbox" value="${escapeHtml(n)}" class="${pr}-chk hidden" onchange="this.parentElement.classList.toggle('active', this.checked)">
          <span class="w-2 h-2 rounded-full inline-block shrink-0" style="background-color: ${cColor};"></span>
          <span>${escapeHtml(n)}</span>
        </label>`;
      }).join('');
      const elEdit = document.getElementById('editConsultantsChecks');
      const elNew = document.getElementById('newProjConsultantsChecks');
      if (elEdit) elEdit.innerHTML = mkChips('editProjCons'); 
      if (elNew) elNew.innerHTML = mkChips('newProjCons');
    };
    let activeConsultantRoleFilter = 'ALL';
    window.setConsultantRoleFilter = function(role) {
        activeConsultantRoleFilter = role;
        document.querySelectorAll('.cons-role-pill').forEach(btn => {
            btn.classList.remove('active', 'bg-white/15', 'text-white', 'border-white/20');
            btn.classList.add('text-[#8a8380]', 'bg-[#101010]', 'border-[#3d3a39]');
        });
        const curBtn = document.getElementById(`consRoleFilterBtn-${role}`);
        if (curBtn) {
            curBtn.classList.add('active', 'bg-white/15', 'text-white', 'border-white/20');
            curBtn.classList.remove('text-[#8a8380]', 'bg-[#101010]', 'border-[#3d3a39]');
        }
        window.renderRegisteredConsultantsList();
    };

    window.filterConsultant = function(name) {
        if (!name) return;

        // Conmutador (Toggle): Si ya estaba seleccionado únicamente este consultor, restablecer a vista completa
        if (activeFilterConsultants.length === 1 && activeFilterConsultants[0] === name) {
            window.resetAdvFilters();
            if (isDrawerOpen) window.closeConfigDrawer();
            window.showToast("🗺️ Filtro restablecido: Mostrando todos los proyectos");
            setTimeout(() => {
                if (typeof window.recenterCanvas === 'function') window.recenterCanvas();
            }, 180);
            return;
        }

        // Verificar si tiene proyectos asignados
        let pCount = 0;
        const countProjects = (p) => { if (getProjectConsultants(p).includes(name)) pCount++; };
        (appData.directProjects || []).forEach(countProjects);
        (appData.modules || []).forEach(m => { (m.projects || []).forEach(countProjects); });

        if (pCount === 0) {
            window.showToast(`ℹ️ ${name} no tiene proyectos asignados actualmente`, false);
            return;
        }

        // Establecer filtro exclusivo para este consultor
        activeFilterConsultants = [name];
        activeFilterConsultant = name;

        // Limpiar otros filtros para que no oculten sus proyectos
        activeFilterModules = ['ALL'];
        activeFilterModule = 'ALL';
        activeFilterCompanies = ['ALL'];
        activeFilterCompany = 'ALL';
        activeFilterStatuses = ['ALL'];
        activeFilterStatus = 'ALL';
        activeFilterUrgency = 'ALL';
        activeFilterPriority = 'ALL';
        activeFilterBottleneck = 'ALL';

        // Actualizar chips de filtros y renderizar mapa
        if (typeof window.renderFilterChips === 'function') window.renderFilterChips();
        if (typeof window.handleAdvFilter === 'function') window.handleAdvFilter();

        // Cerrar el Centro de Control para revelar el mapa interactivo
        if (isDrawerOpen) {
            window.closeConfigDrawer();
        }

        window.showToast(`🗺️ Mostrando los ${pCount} proyectos de ${name}`);

        // Centrar y enfocar suavemente en sus nodos
        setTimeout(() => {
            if (typeof window.focusFilteredMindMap === 'function') {
                window.focusFilteredMindMap();
            }
        }, 180);
    };

    window.renderRegisteredConsultantsList = function() {
        const listEl = document.getElementById('registeredConsultantsList');
        if (!listEl) return;
        
        let all = Object.keys(consultants);
        const countBadge = document.getElementById('consultantsCountBadge');
        if (countBadge) countBadge.textContent = all.length;

        // Filtro por rol
        if (activeConsultantRoleFilter !== 'ALL') {
            all = all.filter(n => (consultants[n] && consultants[n].role === activeConsultantRoleFilter));
        }

        // Búsqueda en vivo
        const searchInp = document.getElementById('searchConsultantInput');
        const term = searchInp ? searchInp.value.trim().toLowerCase() : '';
        if (term) {
            all = all.filter(n => {
                const cData = consultants[n] || {};
                const title = (cData.title || '').toLowerCase();
                const role = (cData.role || '').toLowerCase();
                return n.toLowerCase().includes(term) || title.includes(term) || role.includes(term);
            });
        }

        if (all.length === 0) {
            listEl.innerHTML = `<div class="text-center py-10 opacity-50"><p class="font-mono text-[11px] text-[#8a8380] uppercase">No se encontraron operadores.</p></div>`;
            return;
        }

        const todayZero = new Date(new Date().setHours(0,0,0,0)).getTime();

        listEl.innerHTML = all.map(n => {
            const cData = consultants[n] || { color: '#ee6018', role: 'Consultor' };
            
            let pCount = 0;
            let inValCount = 0;
            let overdueCount = 0;

            const checkP = (p) => {
                if (getProjectConsultants(p).includes(n)) {
                    pCount++;
                    if (p.deadline && !isCompletedStatus(p.status)) {
                        const parts = p.deadline.split('-');
                        if (parts.length === 3) {
                            const dt = new Date(parseInt(parts[0], 10), parseInt(parts[1], 10) - 1, parseInt(parts[2], 10)).getTime();
                            if (dt < todayZero) overdueCount++;
                        }
                    }
                    (p.tasks || []).forEach(t => {
                        if ((t.assignee === n || (!t.assignee && getProjectConsultants(p).includes(n))) && t.done === 'pending') {
                            inValCount++;
                        }
                    });
                }
            };

            (appData.directProjects || []).forEach(checkP);
            (appData.modules || []).forEach(m => { (m.projects || []).forEach(checkP); });

            (appData.globalTasks || []).forEach(t => {
                if (t.assignee === n && t.done === 'pending') inValCount++;
            });
            (appData.dailyTasks || []).forEach(t => {
                if (t.assignee === n && t.done === 'pending') inValCount++;
            });

            const initials = n.split(' ').filter(Boolean).map(w => w[0]).join('').substring(0, 2).toUpperCase() || 'OP';

            const displayTitle = cData.title || (
                cData.role === 'Supremo' ? 'Dirección Técnica & Arquitectura' :
                (cData.role === 'Gestor de Proyectos' ? 'Gestión de Proyectos & Auditoría PMO' :
                (cData.role === 'Supervisor' ? 'Supervisor Operativo & Calidad' :
                (cData.role === 'Lector' ? 'Auditoría / Vista Ejecutiva' : 'Consultor Especialista')))
            );

            let roleBadgeStyle = 'text-[#ee6018] bg-[#ee6018]/10 border-[#ee6018]/30';
            let roleIcon = '⚡';
            if (cData.role === 'Supremo') {
                roleBadgeStyle = 'text-[#0071e3] bg-[#0071e3]/10 border-[#0071e3]/30';
                roleIcon = '👑';
            } else if (cData.role === 'Gestor de Proyectos') {
                roleBadgeStyle = 'text-[#3b82f6] bg-[#3b82f6]/10 border-[#3b82f6]/30';
                roleIcon = '📊';
            } else if (cData.role === 'Supervisor') {
                roleBadgeStyle = 'text-[#30d158] bg-[#30d158]/10 border-[#30d158]/30';
                roleIcon = '🛡️';
            } else if (cData.role === 'Lector') {
                roleBadgeStyle = 'text-[#8e8e93] bg-[#8e8e93]/10 border-[#8e8e93]/30';
                roleIcon = '👁️';
            }

            return `
            <div class="flex flex-col w-full p-3 bg-[#1d1a18] rounded-[10px] border border-[#3d3a39] mb-2 hover:border-[#4d4947] transition group" style="border-left: 3px solid ${cData.color};">
                <div class="flex items-center justify-between gap-3">
                    <div class="relative shrink-0">
                        <div class="w-9 h-9 rounded-full bg-[#101010] flex items-center justify-center font-mono font-bold text-[11px] text-[#eeeeee] transition shadow-inner select-none" style="border: 2px solid ${cData.color};" title="Operador: ${escapeHtml(n)}">
                            ${escapeHtml(initials)}
                        </div>
                        <span class="w-2.5 h-2.5 rounded-full bg-[#30d158] absolute bottom-0 right-0 border-2 border-[#1d1a18]" title="Activo"></span>
                    </div>

                    <div class="flex-1 min-w-0">
                        <div class="flex items-center gap-1.5 flex-wrap">
                            <span class="text-xs font-medium text-[#eeeeee] truncate">${escapeHtml(n)}</span>
                            <span class="font-mono text-[9px] uppercase px-1.5 py-0.2 rounded-[3px] border ${roleBadgeStyle}">
                                ${roleIcon} ${escapeHtml(cData.role || 'Consultor')}
                            </span>
                            ${cData.lead ? `<span class="font-mono text-[9px] text-[#10b981] bg-[#10b981]/10 border border-[#10b981]/30 px-1.5 py-0.2 rounded-[3px]">Jefe: ${escapeHtml(cData.lead)}</span>` : ''}
                            ${cData.employeeNo ? `<span class="font-mono text-[9px] text-[#8a8380] bg-[#101010] border border-[#3d3a39] px-1 py-0.2 rounded-[3px]">No. ${escapeHtml(cData.employeeNo)}</span>` : ''}
                        </div>
                        <p class="text-[10px] text-[#8a8380] truncate mt-0.5 font-normal">${escapeHtml(displayTitle)} ${cData.team ? `• ${escapeHtml(cData.team)}` : ''} ${cData.schedule ? `[${escapeHtml(cData.schedule)}]` : ''}</p>
                    </div>

                    <div class="flex items-center gap-1 shrink-0">
                        <button onclick="window.filterConsultant('${jsArg(n)}')" class="p-1.5 text-[#8a8380] hover:text-[#eeeeee] hover:bg-[#101010] rounded-[3px] border border-transparent hover:border-[#3d3a39] transition" title="Ver proyectos en el Mapa">
                            <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="1.75" d="M9 20l-5.447-2.724A1 1 0 013 16.382V5.618a1 1 0 011.447-.894L9 7m0 13l6-3m-6 3V7m6 10l4.553 2.276A1 1 0 0021 18.382V7.618a1 1 0 00-.553-.894L15 4m0 13V4m0 0L9 7"/></svg>
                        </button>
                        <button onclick="openEditConsultantModal('${jsArg(n)}')" class="p-1.5 text-[#8a8380] hover:text-[#eeeeee] hover:bg-[#101010] rounded-[3px] border border-transparent hover:border-[#3d3a39] transition" title="Editar Perfil y Cargo">
                            <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="1.75" d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z"/></svg>
                        </button>
                        <button onclick="openPasswordModal('${jsArg(n)}')" class="p-1.5 text-[#8a8380] hover:text-[#eeeeee] hover:bg-[#101010] rounded-[3px] border border-transparent hover:border-[#3d3a39] transition" title="Seguridad / Cambiar PIN">
                            <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="1.75" d="M15 7a2 2 0 012 2m4 0a6 6 0 01-7.743 5.743L11 17H9v2H7v2H4a1 1 0 01-1-1v-2.586a1 1 0 01.293-.707l5.964-5.964A6 6 0 1121 9z"/></svg>
                        </button>
                        <button onclick="requestDeleteConsultant('${jsArg(n)}')" class="p-1.5 text-[#8a8380] hover:text-[#ee6018] hover:bg-[#101010] rounded-[3px] border border-transparent hover:border-[#ee6018] transition" title="Eliminar Operador">
                            <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="1.75" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
                        </button>
                    </div>
                </div>

                <div class="flex items-center gap-2 mt-2 pt-1.5 border-t border-[#3d3a39]/60 text-[9px] font-mono text-[#8a8380] flex-wrap justify-between">
                    <div class="flex items-center gap-2 flex-wrap">
                        <span class="flex items-center gap-1 text-[#b8b3b0]">
                            <span class="w-1.5 h-1.5 rounded-full" style="background-color: ${cData.color}"></span>
                            ${pCount} ${pCount === 1 ? 'proyecto' : 'proyectos'}
                        </span>
                        ${inValCount > 0 ? `<span class="px-1.5 py-0.2 rounded-[3px] bg-[#ff9f0a]/10 text-[#ff9f0a] border border-[#ff9f0a]/30 flex items-center gap-1">⏳ ${inValCount} en validación</span>` : ''}
                        ${overdueCount > 0 ? `<span class="px-1.5 py-0.2 rounded-[3px] bg-[#ff453a]/10 text-[#ff453a] border border-[#ff453a]/30 flex items-center gap-1">🚨 ${overdueCount} atrasados</span>` : ''}
                    </div>
                    <button type="button" onclick="window.filterConsultant('${jsArg(n)}')" class="text-[9px] uppercase text-[#8a8380] hover:text-[#eeeeee] transition font-mono flex items-center gap-1">
                        <span>Ver en el Mapa</span> <span>→</span>
                    </button>
                </div>
            </div>`;
        }).join('');
    };

    let draggedDocIndex = null;

    window.handleDocDragStart = function(e, idx) {
        draggedDocIndex = idx;
        e.dataTransfer.effectAllowed = 'move';
        e.dataTransfer.setData('text/plain', idx);
        const card = e.currentTarget;
        setTimeout(() => {
            if (card) card.classList.add('is-dragging');
        }, 0);
    };

    window.handleDocDragEnd = function(e) {
        draggedDocIndex = null;
        document.querySelectorAll('.doc-drag-item').forEach(el => {
            el.classList.remove('is-dragging', 'drag-over-top', 'drag-over-bottom');
        });
    };

    window.handleDocDragOver = function(e, idx) {
        e.preventDefault();
        e.dataTransfer.dropEffect = 'move';
        const target = e.currentTarget;
        const rect = target.getBoundingClientRect();
        const midY = rect.top + rect.height / 2;
        if (e.clientY < midY) {
            target.classList.add('drag-over-top');
            target.classList.remove('drag-over-bottom');
        } else {
            target.classList.add('drag-over-bottom');
            target.classList.remove('drag-over-top');
        }
    };

    window.handleDocDragLeave = function(e) {
        const target = e.currentTarget;
        target.classList.remove('drag-over-top', 'drag-over-bottom');
    };

    window.handleDocDrop = function(e, targetIdx) {
        e.preventDefault();
        if (draggedDocIndex === null || draggedDocIndex === targetIdx) {
            window.handleDocDragEnd(e);
            return;
        }
        const target = e.currentTarget;
        const rect = target.getBoundingClientRect();
        const midY = rect.top + rect.height / 2;
        let insertIdx = (e.clientY < midY) ? targetIdx : targetIdx + 1;
        
        const item = globalDocs.splice(draggedDocIndex, 1)[0];
        if (draggedDocIndex < insertIdx) {
            insertIdx--;
        }
        globalDocs.splice(insertIdx, 0, item);
        window.saveData(false);
        window.renderRegisteredDocsList();
    };

    window.getDocPhase = function(doc, idx) {
        if (doc && doc.phase) return doc.phase;
        const name = ((doc && doc.name) || '').toLowerCase();
        if (name.includes('propuesta') || name.includes('contrato') || name.includes('plano') || name.includes('plan de trabajo') || name.includes('alcance')) {
            return 'Fase 1: Contractual';
        }
        if (name.includes('prueba') || name.includes('validación') || name.includes('matriz') || name.includes('qa') || name.includes('testing')) {
            return 'Fase 2: Calidad';
        }
        if (name.includes('comité') || name.includes('capacitación') || name.includes('liberación') || name.includes('factura') || name.includes('cierre')) {
            return 'Fase 3: Cierre';
        }
        return idx < 4 ? 'Fase 1: Contractual' : (idx < 7 ? 'Fase 2: Calidad' : 'Fase 3: Cierre');
    };

    window.registerGlobalDocument = function() { 
        const n = document.getElementById('newDocName').value.trim(); 
        if (!n) {
            window.showToast("⚠️ Ingresa el nombre del documento", true);
            return; 
        }
        const phaseEl = document.getElementById('newDocPhase');
        const phase = phaseEl ? phaseEl.value : 'Fase 1: Contractual';
        globalDocs.push({ id: 'doc_' + Date.now(), name: n, phase: phase }); 
        document.getElementById('newDocName').value = ''; 
        window.saveData(false); 
        window.renderRegisteredDocsList(); 
        window.showToast(`Requisito "${n}" registrado`, false);
    };

    window.renderRegisteredDocsList = function() {
        const listEl = document.getElementById('registeredDocsList');
        if (!listEl) return;

        if (!globalDocs || globalDocs.length === 0) {
            listEl.innerHTML = `<div class="text-center py-10 opacity-50"><p class="font-mono text-[11px] text-[#8a8380] uppercase">No hay documentos base configurados.</p></div>`;
            return;
        }

        let totalProjects = (appData.directProjects || []).length;
        (appData.modules || []).forEach(m => { totalProjects += (m.projects || []).length; });

        listEl.innerHTML = globalDocs.map((d, i) => {
            const phase = window.getDocPhase(d, i);
            let phaseStyle = 'text-[#5ac8fa] bg-[#5ac8fa]/10 border-[#5ac8fa]/30';
            if (phase.includes('Calidad')) {
                phaseStyle = 'text-[#ffd60a] bg-[#ffd60a]/10 border-[#ffd60a]/30';
            } else if (phase.includes('Cierre')) {
                phaseStyle = 'text-[#a0ca92] bg-[#a0ca92]/10 border-[#a0ca92]/30';
            }

            let validatedIn = 0;
            (appData.directProjects || []).forEach(p => {
                if (p.docs && p.docs[d.id] && (p.docs[d.id].checked || (p.docs[d.id].na && p.docs[d.id].naValidated))) validatedIn++;
            });
            (appData.modules || []).forEach(m => {
                (m.projects || []).forEach(p => {
                    if (p.docs && p.docs[d.id] && (p.docs[d.id].checked || (p.docs[d.id].na && p.docs[d.id].naValidated))) validatedIn++;
                });
            });
            const pct = totalProjects > 0 ? Math.round((validatedIn / totalProjects) * 100) : 0;

            return `
            <div class="doc-drag-item flex flex-col p-2.5 bg-[#1d1a18] rounded-[10px] border border-[#3d3a39] mb-2 hover:border-[#4d4947] transition select-none"
                 draggable="true"
                 ondragstart="handleDocDragStart(event, ${i})"
                 ondragend="handleDocDragEnd(event)"
                 ondragover="handleDocDragOver(event, ${i})"
                 ondragleave="handleDocDragLeave(event)"
                 ondrop="handleDocDrop(event, ${i})">
                
                <div class="flex items-center gap-2">
                    <div class="cursor-grab active:cursor-grabbing text-[#4d4947] hover:text-[#8a8380] transition p-1 shrink-0" title="Arrastra hacia arriba o abajo para reordenar">
                        <svg class="w-3.5 h-3.5" fill="currentColor" viewBox="0 0 24 24"><circle cx="9" cy="6" r="1.5"/><circle cx="15" cy="6" r="1.5"/><circle cx="9" cy="12" r="1.5"/><circle cx="15" cy="12" r="1.5"/><circle cx="9" cy="18" r="1.5"/><circle cx="15" cy="18" r="1.5"/></svg>
                    </div>

                    <span class="font-mono text-[9px] text-[#b8b3b0] bg-[#101010] px-1.5 py-0.5 rounded-[3px] shrink-0 border border-[#3d3a39] select-none">
                        ${String(i+1).padStart(2, '0')}
                    </span>

                    <div class="flex-1 min-w-0">
                        <input type="text" value="${escapeHtml(d.name)}" 
                               onchange="globalDocs[${i}].name=this.value; saveData(false);" 
                               class="bg-transparent border border-transparent hover:border-[#3d3a39] focus:border-[#eeeeee] rounded-[3px] text-xs text-[#eeeeee] font-normal w-full p-1 focus:outline-none transition" 
                               title="Clic para editar el nombre">
                    </div>

                    <div class="flex items-center gap-0.5 shrink-0">
                        <button onclick="moveDoc(${i}, -1)" ${i === 0 ? 'disabled' : ''} class="p-1 rounded-[3px] transition ${i === 0 ? 'opacity-20 cursor-not-allowed text-[#4d4947]' : 'text-[#8a8380] hover:text-[#eeeeee] hover:bg-[#101010]'}" title="Subir">
                            <svg class="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M5 15l7-7 7 7"/></svg>
                        </button>
                        <button onclick="moveDoc(${i}, 1)" ${i === globalDocs.length - 1 ? 'disabled' : ''} class="p-1 rounded-[3px] transition ${i === globalDocs.length - 1 ? 'opacity-20 cursor-not-allowed text-[#4d4947]' : 'text-[#8a8380] hover:text-[#eeeeee] hover:bg-[#101010]'}" title="Bajar">
                            <svg class="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 9l-7 7-7-7"/></svg>
                        </button>
                    </div>

                    <button onclick="deleteDoc('${d.id}')" class="p-1 text-[#8a8380] hover:text-[#ee6018] hover:bg-[#101010] rounded-[3px] transition shrink-0" title="Eliminar requisito">
                        <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="1.75" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
                    </button>
                </div>

                <div class="flex items-center justify-between text-[9px] font-mono mt-1.5 pt-1.5 border-t border-[#3d3a39]/60 text-[#8a8380] pl-6">
                    <span class="px-1.5 py-0.2 rounded-[3px] border ${phaseStyle}">${escapeHtml(phase)}</span>
                    <span class="text-[#8a8380]">Validado en <b class="text-[#eeeeee]">${validatedIn}/${totalProjects}</b> proyectos (${pct}%)</span>
                </div>
            </div>`;
        }).join('');
    };

    window.moveDoc = function(idx, dir) { 
        if(idx+dir < 0 || idx+dir >= globalDocs.length) return; 
        const t = globalDocs[idx]; 
        globalDocs[idx] = globalDocs[idx+dir]; 
        globalDocs[idx+dir] = t; 
        window.saveData(false); 
        window.renderRegisteredDocsList(); 
    };

    window.deleteDoc = function(id) { 
        globalDocs = globalDocs.filter(d => d.id !== id); 
        window.saveData(false); 
        window.renderRegisteredDocsList(); 
    };

    let activePriorityConsultantTab = null;
    window.setPriorityConsultantTab = function(cons) {
        activePriorityConsultantTab = cons;
        window.renderPriorityDrawer();
        const c = document.getElementById('priorityListContainer');
        if (c) c.scrollTop = 0;
    };

    window.renderPriorityDrawer = function() {
        const c = document.getElementById('priorityListContainer');
        const tabsBar = document.getElementById('priorityTabsBar');
        if (!c) return;
        const all = (!activeFilterConsultants.includes('ALL') && activeFilterConsultants.length > 0) ? activeFilterConsultants : Object.keys(consultants);
        const statusMatches = (p) => (activeFilterStatuses.includes('ALL') || activeFilterStatuses.length === 0 || activeFilterStatuses.includes(p.status));
        const companyMatches = (p) => (activeFilterCompanies.includes('ALL') || activeFilterCompanies.length === 0 || window.getProjectCompanies(p).some(comp => activeFilterCompanies.includes(comp)));
        const isModAllPrio = activeFilterModules.includes('ALL') || activeFilterModules.length === 0;
        const selModsPrio = new Set(activeFilterModules.filter(x => x !== 'ALL').map(normModId));
        const moduleMatches = (p, modId) => {
            if (isModAllPrio) return true;
            const pPrim = normModId(modId);
            const pSecs = (Array.isArray(p.secondaryModules) ? p.secondaryModules : []).map(normModId);
            const allMods = new Set([pPrim, ...pSecs].filter(Boolean));
            if (moduleFilterMode === 'CORRELATED' && selModsPrio.size >= 2) {
                return [...allMods].filter(m => selModsPrio.has(m)).length >= 2;
            }
            return selModsPrio.has(pPrim);
        };

        const groups = [];
        all.forEach(cons => {
            const cData = consultants[cons];
            if (!cData) return;
            let projs = [];
            appData.directProjects.forEach(p => { if (getProjectConsultants(p).includes(cons) && statusMatches(p) && companyMatches(p) && moduleMatches(p, 'hub-direct')) projs.push({ ...p, parentName: appData.directHub.name, pType: 'direct-project' }); });
            appData.modules.forEach(m => { (m.projects || []).forEach(p => { if (getProjectConsultants(p).includes(cons) && statusMatches(p) && companyMatches(p) && moduleMatches(p, m.id)) projs.push({ ...p, parentName: m.name, pType: 'project' }); }); });
            if (projs.length === 0) return;
            projs.sort((a, b) => parseFloat(a.priority || 0) - parseFloat(b.priority || 0));
            groups.push({ cons, cData, projs });
        });

        if (groups.length === 0) {
            if (tabsBar) { tabsBar.innerHTML = ''; tabsBar.classList.add('hidden'); }
            c.innerHTML = `<div class="flex flex-col items-center justify-center py-20 text-center opacity-50"><svg class="w-12 h-12 text-[#8a8380] mb-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="1.5" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-6 9l2 2 4-4"/></svg><p class="font-mono text-xs text-[#b8b3b0] uppercase">Sin coincidencias.</p></div>`;
            return;
        }

        const validNames = groups.map(g => g.cons);
        if (!activePriorityConsultantTab || (activePriorityConsultantTab !== 'ALL' && !validNames.includes(activePriorityConsultantTab))) {
            activePriorityConsultantTab = groups[0].cons;
        }

        if (tabsBar) {
            if (groups.length > 1) {
                tabsBar.classList.remove('hidden');
                const totalProjs = groups.reduce((acc, g) => acc + g.projs.length, 0);
                const isAllAct = activePriorityConsultantTab === 'ALL';
                
                let tabsHtml = `<div class="space-y-2.5">
                    <div class="flex items-center justify-between">
                        <span class="font-mono text-[10px] text-[#8a8380] uppercase tracking-wider">Filtrar por Consultor</span>
                        <span class="font-mono text-[10px] text-[#ee6018] uppercase font-semibold">${groups.length} Consultores · ${totalProjs} Proys</span>
                    </div>

                    <!-- BOTÓN MASTER: VER TODOS LOS CONSULTORES (SIEMPRE VISIBLE ARRIBA) -->
                    <button type="button" onclick="window.setPriorityConsultantTab('ALL')" class="w-full px-3 py-2 rounded-[3px] border font-mono text-[11px] uppercase transition flex items-center justify-between select-none ${isAllAct ? 'bg-[#ee6018] text-[#fafafa] border-[#ee6018] font-semibold' : 'bg-[#101010] hover:bg-[#1d1a18] text-[#eeeeee] border-[#3d3a39]'}">
                        <div class="flex items-center gap-2">
                            <span class="w-2 h-2 rounded-full ${isAllAct ? 'bg-[#fafafa]' : 'bg-[#ee6018]'}"></span>
                            <span>🌐 Ver Todos los Consultores</span>
                        </div>
                        <span class="text-[10px] px-2 py-0.5 rounded-[3px] ${isAllAct ? 'bg-[#101010]/30 text-[#fafafa]' : 'bg-[#101010] text-[#ee6018] border border-[#3d3a39]'} font-semibold">${totalProjs}</span>
                    </button>

                    <!-- CUADRÍCULA DE CONSULTORES INDIVIDUALES -->
                    <div class="grid grid-cols-2 gap-1.5 max-h-36 overflow-y-auto scrollbar-thin pr-0.5">`;

                groups.forEach(g => {
                    const isAct = activePriorityConsultantTab === g.cons;
                    const borderStyle = isAct ? `border-color: ${g.cData.color}; background-color: #1d1a18; box-shadow: 0 0 0 1px ${g.cData.color};` : `border-color: #3d3a39; background-color: #101010;`;
                    tabsHtml += `<button type="button" onclick="window.setPriorityConsultantTab('${jsArg(g.cons)}')" class="px-2.5 py-1.5 rounded-[3px] border text-left transition flex items-center justify-between gap-1.5 hover:bg-[#1d1a18]" style="${borderStyle}">
                        <div class="flex items-center gap-1.5 min-w-0">
                            <span class="w-2 h-2 rounded-full shrink-0" style="background-color: ${g.cData.color}"></span>
                            <span class="font-mono text-[10px] uppercase truncate ${isAct ? 'text-[#eeeeee] font-medium' : 'text-[#b8b3b0]'}">${escapeHtml(g.cons)}</span>
                        </div>
                        <span class="font-mono text-[9px] px-1.5 py-0.2 rounded-[3px] bg-[#101010] border border-[#3d3a39] shrink-0" style="color: ${isAct ? g.cData.color : '#8a8380'}">${g.projs.length}</span>
                    </button>`;
                });

                tabsHtml += `</div>
                </div>`;
                tabsBar.innerHTML = tabsHtml;
            } else {
                tabsBar.innerHTML = '';
                tabsBar.classList.add('hidden');
            }
        }

        const renderProjectCards = (projs, cData) => projs.map(p => {
            let sIco = p.status === 'En Progreso' ? '🚀' : (isCompletedStatus(p.status) ? '✅' : (p.status === 'No Iniciado' ? '⏸️' : '⏳'));
            let over = false;
            if (p.deadline && !isCompletedStatus(p.status)) {
                const [y, m, d] = p.deadline.split('-');
                if (new Date(y, m - 1, d) < new Date(new Date().setHours(0, 0, 0, 0))) over = true;
            }
            const pComps = window.getProjectCompanies(p);
            const compBadges = pComps.map(comp => {
                const st = window.getCompanyStyle ? window.getCompanyStyle(comp) : { color: '#ee6018', bg: 'rgba(238,96,24,0.15)', border: 'rgba(238,96,24,0.3)', icon: '🏢' };
                return `<span class="font-mono text-[9px] uppercase px-1.5 py-0.5 rounded-[3px] border truncate max-w-[90px]" style="background-color:${st.bg}; color:${st.color}; border-color:${st.border};" title="${escapeHtml(comp)}">${st.icon} ${escapeHtml(comp)}</span>`;
            }).join('');
            const tk = (typeof getProjectTicket === 'function' ? getProjectTicket(p) : (p.ticket || '')).trim().replace(/^#+/, '');
            const tkBadge = tk ? `<span class="inline-flex items-center gap-0.5 font-mono text-[9px] uppercase px-1.5 py-0.5 rounded-[3px] bg-yellow-200 text-yellow-900 font-semibold border border-yellow-400 shrink-0">🎫 #${escapeHtml(tk)}</span>` : '';
            const prioVal = parseInt(p.priority, 10) || 1;
            return `<div class="bg-[#1d1a18] border ${over ? 'border-[#ee6018]' : 'border-[#3d3a39] hover:border-[#eeeeee]'} rounded-[10px] p-3.5 flex gap-3 transition-colors cursor-pointer group select-none" style="border-left: 3px solid ${over ? '#ee6018' : cData.color};" onclick="window.selectNode('${p.pType}', '${p.id}')"><div class="flex flex-col items-center shrink-0 w-9 pt-0.5" onclick="event.stopPropagation()"><div class="font-mono text-base font-bold text-center" style="color: ${cData.color}">*${prioVal}</div><div class="flex items-center mt-1 bg-[#101010] border border-[#3d3a39] rounded-[3px] overflow-hidden"><button type="button" onclick="window.adjustProjectPriority('${p.pType}', '${p.id}', -1, event)" class="px-1 py-0.5 hover:bg-[#3d3a39] text-[#b8b3b0] hover:text-[#fafafa] text-[9px] leading-none transition" title="Subir prioridad (ej. *2 ➔ *1)">▲</button><button type="button" onclick="window.adjustProjectPriority('${p.pType}', '${p.id}', 1, event)" class="px-1 py-0.5 hover:bg-[#3d3a39] text-[#b8b3b0] hover:text-[#fafafa] text-[9px] leading-none transition border-l border-[#3d3a39]" title="Bajar prioridad (ej. *1 ➔ *2)">▼</button></div></div><div class="flex-1 min-w-0"><div class="flex items-center justify-between gap-1 mb-1"><h4 class="text-sm font-normal text-[#eeeeee] leading-tight group-hover:text-[#fafafa] transition truncate">${over ? '⚠️ ' : ''}${escapeHtml(p.name)}</h4><div class="flex items-center gap-1 shrink-0" onclick="event.stopPropagation()"><button type="button" onclick="window.jumpToMapNode('${p.pType}', '${p.id}', event)" class="px-1.5 py-0.5 rounded-[3px] bg-[#101010] hover:bg-[#ee6018] hover:text-[#101010] border border-[#3d3a39] text-[#b8b3b0] font-mono text-[8px] uppercase transition" title="Ver en el mapa">Mapa ↗</button></div></div><p class="font-mono text-[10px] text-[#8a8380] uppercase truncate">└ ${escapeHtml(p.parentName)}</p><div class="flex flex-wrap items-center gap-1.5 mt-2">${tkBadge}${compBadges}<span class="font-mono text-[9px] uppercase px-2 py-0.5 rounded-[3px] bg-[#101010] border border-[#3d3a39] text-[#b8b3b0]">${sIco} ${p.status || 'Pendiente'} (${p.progress || 0}%)</span>${p.deadline ? `<span class="font-mono text-[9px] uppercase ${over ? 'text-[#ee6018] border-[#ee6018]/50' : 'text-[#b8b3b0] border-[#3d3a39]'} bg-[#101010] border px-2 py-0.5 rounded-[3px]">📅 ${p.deadline}</span>` : ''}</div></div></div>`;
        }).join('');

        let h = '';
        const visibleGroups = (groups.length > 1 && activePriorityConsultantTab !== 'ALL')
            ? groups.filter(g => g.cons === activePriorityConsultantTab)
            : groups;

        if (groups.length > 1 && activePriorityConsultantTab === 'ALL') {
            visibleGroups.forEach(g => {
                h += `<div class="bg-[#101010] border border-[#3d3a39] rounded-[10px] overflow-hidden mb-3.5 block shrink-0">
                    <div class="flex items-center justify-between p-3.5 bg-[#1d1a18] border-b border-[#3d3a39]" style="border-left: 3px solid ${g.cData.color};">
                        <div class="flex items-center gap-2.5 min-w-0">
                            <span class="w-2.5 h-2.5 rounded-full shrink-0" style="background-color: ${g.cData.color}"></span>
                            <span class="font-mono text-[11px] uppercase text-[#eeeeee] font-semibold tracking-wide truncate">${escapeHtml(g.cons)}</span>
                        </div>
                        <span class="bg-[#101010] text-[#b8b3b0] px-2 py-0.5 rounded-[3px] font-mono text-[10px] border border-[#3d3a39] shrink-0 font-medium">${g.projs.length} PROYS</span>
                    </div>
                    <div class="p-3 space-y-2.5 bg-[#101010]/40">${renderProjectCards(g.projs, g.cData)}</div>
                </div>`;
            });
        } else {
            visibleGroups.forEach(g => {
                h += `<div class="mb-4"><div class="flex items-center gap-2 mb-3 px-1"><span class="w-2.5 h-2.5 rounded-full shrink-0" style="background-color: ${g.cData.color}"></span><h3 class="font-mono text-[11px] uppercase text-[#eeeeee] truncate">${escapeHtml(g.cons)}</h3><span class="bg-[#1d1a18] text-[#b8b3b0] px-2 py-0.5 rounded-[3px] font-mono text-[10px] ml-auto border border-[#3d3a39]">${g.projs.length} PROYS</span></div><div class="space-y-2.5">${renderProjectCards(g.projs, g.cData)}</div></div>`;
            });
        }
        c.innerHTML = h;
    }


    // =========================================================================
    // VISTA PRINCIPAL DEL ESPACIO DE TRABAJO (MAPA MENTAL vs TABLERO DE PRIORIDADES)
    // =========================================================================
    let mainWorkspaceViewMode = 'map'; // 'map' | 'priority'
    let priorityBoardGroupBy = 'consultant'; // 'consultant' | 'tier'


    window.toggleCanvasSpeedDial = function() {
        const dock = document.getElementById('canvasToolsDock');
        const trig = document.getElementById('canvasSpeedDialTrigger');
        if (!dock) return;
        const isOpen = dock.classList.contains('csd-open');
        dock.classList.toggle('csd-open', !isOpen);
        if (trig) trig.setAttribute('aria-expanded', !isOpen ? 'true' : 'false');
    };

    window.closeCanvasSpeedDial = function() {
        const dock = document.getElementById('canvasToolsDock');
        const trig = document.getElementById('canvasSpeedDialTrigger');
        if (dock) dock.classList.remove('csd-open');
        if (trig) trig.setAttribute('aria-expanded', 'false');
    };

    document.addEventListener('click', function(e) {
        const dock = document.getElementById('canvasToolsDock');
        if (dock && dock.classList.contains('csd-open') && !dock.contains(e.target)) {
            window.closeCanvasSpeedDial();
        }
    });

    document.addEventListener('keydown', function(e) {
        if (e.key === 'Escape') {
            window.closeCanvasSpeedDial();
        }
    });

    // === SISTEMA DE GESTOS ANDROID & HISTORIAL DE NAVEGACIÓN (SAMSUNG S24 ULTRA) ===
    let _isSelfNavigatingBack = false;

    window.pushNavigationState = function(stateName) {
        try {
            history.pushState({ eosaPanel: stateName, time: Date.now() }, '');
        } catch(e) {}
    };

    window.initNavigationGestures = function() {
        try {
            history.replaceState({ eosaPanel: 'root', view: 'map' }, '');
        } catch(e) {}

        window.addEventListener('popstate', function(e) {
            if (_isSelfNavigatingBack) {
                _isSelfNavigatingBack = false;
                return;
            }

            // 1. Modales emergentes secundarios (comisión, vacaciones, día de calendario, confirmaciones, dashboards)
            const subModals = [
                { id: 'commissionModal', close: () => typeof window.closeCommissionModal === 'function' && window.closeCommissionModal() },
                { id: 'vacationModal', close: () => typeof window.closeVacationModal === 'function' && window.closeVacationModal() },
                { id: 'calendarDayModal', close: () => typeof window.closeCalendarDayModal === 'function' && window.closeCalendarDayModal() },
                { id: 'executiveDashboardModal', close: () => typeof window.closeExecutiveDashboard === 'function' && window.closeExecutiveDashboard() },
                { id: 'pwaInstallGuideModal', close: () => typeof window.closePwaInstallGuide === 'function' && window.closePwaInstallGuide() },
                { id: 'projectModal', close: () => typeof window.closeModal === 'function' && window.closeModal() },
                { id: 'editConsultantModal', close: () => typeof window.closeEditConsultantModal === 'function' && window.closeEditConsultantModal() },
                { id: 'globalTaskModal', close: () => typeof window.closeGlobalTaskModal === 'function' && window.closeGlobalTaskModal() },
                { id: 'taskFeedbackModal', close: () => typeof window.closeTaskFeedbackModal === 'function' && window.closeTaskFeedbackModal() },
                { id: 'manualModal', close: () => typeof window.closeManual === 'function' && window.closeManual() },
                { id: 'passwordModal', close: () => typeof window.closePasswordModal === 'function' && window.closePasswordModal() }
            ];

            for (const m of subModals) {
                const el = document.getElementById(m.id);
                if (el && !el.classList.contains('hidden')) {
                    m.close();
                    return;
                }
            }

            // 2. Menú de creación móvil superior
            const mobileTopMenu = document.getElementById('mobileTopCreateMenu');
            if (mobileTopMenu && !mobileTopMenu.classList.contains('hidden')) {
                if (typeof window.closeMobileTopCreateMenu === 'function') window.closeMobileTopCreateMenu();
                return;
            }

            // 3. Ficha de proyecto seleccionada (infoCard)
            const infoCard = document.getElementById('infoCard');
            if (infoCard && !infoCard.classList.contains('hidden')) {
                if (typeof window.closeInfoCardSafe === 'function') {
                    window.closeInfoCardSafe();
                }
                return;
            }

            // 4. Cajones laterales (Explorar, Tareas, Configuración)
            if (typeof isFilterDrawerOpen !== 'undefined' && isFilterDrawerOpen) {
                if (typeof window.closeFilterDrawer === 'function') window.closeFilterDrawer();
                return;
            }
            if (typeof isDailyDrawerOpen !== 'undefined' && isDailyDrawerOpen) {
                if (typeof window.closeDailyDrawer === 'function') window.closeDailyDrawer();
                return;
            }
            if (typeof isDrawerOpen !== 'undefined' && isDrawerOpen) {
                if (typeof window.closeConfigDrawer === 'function') window.closeConfigDrawer();
                return;
            }

            // 5. Modal de Rol & Prenómina (attendanceModal)
            const attM = document.getElementById('attendanceModal');
            if (attM && !attM.classList.contains('hidden')) {
                if (typeof window.closeAttendanceModal === 'function') window.closeAttendanceModal();
                return;
            }

            // 6. Si estamos en Calendario o Prioridades, regresar al Mapa Mental principal
            if (typeof mainWorkspaceViewMode !== 'undefined' && mainWorkspaceViewMode !== 'map') {
                if (typeof window.switchMainWorkspaceView === 'function') {
                    window.switchMainWorkspaceView('map');
                }
                return;
            }

            // 7. Si ya estamos en la raíz del mapa, re-empujar el estado para que un siguiente swipe no salga de la app accidentalmente
            try {
                history.pushState({ eosaPanel: 'root', view: 'map' }, '');
            } catch(e) {}
        });
    };
    try { window.initNavigationGestures(); } catch(e) {}

    // === GESTOR GLOBAL DE ESTADO DE NAVEGACIÓN EN EL DOCK INFERIOR MÓVIL (5 ACCESOS PERMANENTES) ===
    window.syncMobileDockState = function(activeMode) {
        if (!activeMode) activeMode = mainWorkspaceViewMode || 'map';
        const mInact = "flex-1 flex flex-col items-center justify-center py-1 px-1 font-mono uppercase text-[9px] tracking-[-0.24px] text-[#8a8380] hover:text-[#eeeeee] transition cursor-pointer relative group";
        const mAct = "flex-1 flex flex-col items-center justify-center py-1 px-1 font-mono uppercase text-[9px] tracking-[-0.24px] text-[#fafafa] font-medium transition cursor-pointer relative group";

        const mBtnMap = document.getElementById('mobileBtnViewModeMap');
        const mBtnTimeline = document.getElementById('mobileBtnViewModeTimeline');
        const mBtnExplore = document.getElementById('mobileBtnBottomExplore');
        const mBtnTasks = document.getElementById('mobileBtnBottomDailyTasks');
        const mBtnAttendance = document.getElementById('mobileBtnBottomAttendance');
        const mBtnPrio = document.getElementById('mobileBtnViewModePriority');

        if (mBtnMap) mBtnMap.className = (activeMode === 'map') ? mAct : mInact;
        if (mBtnTimeline) mBtnTimeline.className = (activeMode === 'timeline' || activeMode === 'priority') ? mAct : mInact;
        if (mBtnExplore) mBtnExplore.className = (activeMode === 'explore') ? mAct : mInact;
        if (mBtnTasks) mBtnTasks.className = (activeMode === 'tasks') ? mAct : mInact;
        if (mBtnAttendance) mBtnAttendance.className = (activeMode === 'attendance') ? mAct : mInact;
        if (mBtnPrio) mBtnPrio.className = (activeMode === 'priority') ? mAct : mInact;

        const dockIndMap = document.getElementById('mobileDockIndicatorMap');
        const dockIndTimeline = document.getElementById('mobileDockIndicatorTimeline');
        const dockIndExplore = document.getElementById('mobileDockIndicatorExplore');
        const dockIndTasks = document.getElementById('mobileDockIndicatorTasks');
        const dockIndAttendance = document.getElementById('mobileDockIndicatorAttendance');
        const dockIndPrio = document.getElementById('mobileDockIndicatorPriority');

        if (dockIndMap) dockIndMap.classList.toggle('hidden', activeMode !== 'map');
        if (dockIndTimeline) dockIndTimeline.classList.toggle('hidden', activeMode !== 'timeline' && activeMode !== 'priority');
        if (dockIndExplore) dockIndExplore.classList.toggle('hidden', activeMode !== 'explore');
        if (dockIndTasks) dockIndTasks.classList.toggle('hidden', activeMode !== 'tasks');
        if (dockIndAttendance) dockIndAttendance.classList.toggle('hidden', activeMode !== 'attendance');
        if (dockIndPrio) dockIndPrio.classList.toggle('hidden', activeMode !== 'priority');
    };

    window.switchMainWorkspaceView = function(mode) {
        mainWorkspaceViewMode = mode;
        try {
            sessionStorage.setItem('sicom_active_view_mode', mode);
        } catch(e) {}
        if (mode !== 'map' && typeof window.pushNavigationState === 'function') {
            window.pushNavigationState('view_' + mode);
        }
        const btnMap = document.getElementById('btnViewModeMap');
        const btnPrio = document.getElementById('btnViewModePriority');
        const btnTimeline = document.getElementById('btnViewModeTimeline');
        const svgCanvas = document.getElementById('mindmapCanvas');
        const boardView = document.getElementById('priorityBoardView');
        const timelineView = document.getElementById('timelineBoardView');
        const dock = document.getElementById('canvasToolsDock');
        const actFilterPill = document.getElementById('activeFilterPill');
        const btnDaily = document.getElementById('btnDailyTasks');
        const speedDial = document.getElementById('speedDial');

        // Cerrar cajones o modales flotantes al cambiar de vista desde el dock
        if (typeof isDailyDrawerOpen !== 'undefined' && isDailyDrawerOpen && typeof window.closeDailyDrawer === 'function') {
            window.closeDailyDrawer();
            isDailyDrawerOpen = false;
        }
        if (typeof isFilterDrawerOpen !== 'undefined' && isFilterDrawerOpen && typeof window.closeFilterDrawer === 'function') {
            window.closeFilterDrawer();
        }
        if (typeof window.closeAttendanceModal === 'function') {
            const attM = document.getElementById('attendanceModal');
            if (attM && !attM.classList.contains('hidden')) window.closeAttendanceModal();
        }
        if (typeof isDrawerOpen !== 'undefined' && isDrawerOpen && typeof window.closeConfigDrawer === 'function') {
            window.closeConfigDrawer();
        }

        const setActiveTabStyle = (activeMode) => {
            // Conmutador de escritorio (Header)
            const dInact = "px-2 sm:px-2.5 py-1 rounded-[3px] font-mono uppercase text-[10px] sm:text-[11px] tracking-[-0.24px] flex items-center gap-1.5 transition text-[#b8b3b0] hover:text-[#eeeeee] cursor-pointer";
            const dAct = "px-2 sm:px-2.5 py-1 rounded-[3px] font-mono uppercase text-[10px] sm:text-[11px] tracking-[-0.24px] flex items-center gap-1.5 transition bg-[#eeeeee] text-[#101010] font-medium cursor-pointer";
            if (btnMap) btnMap.className = (activeMode === 'map') ? dAct : dInact;
            if (btnPrio) btnPrio.className = (activeMode === 'priority') ? dAct : dInact;
            if (btnTimeline) btnTimeline.className = (activeMode === 'timeline') ? dAct : dInact;
            const btnTasks = document.getElementById('btnViewModeTasks');
            if (btnTasks) btnTasks.classList.add('hidden');

            // Sincronizar dock inferior móvil (5 accesos)
            window.syncMobileDockState(activeMode);

            // Control flotante de centrado rápido sobre el canvas
            const quickRecenter = document.getElementById('canvasQuickControls');
            if (quickRecenter) quickRecenter.classList.toggle('hidden', activeMode !== 'map');

            // Menú desplegable móvil (3 puntos)
            const badge = document.getElementById('mobileMenuCurrentViewBadge');
            if (badge) {
                badge.textContent = (activeMode === 'priority') ? 'PRIORIDADES' : (activeMode === 'timeline') ? 'CALENDARIO' : 'MAPA';
            }
            const indMap = document.getElementById('mobileMenuIndicatorMap');
            const indPrio = document.getElementById('mobileMenuIndicatorPriority');
            const indTimeline = document.getElementById('mobileMenuIndicatorTimeline');
            if (indMap) indMap.classList.toggle('hidden', activeMode !== 'map');
            if (indPrio) indPrio.classList.toggle('hidden', activeMode !== 'priority');
            if (indTimeline) indTimeline.classList.toggle('hidden', activeMode !== 'timeline');
        };

        if (mode === 'priority') {
            if (typeof window.closeCanvasSpeedDial === 'function') window.closeCanvasSpeedDial();
            if (typeof window.closeSpeedDial === 'function') window.closeSpeedDial();
            if (typeof window.closePriorityCreateMenu === 'function') window.closePriorityCreateMenu();
            if (typeof window.closeCalendarCreateMenu === 'function') window.closeCalendarCreateMenu(); if (typeof window.closeMobileTopCreateMenu === 'function') window.closeMobileTopCreateMenu();
            setActiveTabStyle('priority');
            if (svgCanvas) svgCanvas.classList.add('hidden');
            if (timelineView) timelineView.classList.add('hidden');
            if (dock) dock.classList.add('hidden');
            if (btnDaily) btnDaily.classList.add('hidden');
            if (speedDial) speedDial.classList.add('hidden');
            if (actFilterPill) actFilterPill.classList.add('hidden');
            if (boardView) {
                boardView.classList.remove('hidden');
                window.renderPriorityBoard();
            }
        } else if (mode === 'timeline') {
            if (typeof window.closeCanvasSpeedDial === 'function') window.closeCanvasSpeedDial();
            if (typeof window.closeSpeedDial === 'function') window.closeSpeedDial();
            if (typeof window.closePriorityCreateMenu === 'function') window.closePriorityCreateMenu();
            if (typeof window.closeCalendarCreateMenu === 'function') window.closeCalendarCreateMenu(); if (typeof window.closeMobileTopCreateMenu === 'function') window.closeMobileTopCreateMenu();
            if (typeof window.closeCalendarDayModal === 'function') window.closeCalendarDayModal();
            setActiveTabStyle('timeline');
            if (svgCanvas) svgCanvas.classList.add('hidden');
            if (boardView) boardView.classList.add('hidden');
            if (dock) dock.classList.add('hidden');
            if (btnDaily) btnDaily.classList.add('hidden');
            if (speedDial) speedDial.classList.add('hidden');
            if (actFilterPill) actFilterPill.classList.add('hidden');

            // Segmentación por Rol al ingresar al Calendario
            if (typeof currentUserRole !== 'undefined' && currentUserRole === 'Consultor' && typeof localAuthor !== 'undefined' && localAuthor) {
                calendarConsultantFilter = localAuthor;
            }

            if (timelineView) {
                timelineView.classList.remove('hidden');
                if (typeof window.renderTimelineBoard === 'function') window.renderTimelineBoard();
            }
        } else {
            if (typeof window.closePriorityCreateMenu === 'function') window.closePriorityCreateMenu();
            if (typeof window.closeCalendarCreateMenu === 'function') window.closeCalendarCreateMenu(); if (typeof window.closeMobileTopCreateMenu === 'function') window.closeMobileTopCreateMenu();
            setActiveTabStyle('map');
            if (boardView) boardView.classList.add('hidden');
            if (timelineView) timelineView.classList.add('hidden');
            if (svgCanvas) svgCanvas.classList.remove('hidden');
            const isDesktopMap = window.innerWidth >= 640;
            if (isDesktopMap) {
                if (dock) dock.classList.add('hidden');
                if (btnDaily) btnDaily.classList.remove('hidden');
                if (speedDial) speedDial.classList.remove('hidden');
            } else {
                if (dock) dock.classList.add('hidden');
                if (btnDaily) btnDaily.classList.add('hidden');
                if (speedDial) speedDial.classList.add('hidden');
            }
            if (typeof window.updateActiveFilterPill === 'function') window.updateActiveFilterPill();
            window.renderMindMap();

            // RECENTER AUTOMÁTICO INMEDIATO Y ANIMADO AL VOLVER AL MAPA
            setTimeout(() => {
                if (typeof window.recenterCanvas === 'function') {
                    window.recenterCanvas(0);
                    setTimeout(() => {
                        try { window.recenterCanvas(400); } catch(e) {}
                    }, 50);
                }
            }, 30);
        }
    };

    
    
    window.highlightPriorityCard = function(id) {
        document.querySelectorAll('#priorityBoardColumns .priority-card-active').forEach(el => {
            el.classList.remove('priority-card-active', 'ring-2', 'ring-[#ee6018]', 'border-[#ee6018]');
            el.classList.add('border-[#3d3a39]');
        });
        const target = document.querySelector(`#priorityBoardColumns [data-node-id="${id}"]`);
        if (target) {
            target.classList.add('priority-card-active', 'ring-2', 'ring-[#ee6018]', 'border-[#ee6018]');
            target.classList.remove('border-[#3d3a39]');
        }
    };

    window.togglePriorityCreateMenu = function() {
        const menu = document.getElementById('priorityCreateMenu');
        const trigger = document.getElementById('priorityCreateTrigger');
        if (!menu) return;
        const isHidden = menu.classList.contains('hidden');
        if (isHidden) {
            menu.classList.remove('hidden');
            if (trigger) trigger.setAttribute('aria-expanded', 'true');
        } else {
            menu.classList.add('hidden');
            if (trigger) trigger.setAttribute('aria-expanded', 'false');
        }
    };

    window.closePriorityCreateMenu = function() {
        const menu = document.getElementById('priorityCreateMenu');
        const trigger = document.getElementById('priorityCreateTrigger');
        if (menu) menu.classList.add('hidden');
        if (trigger) trigger.setAttribute('aria-expanded', 'false');
    };

    window.toggleCalendarCreateMenu = function() {
        const menu = document.getElementById('calendarCreateMenu');
        const trigger = document.getElementById('calendarCreateTrigger');
        if (!menu) return;
        const isHidden = menu.classList.contains('hidden');
        if (isHidden) {
            menu.classList.remove('hidden');
            if (trigger) trigger.setAttribute('aria-expanded', 'true');
        } else {
            menu.classList.add('hidden');
            if (trigger) trigger.setAttribute('aria-expanded', 'false');
        }
    };

    window.closeCalendarCreateMenu = function() {
        const menu = document.getElementById('calendarCreateMenu');
        const trigger = document.getElementById('calendarCreateTrigger');
        if (menu) menu.classList.add('hidden');
        if (trigger) trigger.setAttribute('aria-expanded', 'false');
    };

    window.setPriorityBoardGroupBy = function(groupBy) {
        priorityBoardGroupBy = groupBy;
        const btnC = document.getElementById('btnGroupConsultant');
        const btnT = document.getElementById('btnGroupTier');
        if (btnC && btnT) {
            if (groupBy === 'consultant') {
                btnC.className = "px-2.5 py-1 rounded-[3px] font-mono uppercase text-[10px] tracking-[-0.24px] flex items-center gap-1.5 transition bg-[#eeeeee] text-[#101010] font-medium cursor-pointer";
                btnT.className = "px-2.5 py-1 rounded-[3px] font-mono uppercase text-[10px] tracking-[-0.24px] flex items-center gap-1.5 transition text-[#b8b3b0] hover:text-[#eeeeee] cursor-pointer";
            } else {
                btnC.className = "px-2.5 py-1 rounded-[3px] font-mono uppercase text-[10px] tracking-[-0.24px] flex items-center gap-1.5 transition text-[#b8b3b0] hover:text-[#eeeeee] cursor-pointer";
                btnT.className = "px-2.5 py-1 rounded-[3px] font-mono uppercase text-[10px] tracking-[-0.24px] flex items-center gap-1.5 transition bg-[#eeeeee] text-[#101010] font-medium cursor-pointer";
            }
        }
        window.renderPriorityBoard();
    };

    window.adjustProjectPriority = function(type, id, delta, event) {
        if (event) {
            event.stopPropagation();
            event.preventDefault();
        }
        let target = null;
        if (type === 'direct-project') {
            target = (appData.directProjects || []).find(p => p.id === id);
        } else {
            (appData.modules || []).forEach(m => {
                const found = (m.projects || []).find(p => p.id === id);
                if (found) target = found;
            });
        }
        if (!target) return;

        let currentPrio = parseInt(target.priority, 10);
        if (isNaN(currentPrio) || currentPrio < 1) currentPrio = 1;
        let newPrio = currentPrio + delta;
        if (newPrio < 1) {
            window.showToast("⭐ Ya se encuentra en la prioridad máxima (*1)", false);
            return;
        }
        if (newPrio > 99) newPrio = 99;

        target.priority = newPrio;
        if (typeof window.logSystemActivity === 'function') {
            window.logSystemActivity(`Prioridad de "${target.name}" actualizada a *${newPrio}`, 'priority');
        }
        window.saveData(false);

        if (typeof window.renderPriorityBoard === 'function' && document.getElementById('priorityBoardView') && !document.getElementById('priorityBoardView').classList.contains('hidden')) {
            window.renderPriorityBoard();
        }
        if (typeof window.renderPriorityDrawer === 'function' && isPriorityDrawerOpen) {
            window.renderPriorityDrawer();
        }
        window.renderMindMap();
        if (currentSelection && currentSelection.id === id && typeof window.showInfoCard === 'function') {
            window.showInfoCard(type, id);
        }
        window.showToast(`🎯 Prioridad de "${target.name}" cambiada a *${newPrio}`, false);
    };

    window.jumpToMapNode = function(type, id, event) {
        if (event) {
            event.stopPropagation();
            event.preventDefault();
        }
        window.switchMainWorkspaceView('map');
        if (typeof isPriorityDrawerOpen !== 'undefined' && isPriorityDrawerOpen) window.closePriorityDrawer();
        if (typeof window.navigateToProjectFromNotif === 'function') {
            window.navigateToProjectFromNotif(type, id);
        } else {
            window.selectNode(type, id);
        }
    };


    window.bindPriorityBoardScroll = function() {
        const pCols = document.getElementById('priorityBoardColumns');
        if (!pCols || pCols.__wheelBound) return;
        pCols.__wheelBound = true;

        pCols.addEventListener('wheel', function(e) {
            const innerScroll = e.target.closest('.overflow-y-auto');
            if (innerScroll) {
                const canScrollDown = e.deltaY > 0 && (innerScroll.scrollTop + innerScroll.clientHeight < innerScroll.scrollHeight - 1);
                const canScrollUp = e.deltaY < 0 && (innerScroll.scrollTop > 1);
                if (canScrollDown || canScrollUp) {
                    return; // Permitir scroll vertical fluido de la columna
                }
            }
            if (Math.abs(e.deltaY) > Math.abs(e.deltaX)) {
                pCols.scrollLeft += e.deltaY;
                e.preventDefault();
            }
        }, { passive: false });
    };

    window.renderPriorityBoard = function() {
        try {
            const boardContainer = document.getElementById('priorityBoardColumns');
            const countBadge = document.getElementById('priorityBoardCountBadge');
            if (!boardContainer) return;

            if (!appData || !Array.isArray(appData.modules) || appData.modules.length === 0) {
                try { if (typeof loadLocalFallback === 'function') loadLocalFallback(); } catch(e) {}
            }

        const allProjs = [];
        (appData.directProjects || []).forEach(p => {
            allProjs.push({
                ...p,
                pType: 'direct-project',
                parentName: (appData.directHub && appData.directHub.name) || 'Directos',
                parentModId: 'hub-direct',
                parentColor: (appData.directHub && appData.directHub.color) || '#f59e0b'
            });
        });
        (appData.modules || []).forEach(m => {
            (m.projects || []).forEach(p => {
                allProjs.push({
                    ...p,
                    pType: 'project',
                    parentName: m.name || 'Módulo',
                    parentModId: m.id,
                    parentColor: m.color || '#eeeeee'
                });
            });
        });

        const isModAllPrio = activeFilterModules.includes('ALL') || activeFilterModules.length === 0;
        const selModsPrio = new Set(activeFilterModules.filter(x => x !== 'ALL').map(normModId));

        const projectPasses = (p) => {
            if (!activeFilterStatuses.includes('ALL') && activeFilterStatuses.length > 0) {
                if (!activeFilterStatuses.includes(p.status)) return false;
            }
            if (!activeFilterCompanies.includes('ALL') && activeFilterCompanies.length > 0) {
                const comps = window.getProjectCompanies(p);
                if (!comps.some(comp => activeFilterCompanies.includes(comp))) return false;
            }
            if (!activeFilterConsultants.includes('ALL') && activeFilterConsultants.length > 0) {
                const pCons = getProjectConsultants(p);
                if (!pCons.some(c => activeFilterConsultants.includes(c))) return false;
            }
            if (!isModAllPrio) {
                const pPrim = normModId(p.parentModId);
                const pSecs = (Array.isArray(p.secondaryModules) ? p.secondaryModules : []).map(normModId);
                const allMods = new Set([pPrim, ...pSecs].filter(Boolean));
                if (moduleFilterMode === 'CORRELATED' && selModsPrio.size >= 2) {
                    if ([...allMods].filter(m => selModsPrio.has(m)).length < 2) return false;
                } else if (!selModsPrio.has(pPrim)) return false;
            }
            if (activeFilterUrgency !== 'ALL') {
                const today = new Date(); today.setHours(0,0,0,0);
                let isOver = false, isSoon = false, is30 = false;
                if (p.deadline) {
                    const [y, m, d] = p.deadline.split('-');
                    const deadDate = new Date(y, m - 1, d);
                    const diffDays = Math.ceil((deadDate - today) / (1000 * 60 * 60 * 24));
                    if (diffDays < 0 && !isCompletedStatus(p.status)) isOver = true;
                    else if (diffDays >= 0 && diffDays <= 7 && !isCompletedStatus(p.status)) isSoon = true;
                    else if (diffDays > 7 && diffDays <= 30 && !isCompletedStatus(p.status)) is30 = true;
                }
                if (activeFilterUrgency === 'OVERDUE' && !isOver) return false;
                if (activeFilterUrgency === 'WEEK' && !isSoon) return false;
                if (activeFilterUrgency === 'MONTH' && !is30) return false;
                if (activeFilterUrgency === 'NONE' && p.deadline) return false;
            }
            if (activeFilterPriority !== 'ALL') {
                const prio = parseFloat(p.priority || 0);
                if (activeFilterPriority === 'HIGH' && prio > 3) return false;
                if (activeFilterPriority === 'MED' && (prio < 4 || prio > 6)) return false;
                if (activeFilterPriority === 'LOW' && prio < 7) return false;
            }
            if (activeFilterBottleneck !== 'ALL') {
                if (activeFilterBottleneck === 'CLIENT' && (!p.clientDeliveryDate || p.clientReturnDate || isCompletedStatus(p.status))) return false;
                if (activeFilterBottleneck === 'VALIDATION' && !(p.tasks || []).some(t => t.done === 'pending')) return false;
                if (activeFilterBottleneck === 'NA') {
                    const isClient = (p.clientDeliveryDate && !p.clientReturnDate && !isCompletedStatus(p.status));
                    const isVal = (p.tasks || []).some(t => t.done === 'pending');
                    if (isClient || isVal) return false;
                }
            }
            if (activeSearchQuery) {
                const q = activeSearchQuery.toLowerCase();
                const nameMatch = (p.name || '').toLowerCase().includes(q);
                const tk = (typeof getProjectTicket === 'function' ? getProjectTicket(p) : (p.ticket || '')).toLowerCase();
                const tkMatch = tk.includes(q);
                const descMatch = (p.notes || []).some(n => (n.text || '').toLowerCase().includes(q));
                const consMatch = (getProjectConsultants(p) || []).some(c => c.toLowerCase().includes(q));
                const parentMatch = (p.parentName || '').toLowerCase().includes(q);
                if (!nameMatch && !tkMatch && !descMatch && !consMatch && !parentMatch) return false;
            }
            return true;
        };

        const matchingProjs = allProjs.filter(projectPasses);

        if (countBadge) {
            countBadge.textContent = `${matchingProjs.length} PROYECTOS`;
        }

        const renderCard = (p, accentColor) => {
            const sIco = p.status === 'En Progreso' ? '🚀' : (isCompletedStatus(p.status) ? '✅' : (p.status === 'No Iniciado' ? '⏸️' : '⏳'));
            let isOver = false;
            if (p.deadline && !isCompletedStatus(p.status)) {
                const [y, m, d] = p.deadline.split('-');
                if (new Date(y, m - 1, d) < new Date(new Date().setHours(0, 0, 0, 0))) isOver = true;
            }
            const comps = window.getProjectCompanies(p);
            const compBadges = comps.map(comp => {
                const st = window.getCompanyStyle ? window.getCompanyStyle(comp) : { color: '#ee6018', bg: 'rgba(238,96,24,0.15)', border: 'rgba(238,96,24,0.3)', icon: '🏢' };
                return `<span class="font-mono text-[9px] uppercase px-1.5 py-0.5 rounded-[3px] border truncate max-w-[90px]" style="background-color:${st.bg}; color:${st.color}; border-color:${st.border};" title="${escapeHtml(comp)}">${st.icon} ${escapeHtml(comp)}</span>`;
            }).join('');

            const tk = (typeof getProjectTicket === 'function' ? getProjectTicket(p) : (p.ticket || '')).trim().replace(/^#+/, '');
            const tkBadge = tk ? `<span class="inline-flex items-center gap-0.5 font-mono text-[9px] uppercase px-1.5 py-0.5 rounded-[3px] bg-yellow-200 text-yellow-900 font-semibold border border-yellow-400 shrink-0">🎫 #${escapeHtml(tk)}</span>` : '';

            const pCons = getProjectConsultants(p);
            const consPills = pCons.map(c => {
                const cd = consultants[c];
                const col = cd ? cd.color : '#b8b3b0';
                return `<span class="inline-flex items-center gap-1 font-mono text-[9px] uppercase px-1.5 py-0.5 rounded-[3px] bg-[#101010] border border-[#3d3a39] text-[#eeeeee] shrink-0"><span class="w-1.5 h-1.5 rounded-full" style="background-color: ${col}"></span>${escapeHtml(c)}</span>`;
            }).join('');

            const prioVal = parseInt(p.priority, 10) || 1;
            const isSelected = currentSelection && currentSelection.id === p.id;
            const cardBorder = isSelected 
                ? 'border-[#ee6018] ring-2 ring-[#ee6018] bg-[#1c1917] priority-card-active' 
                : (isOver ? 'border-[#ee6018]' : 'border-[#3d3a39] hover:border-[#eeeeee]/60');

            return `
            <div data-node-id="${p.id}" class="bg-[#101010] hover:bg-[#1c1917] border ${cardBorder} rounded-[10px] p-3 transition-all cursor-pointer group flex flex-col gap-2 select-none" style="border-left: 3px solid ${isOver ? '#ee6018' : (accentColor || '#3d3a39')}" onclick="window.selectNode('${p.pType}', '${p.id}')">
              <div class="flex items-center justify-between gap-1.5 min-w-0">
                <div class="flex items-center gap-1 shrink-0" onclick="event.stopPropagation()">
                  <span class="font-mono text-xs font-bold px-2 py-0.5 rounded-[3px] bg-[#101010] border border-[#3d3a39] shadow-inner" style="color: ${accentColor || '#ee6018'}">*${prioVal}</span>
                  <div class="flex items-center bg-[#101010] border border-[#3d3a39] rounded-[3px] overflow-hidden">
                    <button type="button" onclick="window.adjustProjectPriority('${p.pType}', '${p.id}', -1, event)" class="px-1.5 py-0.5 hover:bg-[#3d3a39] text-[#b8b3b0] hover:text-[#fafafa] text-[10px] leading-none transition" title="Subir prioridad (ej. *2 ➔ *1)">▲</button>
                    <button type="button" onclick="window.adjustProjectPriority('${p.pType}', '${p.id}', 1, event)" class="px-1.5 py-0.5 hover:bg-[#3d3a39] text-[#b8b3b0] hover:text-[#fafafa] text-[10px] leading-none transition border-l border-[#3d3a39]" title="Bajar prioridad (ej. *1 ➔ *2)">▼</button>
                  </div>
                </div>

                <div class="flex items-center gap-1 overflow-hidden justify-end">
                  ${tkBadge}
                  <span class="font-mono text-[9px] uppercase px-1.5 py-0.5 rounded-[3px] bg-[#101010] border border-[#3d3a39] text-[#b8b3b0] truncate max-w-[110px]" title="${escapeHtml(p.status || 'Pendiente')}">${sIco} ${escapeHtml(p.status || 'Pendiente')}</span>
                </div>
              </div>

              <h4 class="text-xs sm:text-[13px] font-medium text-[#eeeeee] leading-snug line-clamp-2 group-hover:text-[#fafafa] transition break-words">
                ${isOver ? '<span class="text-[#ee6018] font-bold">⚠️ </span>' : ''}${escapeHtml(p.name)}
              </h4>

              <div class="flex flex-wrap items-center gap-1 text-[9px] font-mono text-[#8a8380]">
                <span class="truncate max-w-[140px] px-1.5 py-0.5 rounded-[3px] bg-[#101010] border border-[#3d3a39] text-[#8a8380]" title="${escapeHtml(p.parentName)}">📁 ${escapeHtml(p.parentName)}</span>
                ${compBadges}
                ${priorityBoardGroupBy === 'tier' ? consPills : ''}
              </div>

              <div class="flex items-center justify-between gap-2 pt-1 border-t border-[#3d3a39]/80 mt-0.5">
                <div class="flex items-center gap-1.5 min-w-0">
                  <div class="w-14 sm:w-16 h-1.5 bg-[#101010] rounded-full overflow-hidden border border-[#3d3a39] shrink-0">
                    <div class="h-full bg-[#10b981] rounded-full" style="width: ${p.progress || 0}%"></div>
                  </div>
                  <span class="font-mono text-[9px] text-[#a0ca92] font-semibold">${p.progress || 0}%</span>
                  ${p.deadline ? `<span class="hidden sm:inline font-mono text-[9px] text-[#8a8380] truncate">📅 ${p.deadline}</span>` : ''}
                </div>

                <div class="flex items-center gap-1 shrink-0" onclick="event.stopPropagation()">
                  <button type="button" onclick="window.jumpToMapNode('${p.pType}', '${p.id}', event)" class="px-2 py-0.5 rounded-[3px] bg-[#1d1a18] hover:bg-[#ee6018] hover:text-[#101010] border border-[#3d3a39] text-[#b8b3b0] font-mono text-[9px] uppercase transition flex items-center gap-1 cursor-pointer" title="Ver en el Mapa Mental">
                    <span>Mapa</span><span class="text-[8px]">↗</span>
                  </button>
                  <button type="button" onclick="window.selectNodeAndOpenConfig('${p.pType}', '${p.id}', event)" class="p-1 rounded-[3px] bg-[#1d1a18] hover:bg-[#3d3a39] text-[#8a8380] hover:text-[#eeeeee] transition cursor-pointer" title="Editar en configuración completa">
                    <svg class="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="1.75" d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z"/><path stroke-linecap="round" stroke-linejoin="round" stroke-width="1.75" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"/></svg>
                  </button>
                </div>
              </div>
            </div>`;
        };

        if (matchingProjs.length === 0) {
            boardContainer.innerHTML = `
            <div class="w-full flex flex-col items-center justify-center py-24 text-center">
              <div class="w-14 h-14 rounded-full bg-[#181615] border border-[#3d3a39] flex items-center justify-center mb-4 text-[#8a8380]">
                <svg class="w-7 h-7" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="1.75" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-6 9l2 2 4-4"/></svg>
              </div>
              <h3 class="text-sm font-semibold uppercase font-mono text-[#eeeeee]">Sin proyectos que coincidan</h3>
              <p class="text-xs text-[#8a8380] font-mono mt-1 max-w-sm">No hay proyectos que cumplan con la búsqueda o los filtros operativos seleccionados.</p>
              <button type="button" onclick="window.clearActiveFilterPill()" class="mt-4 px-3 py-1.5 rounded-[3px] bg-[#ee6018] text-[#fafafa] font-mono text-xs uppercase font-medium hover:bg-[#d45210] transition">Restablecer Filtros</button>
            </div>`;
            return;
        }

        let htmlColumns = '';

        if (priorityBoardGroupBy === 'consultant') {
            const consList = Object.keys(consultants);
            consList.forEach(consName => {
                const cData = consultants[consName] || { color: '#8a8380' };
                const cProjs = matchingProjs.filter(p => getProjectConsultants(p).includes(consName));
                if (cProjs.length === 0) return;

                cProjs.sort((a, b) => (parseInt(a.priority, 10) || 99) - (parseInt(b.priority, 10) || 99));
                const p1Count = cProjs.filter(p => parseInt(p.priority, 10) === 1).length;

                const cardsHtml = cProjs.map(p => renderCard(p, cData.color)).join('');

                htmlColumns += `
                <div class="w-80 sm:w-88 shrink-0 bg-[#121110] border border-[#262321] rounded-[10px] flex flex-col max-h-full overflow-hidden">
                  <div class="p-3 bg-[#181615] border-b border-[#262321] flex items-center justify-between" style="border-left: 3px solid ${cData.color}">
                    <div class="flex items-center gap-2 min-w-0">
                      <span class="w-2.5 h-2.5 rounded-full shrink-0" style="background-color: ${cData.color}"></span>
                      <h3 class="font-mono text-xs font-semibold uppercase text-[#fafafa] truncate">${escapeHtml(consName)}</h3>
                    </div>
                    <div class="flex items-center gap-1.5 shrink-0">
                      ${p1Count > 0 ? `<span class="font-mono text-[9px] px-2 py-0.5 rounded-[3px] bg-[#ee6018]/15 border border-[#ee6018]/40 text-[#ee6018] font-bold">🔥 ${p1Count} en *1</span>` : ''}
                      <span class="font-mono text-[10px] px-2 py-0.5 rounded-[3px] bg-[#101010] border border-[#3d3a39] text-[#b8b3b0] font-medium">${cProjs.length}</span>
                    </div>
                  </div>
                  <div class="flex-1 overflow-y-auto p-3 pb-32 sm:pb-3 space-y-3 scrollbar-thin">
                    ${cardsHtml}
                  </div>
                </div>`;
            });
        } else {
            const tiers = [
                {
                    id: 'tier1',
                    label: '🔥 Prioridad Crítica (*1 - *2)',
                    color: '#ef4444',
                    filter: p => { const prio = parseInt(p.priority, 10) || 99; return prio <= 2; }
                },
                {
                    id: 'tier2',
                    label: '⚡ Prioridad Alta (*3 - *4)',
                    color: '#f59e0b',
                    filter: p => { const prio = parseInt(p.priority, 10) || 99; return prio >= 3 && prio <= 4; }
                },
                {
                    id: 'tier3',
                    label: '📌 Prioridad Media (*5 - *6)',
                    color: '#3b82f6',
                    filter: p => { const prio = parseInt(p.priority, 10) || 99; return prio >= 5 && prio <= 6; }
                },
                {
                    id: 'tier4',
                    label: '📥 Backlog (*7+)',
                    color: '#8a8380',
                    filter: p => { const prio = parseInt(p.priority, 10) || 99; return prio >= 7; }
                }
            ];

            tiers.forEach(tier => {
                const tierProjs = matchingProjs.filter(tier.filter);
                tierProjs.sort((a, b) => (parseInt(a.priority, 10) || 99) - (parseInt(b.priority, 10) || 99));

                const cardsHtml = tierProjs.length > 0
                    ? tierProjs.map(p => renderCard(p, tier.color)).join('')
                    : `<div class="py-10 text-center text-[#8a8380] font-mono text-[10px] uppercase">Sin proyectos en este nivel</div>`;

                const pct = matchingProjs.length > 0 ? Math.round((tierProjs.length / matchingProjs.length) * 100) : 0;

                htmlColumns += `
                <div class="w-80 sm:w-88 shrink-0 bg-[#121110] border border-[#262321] rounded-[10px] flex flex-col max-h-full overflow-hidden">
                  <div class="p-3 bg-[#181615] border-b border-[#262321] flex items-center justify-between" style="border-left: 3px solid ${tier.color}">
                    <div class="flex items-center gap-2 min-w-0">
                      <span class="w-2.5 h-2.5 rounded-full shrink-0" style="background-color: ${tier.color}"></span>
                      <h3 class="font-mono text-xs font-semibold uppercase text-[#fafafa] truncate">${tier.label}</h3>
                    </div>
                    <div class="flex items-center gap-1.5 shrink-0">
                      <span class="font-mono text-[9px] px-1.5 py-0.5 rounded-[3px] bg-[#101010] border border-[#3d3a39] text-[#8a8380]">${pct}%</span>
                      <span class="font-mono text-[10px] px-2 py-0.5 rounded-[3px] bg-[#101010] border border-[#3d3a39] text-[#b8b3b0] font-medium">${tierProjs.length}</span>
                    </div>
                  </div>
                  <div class="flex-1 overflow-y-auto p-3 pb-32 sm:pb-3 space-y-3 scrollbar-thin">
                    ${cardsHtml}
                  </div>
                </div>`;
            });
        }

        boardContainer.innerHTML = htmlColumns;
        if (typeof window.bindPriorityBoardScroll === 'function') window.bindPriorityBoardScroll();
        } catch (err) {
            console.error('⚠️ [Prioridades] Error al renderizar tablero:', err);
        }
    };

    window.renderMindMap = function() {
      if (!canvasGroup) window.ensureDomReferences();
      if (!canvasGroup) return;
      const mapFrag = document.createDocumentFragment();
      const dynamicDefs = document.createElementNS('http://www.w3.org/2000/svg', 'defs');
      mapFrag.appendChild(dynamicDefs);
      const q = activeSearchQuery.toLowerCase();

      ensureDataStructure();
      if (!initialCollapseApplied) {
          collapsedModules.add('hub-direct');
          knownModuleIds.add('hub-direct');
          (appData.modules || []).forEach(m => {
              if (m && m.id) {
                  collapsedModules.add(m.id);
                  knownModuleIds.add(m.id);
              }
          });
          initialCollapseApplied = true;
          window.updateCollapseAllButtonState();
      } else {
          // Cualquier módulo que llegue por primera vez (ej. desde Firebase o recién creado) inicia colapsado
          if (!knownModuleIds.has('hub-direct')) {
              collapsedModules.add('hub-direct');
              knownModuleIds.add('hub-direct');
          }
          (appData.modules || []).forEach(m => {
              if (m && m.id && !knownModuleIds.has(m.id)) {
                  collapsedModules.add(m.id);
                  knownModuleIds.add(m.id);
              }
          });
      }

      // Garantizar que todos los proyectos tengan su _modId primario antes de evaluar filtros
      (appData.directProjects || []).forEach(p => {
          if (p) { p._modId = 'hub-direct'; p._renderData = null; }
      });
      (appData.modules || []).forEach(m => {
          if (!m) return;
          (m.projects || []).forEach(p => {
              if (p) { p._modId = m.id; p._renderData = null; }
          });
      });

      const isModAll = activeFilterModules.includes('ALL') || activeFilterModules.length === 0;
      const selectedNormMods = new Set(activeFilterModules.filter(x => x !== 'ALL').map(normModId));
      const isMultiModSelected = !isModAll && selectedNormMods.size >= 2;

      const getProjectAllNormMods = (p) => {
          const orig = p._origProj || p;
          const prim = normModId(orig._modId || p._modId);
          const secs = (Array.isArray(orig.secondaryModules) ? orig.secondaryModules : []).map(normModId);
          return new Set([prim, ...secs].filter(Boolean));
      };

      const isProjectModCorrelated = (p) => {
          if (!isMultiModSelected) return false;
          const pMods = getProjectAllNormMods(p);
          let matchCount = 0;
          pMods.forEach(mId => { if (selectedNormMods.has(mId)) matchCount++; });
          return matchCount >= 2;
      };
      
      const isFiltered = (p) => {
          if (isFocusMode) {
              let isOverdue = false, isSoon = false;
              if (p.deadline && !isCompletedStatus(p.status)) {
                  const [y,m,d] = p.deadline.split('-'); 
                  const diff = Math.ceil((new Date(y, m-1, d) - new Date(new Date().setHours(0,0,0,0))) / 86400000);
                  if (diff < 0) isOverdue = true;
                  if (diff >= 0 && diff <= 3) isSoon = true;
              }
              const hasVal = (p.tasks||[]).some(t => t.done === 'pending');
              return isOverdue || isSoon || hasVal;
          }

          if (!isModAll) {
              const pContainerMod = normModId(p._modId);
              const origPrim = normModId((p._origProj || p)._modId || p._modId);
              const pAllMods = getProjectAllNormMods(p);

              if (!selectedNormMods.has(pContainerMod)) return false;

              if (selectedNormMods.size === 1) {
                  // Selección de 1 solo módulo: enfocar exclusivamente los proyectos de ese módulo sin expandir otros
                  if (!pAllMods.has(pContainerMod)) return false;
              } else {
                  // Multiselección de módulos (2 o más)
                  // Evitar duplicar una copia vinculada si su módulo primario ya está entre los seleccionados
                  if (p._isLinkedCopy && selectedNormMods.has(origPrim)) return false;
                  if (p._isLinkedCopy && !selectedNormMods.has(origPrim)) {
                      const firstSelectedSec = [...selectedNormMods].find(sm => pAllMods.has(sm));
                      if (pContainerMod !== firstSelectedSec) return false;
                  }
                  if (moduleFilterMode === 'CORRELATED') {
                      if (!isProjectModCorrelated(p)) return false;
                  }
              }
          }
          if (activeFilterStatuses.length > 0 && !activeFilterStatuses.includes('ALL')) {
              if (!activeFilterStatuses.includes(p.status)) return false;
          }
          if (activeFilterConsultants.length > 0 && !activeFilterConsultants.includes('ALL')) {
              const pCons = getProjectConsultants(p);
              if (consultantFilterMode === 'ALL_SELECTED' && activeFilterConsultants.length >= 2) {
                  if (!activeFilterConsultants.every(c => pCons.includes(c))) return false;
              } else {
                  if (!pCons.some(c => activeFilterConsultants.includes(c))) return false;
              }
          }
          if (activeFilterCompanies.length > 0 && !activeFilterCompanies.includes('ALL')) {
              const pComps = window.getProjectCompanies(p);
              if (!pComps.some(c => activeFilterCompanies.includes(c))) return false;
          }
          
          if (activeFilterUrgency !== 'ALL') {
              if (isCompletedStatus(p.status)) return false;
              let isOver = false, isSoon = false, is30 = false;
              if (p.deadline) {
                  const [y,m,d] = p.deadline.split('-'); 
                  const diff = Math.ceil((new Date(y, m-1, d) - new Date(new Date().setHours(0,0,0,0))) / 86400000);
                  if (diff < 0) isOver = true; if (diff >= 0 && diff <= 7) isSoon = true; if (diff >= 0 && diff <= 30) is30 = true;
              }
              if (activeFilterUrgency === 'OVERDUE' && !isOver) return false;
              if (activeFilterUrgency === 'WEEK' && !isSoon) return false;
              if (activeFilterUrgency === 'MONTH' && !is30) return false;
              if (activeFilterUrgency === 'NONE' && p.deadline) return false;
          }

          if (activeFilterPriority !== 'ALL') {
              const prio = parseFloat(p.priority || 1);
              if (activeFilterPriority === 'HIGH' && prio > 3) return false;
              if (activeFilterPriority === 'MED' && (prio < 4 || prio > 6)) return false;
              if (activeFilterPriority === 'LOW' && prio < 7) return false;
          }

          if (activeFilterBottleneck !== 'ALL') {
              if (activeFilterBottleneck === 'CLIENT' && (!p.clientDeliveryDate || p.clientReturnDate || isCompletedStatus(p.status))) return false;
              if (activeFilterBottleneck === 'VALIDATION' && !(p.tasks||[]).some(t => t.done === 'pending')) return false;
              if (activeFilterBottleneck === 'NA') {
                  let unv = false; if(p.docs) Object.keys(p.docs).forEach(k => { if(p.docs[k].na && !p.docs[k].naValidated) unv = true; });
                  if(!unv) return false;
              }
          }

          if (q) {
              const qClean = q.replace(/^#/, '');
              const nameMatch = p.name.toLowerCase().includes(q);
              const consMatch = getProjectConsultants(p).some(c => c.toLowerCase().includes(q));
              const compMatch = window.getProjectCompanies(p).some(c => c.toLowerCase().includes(q));
              const tk = (typeof getProjectTicket === 'function' ? getProjectTicket(p) : (p.ticket || '')).toLowerCase();
              const tkMatch = tk && (tk.includes(q) || tk.includes(qClean) || (`#${tk}`).includes(q));
              if (!nameMatch && !consMatch && !compMatch && !tkMatch) return false;
          }
          return true;
      };

      const isConsAll = activeFilterConsultants.includes('ALL') || activeFilterConsultants.length === 0;
      const isStatusAll = activeFilterStatuses.includes('ALL') || activeFilterStatuses.length === 0;
      const isCompAll = activeFilterCompanies.includes('ALL') || activeFilterCompanies.length === 0;

      const isDefaultState = !isFocusMode &&
          isModAll &&
          isStatusAll &&
          isConsAll &&
          isCompAll &&
          activeFilterUrgency === 'ALL' &&
          activeFilterPriority === 'ALL' &&
          activeFilterBottleneck === 'ALL' &&
          !q;

      function isModuleCollapsed(modId, n) {
          const nMod = normModId(modId);
          if (!isDefaultState) {
              if (!isModAll && !selectedNormMods.has(nMod)) {
                  return true;
              }
              return (n.projects || []).length === 0;
          }
          return collapsedModules.has(modId);
      }

      const directHubItem = appData.directHub || (appData.directHub = { id: 'hub-direct', name: 'PROYECTOS DIRECTOS SICOM', color: '#f59e0b' });
      const visDir = appData.directProjects || [];
      const activeMods = (appData.modules || []).filter(m => m && typeof m === 'object');

      const getLinkedProjectsForModule = (modId) => {
          const linked = [];
          if (modId !== 'hub-direct' && modId !== 'DIRECT') {
              visDir.forEach(p => {
                  if (Array.isArray(p.secondaryModules) && p.secondaryModules.includes(modId)) {
                      linked.push(Object.assign(Object.create(p), {
                          _isLinkedCopy: true,
                          _origProj: p,
                          _modId: modId,
                          _strictType: 'direct-project',
                          _renderData: null
                      }));
                  }
              });
          }
          activeMods.forEach(m => {
              if (!m || m.id === modId) return;
              (m.projects || []).forEach(p => {
                  const isSec = Array.isArray(p.secondaryModules) && (
                      p.secondaryModules.includes(modId) ||
                      (modId === 'hub-direct' && p.secondaryModules.includes('DIRECT')) ||
                      (modId === 'DIRECT' && p.secondaryModules.includes('hub-direct'))
                  );
                  if (isSec) {
                      linked.push(Object.assign(Object.create(p), {
                          _isLinkedCopy: true,
                          _origProj: p,
                          _modId: modId,
                          _strictType: 'project',
                          _renderData: null
                      }));
                  }
              });
          });
          return linked;
      };

      const buildModuleProjectsList = (modId, ownP, linkedP) => {
          // Cada módulo aloja estrictamente sus proyectos propios para evitar duplicidades visuales en el mapa
          const rawList = ownP;
          return isDefaultState ? rawList : rawList.filter(p => isFiltered(p));
      };

      const dirLinked = getLinkedProjectsForModule('hub-direct');
      // Ordenamiento por Peso (Gravedad al Centro): mayor a menor según cantidad de proyectos propios
      const allNodes = [
          {
              type: 'direct-hub',
              item: directHubItem,
              ownProjects: visDir,
              linkedProjects: dirLinked,
              projects: buildModuleProjectsList('hub-direct', visDir, dirLinked)
          }
      ];
      
      activeMods.forEach(m => {
          if (!m.id) m.id = 'm_' + Math.random().toString(36).slice(2, 9);
          if (!m.name) m.name = 'Módulo';
          if (!m.color) m.color = '#0071e3';
          const ownP = m.projects || [];
          const linkedP = getLinkedProjectsForModule(m.id);
          allNodes.push({
              type: 'module',
              item: m,
              ownProjects: ownP,
              linkedProjects: linkedP,
              projects: buildModuleProjectsList(m.id, ownP, linkedP)
          });
      });

      allNodes.sort((a, b) => (b.ownProjects || []).length - (a.ownProjects || []).length);

      // Simetría izquierda (Oeste) y derecha (Este), con los más pesados al centro (y ≈ 0) y los ligeros hacia Norte y Sur
      const leftRaw = [], rightRaw = [];
      allNodes.forEach((n, idx) => {
          if (idx % 2 === 0) leftRaw.push(n);
          else rightRaw.push(n);
      });

      function arrangeFromCenterOutward(rawList) {
          const ordered = [];
          rawList.forEach((n, idx) => {
              if (idx === 0) ordered.push(n);
              else if (idx % 2 === 1) ordered.unshift(n); // Hacia zona Norte (Arriba)
              else ordered.push(n); // Hacia zona Sur (Abajo)
          });
          return ordered;
      }

      const lNodes = arrangeFromCenterOutward(leftRaw);
      const rNodes = arrangeFromCenterOutward(rightRaw);

      // Helper para saber si un módulo está activo bajo el filtro actual
      const isModuleMatchedByFilter = (modId, n) => {
          if (isDefaultState) return true;
          const nMod = normModId(modId);
          const nItemName = n.item ? (n.item.name || '') : '';
          if (!isModAll) {
              if (!selectedNormMods.has(nMod)) return false;
              if (isMultiModSelected && moduleFilterMode === 'CORRELATED') {
                  if ((n.projects || []).length > 0) return true;
                  // También iluminar si es el módulo destino de un proyecto correlacionado en otro módulo seleccionado
                  const allVisibleCorrelated = [...lNodes, ...rNodes].flatMap(node => node.projects || []);
                  return allVisibleCorrelated.some(p => getProjectAllNormMods(p).has(nMod));
              }
              return true;
          }
          return (n.projects || []).length > 0 || (q !== '' && nItemName.toLowerCase().includes(q));
      };

      const slotH = 75, mOffX = 400, pOffX = 900;
      function procSide(nodes, isLeft) {
          const mx = isLeft ? -mOffX : mOffX, px = isLeft ? -pOffX : pOffX;
          
          // Total de slots reales en este sector según su estado actual (colapsado o expandido)
          const totalSlots = nodes.reduce((sum, n) => {
              const modId = n.type === 'direct-hub' ? 'hub-direct' : (n.item ? n.item.id : 'mod');
              const isCollapsed = isModuleCollapsed(modId, n);
              const pCount = (n.projects || []).length;
              return sum + (isCollapsed ? 1 : Math.max(1, pCount));
          }, 0);

          let cy = -(totalSlots * slotH / 2) + (slotH / 2);
          nodes.forEach(n => {
              const pCount = (n.projects || []).length;
              const modId = n.type === 'direct-hub' ? 'hub-direct' : (n.item ? n.item.id : 'mod');
              const nItemId = String(modId).replace(/[^a-zA-Z0-9_-]/g, '');
              const nItemColor = (n.item && n.item.color) ? n.item.color : '#0071e3';
              const isCollapsed = isModuleCollapsed(modId, n);
              const weight = isCollapsed ? 1 : Math.max(1, pCount);
              
              const sy = cy;
              const ey = cy + (weight - 1) * slotH;
              const my = (sy + ey) / 2;
              cy += weight * slotH;

              if (!isCollapsed && pCount > 0) {
                  n.projects.forEach((p, idx) => { 
                      const cN = getProjectConsultants(p);
                      const col = generateJointGradient(cN);
                      const strictType = p._strictType || (n.type === 'direct-hub' ? 'direct-project' : 'project');
                      p._modId = n.type === 'direct-hub' ? 'hub-direct' : (n.item ? n.item.id : 'mod');
                      const py = sy + idx * slotH;
                      p._renderData = { x: px, y: py, color: col, type: strictType, realId: p.id, parentModColor: nItemColor }; 
                      if (p._isLinkedCopy && p._origProj && !p._origProj._renderData) {
                          p._origProj._renderData = p._renderData;
                      }
                  });
              } else {
                  (n.projects || []).forEach(p => { p._renderData = null; });
              }

              n._renderData = { x: mx, y: my, isLeft };
              if (n.item) n.item._renderData = n._renderData;

              const modMatches = isModuleMatchedByFilter(modId, n);
              const lineOpacity = modMatches ? '1' : '0.12';

              const pC = document.createElementNS('http://www.w3.org/2000/svg', 'path');
              pC.classList.add('mindmap-connector');
              const modEndX = isLeft ? mx + 165 : mx - 165;
              const modEndY = my;
              let coreStartX, coreStartY, cp1CoreX, cp1CoreY, cp2CoreX, cp2CoreY;

              if (my < -70) {
                  coreStartX = 0;
                  coreStartY = -60;
                  cp1CoreX = 0;
                  cp1CoreY = -60 - Math.max(55, Math.abs(modEndY + 60) * 0.55);
                  cp2CoreX = isLeft ? modEndX + 75 : modEndX - 75;
                  cp2CoreY = modEndY;
              } else if (my > 70) {
                  coreStartX = 0;
                  coreStartY = 60;
                  cp1CoreX = 0;
                  cp1CoreY = 60 + Math.max(55, Math.abs(modEndY - 60) * 0.55);
                  cp2CoreX = isLeft ? modEndX + 75 : modEndX - 75;
                  cp2CoreY = modEndY;
              } else if (isLeft) {
                  coreStartX = -60;
                  coreStartY = 0;
                  cp1CoreX = -125;
                  cp1CoreY = 0;
                  cp2CoreX = modEndX + 65;
                  cp2CoreY = modEndY;
              } else {
                  coreStartX = 60;
                  coreStartY = 0;
                  cp1CoreX = 125;
                  cp1CoreY = 0;
                  cp2CoreX = modEndX - 65;
                  cp2CoreY = modEndY;
              }

              const newCorePathD = `M ${coreStartX} ${coreStartY} C ${cp1CoreX} ${cp1CoreY}, ${cp2CoreX} ${cp2CoreY}, ${modEndX} ${modEndY}`;
              pC.setAttribute('d', newCorePathD);
              pC.setAttribute('fill', 'none'); 

              // Conector de fibra óptica: Gradiente direccional de Núcleo a Módulo
              const coreGradId = `grad-c-${nItemId}`;
              const cGrad = document.createElementNS('http://www.w3.org/2000/svg', 'linearGradient');
              cGrad.setAttribute('id', coreGradId);
              cGrad.setAttribute('gradientUnits', 'userSpaceOnUse');
              cGrad.setAttribute('x1', `${coreStartX}`);
              cGrad.setAttribute('y1', `${coreStartY}`);
              cGrad.setAttribute('x2', `${modEndX}`);
              cGrad.setAttribute('y2', `${modEndY}`);

              const cs1 = document.createElementNS('http://www.w3.org/2000/svg', 'stop');
              cs1.setAttribute('offset', '0%');
              cs1.setAttribute('stop-color', nItemColor);
              cs1.setAttribute('stop-opacity', '0.38');
              cGrad.appendChild(cs1);

              const cs2 = document.createElementNS('http://www.w3.org/2000/svg', 'stop');
              cs2.setAttribute('offset', '100%');
              cs2.setAttribute('stop-color', nItemColor);
              cs2.setAttribute('stop-opacity', '0.85');
              cGrad.appendChild(cs2);

              dynamicDefs.appendChild(cGrad);

              pC.setAttribute('stroke', `url(#${coreGradId})`); 
              pC.setAttribute('stroke-width', '1.8');
              pC.setAttribute('opacity', lineOpacity);
              mapFrag.appendChild(pC);

              const prevModPos = prevModulePositions.get(modId);
              const prevCorePathD = prevCorePaths.get(modId);
              if (prevModPos && prevModPos.y !== my && prevCorePathD && prevCorePathD !== newCorePathD) {
                  const prevNums = (prevCorePathD.match(/-?\d+(\.\d+)?/g) || []).map(Number);
                  const currNums = [coreStartX, coreStartY, cp1CoreX, cp1CoreY, cp2CoreX, cp2CoreY, modEndX, modEndY];
                  if (prevNums.length === 8) {
                      pC.setAttribute('d', prevCorePathD);
                      const animStart = performance.now();
                      const animDur = 380;
                      const stepCorePath = (now) => {
                          const t = Math.min(1, (now - animStart) / animDur);
                          const ease = 1 - Math.pow(1 - t, 3);
                          const v = prevNums.map((p0, i) => p0 + (currNums[i] - p0) * ease);
                          pC.setAttribute('d', `M ${v[0]} ${v[1]} C ${v[2]} ${v[3]}, ${v[4]} ${v[5]}, ${v[6]} ${v[7]}`);
                          cGrad.setAttribute('x1', `${v[0]}`);
                          cGrad.setAttribute('y1', `${v[1]}`);
                          cGrad.setAttribute('x2', `${v[6]}`);
                          cGrad.setAttribute('y2', `${v[7]}`);
                          if (t < 1 && pC.isConnected) requestAnimationFrame(stepCorePath);
                      };
                      requestAnimationFrame(stepCorePath);
                  }
              }
              prevCorePaths.set(modId, newCorePathD);

              if (!isCollapsed && pCount > 0) (n.projects || []).forEach((p, idx) => {
                  if (!p._renderData) return;
                  const pMatches = isDefaultState || isFiltered(p);
                  const isSynergyMatch = !activeFilterConsultants.includes('ALL') && activeFilterConsultants.length >= 2 && activeFilterConsultants.every(c => getProjectConsultants(p).includes(c));
                  const isModCorrMatch = isProjectModCorrelated(p);
                  let isOver = false;
                  if(p.deadline && !isCompletedStatus(p.status)) {
                      const [dy, dm, dd] = p.deadline.split('-');
                      if(new Date(dy, dm-1, dd) < new Date(new Date().setHours(0,0,0,0))) isOver = true;
                  }

                  const pP = document.createElementNS('http://www.w3.org/2000/svg', 'path');
                  pP.classList.add('mindmap-connector');
                  pP.setAttribute('pathLength', '1');
                  pP.setAttribute('data-parent-mod', String(modId));
                  pP.style.setProperty('--target-opacity', pMatches ? '1' : '0.12');
                  const solidColor = (getProjectConsultants(p).length > 0 && consultants[getProjectConsultants(p)[0]]) ? consultants[getProjectConsultants(p)[0]].color : '#48484a';
                  const endCol = isOver ? '#ee6018' : solidColor;

                  // Conexión limpia y fluida que nace exactamente en el botón de colapso
                  const startX = isLeft ? (mx - 165 - 11) : (mx + 165 + 11);
                  const endX = isLeft ? p._renderData.x + 160 : p._renderData.x - 160;
                  const dx = Math.abs(endX - startX);
                  const cpDist = Math.max(40, Math.min(95, dx * 0.45));
                  const cp1X = isLeft ? startX - cpDist : startX + cpDist;
                  const cp2X = isLeft ? endX + cpDist : endX - cpDist;
                  
                  pP.setAttribute('d', `M ${startX} ${my} C ${cp1X} ${my}, ${cp2X} ${p._renderData.y}, ${endX} ${p._renderData.y}`);
                  pP.setAttribute('fill', 'none'); 

                  // Conector de fibra óptica: Gradiente direccional de Módulo a Proyecto
                  const pIdClean = String(p.id || Math.random().toString(36).slice(2, 7)).replace(/[^a-zA-Z0-9_-]/g, '');
                  const pGradId = `grad-p-${nItemId}-${pIdClean}`;
                  const pGrad = document.createElementNS('http://www.w3.org/2000/svg', 'linearGradient');
                  pGrad.setAttribute('id', pGradId);
                  pGrad.setAttribute('gradientUnits', 'userSpaceOnUse');
                  pGrad.setAttribute('x1', `${startX}`);
                  pGrad.setAttribute('y1', `${my}`);
                  pGrad.setAttribute('x2', `${endX}`);
                  pGrad.setAttribute('y2', `${p._renderData.y}`);

                  const ps1 = document.createElementNS('http://www.w3.org/2000/svg', 'stop');
                  ps1.setAttribute('offset', '0%');
                  ps1.setAttribute('stop-color', nItemColor);
                  ps1.setAttribute('stop-opacity', '0.50');
                  pGrad.appendChild(ps1);

                  const ps2 = document.createElementNS('http://www.w3.org/2000/svg', 'stop');
                  ps2.setAttribute('offset', '100%');
                  ps2.setAttribute('stop-color', endCol);
                  ps2.setAttribute('stop-opacity', '0.85');
                  pGrad.appendChild(ps2);

                  dynamicDefs.appendChild(pGrad);

                  if (isSynergyMatch || isModCorrMatch) {
                      pP.removeAttribute('pathLength');
                      pP.classList.add('synergy-connector-line');
                      pP.setAttribute('stroke', isSynergyMatch ? generateJointGradient(activeFilterConsultants) : `url(#${pGradId})`);
                  } else {
                      pP.setAttribute('stroke', `url(#${pGradId})`);
                  }
                  pP.setAttribute('stroke-width', '1.5'); 
                  pP.setAttribute('opacity', pMatches ? '1' : '0.12'); 
                  if (lastExpandedModuleId === modId && !isSynergyMatch && !isModCorrMatch) {
                      pP.classList.add('connector-animate-in');
                      pP.style.animationDelay = `${idx * 15}ms`;
                  }
                  mapFrag.appendChild(pP);
              });
          });
      }
      procSide(lNodes, true); procSide(rNodes, false);

      // Mapa de nodos de módulo para resolución rápida de conectores secundarios
      const moduleNodeMap = new Map();
      [...lNodes, ...rNodes].forEach(n => {
          const mId = n.type === 'direct-hub' ? 'DIRECT' : (n.item ? n.item.id : '');
          if (mId) moduleNodeMap.set(mId, n);
          if (n.type === 'direct-hub') moduleNodeMap.set('hub-direct', n);
      });

      // Conectores Secundarios Multimódulo (Fibras ópticas de dependencias cruzadas)
      [...lNodes, ...rNodes].forEach(n => {
          const containerModId = n.type === 'direct-hub' ? 'hub-direct' : (n.item ? n.item.id : '');
          const containerModColor = (n.item && n.item.color) ? n.item.color : '#ee6018';
          (n.projects || []).forEach(p => {
              if (!p._renderData) return;
              const origProj = p._origProj || p;
              const allRelatedMods = [
                  normModId(origProj._modId || containerModId),
                  ...((Array.isArray(origProj.secondaryModules) ? origProj.secondaryModules : []).map(normModId))
              ].filter((mId, idx, arr) => mId && mId !== normModId(containerModId) && arr.indexOf(mId) === idx);

              if (allRelatedMods.length === 0) return;

              const pData = p._renderData;
              const pMatches = isDefaultState || isFiltered(p);
              const isProjectSel = currentSelection.id === p.id;

              allRelatedMods.forEach(secId => {
                  const secNode = moduleNodeMap.get(secId) || (secId === 'DIRECT' || secId === 'hub-direct' ? moduleNodeMap.get('hub-direct') : null);
                  if (!secNode || !secNode._renderData) return;

                  const secData = secNode._renderData;
                  const secMx = secData.x;
                  const secMy = secData.y;
                  const secIsLeft = secData.isLeft;
                  const secColor = (secNode.item && secNode.item.color) ? secNode.item.color : '#ee6018';
                  const secNodeId = secNode.item ? secNode.item.id : (secNode.type === 'direct-hub' ? 'hub-direct' : '');
                  const isSecModSel = currentSelection.id === secNodeId;
                  const normSecId = normModId(secNodeId);
                  const normContainerId = normModId(containerModId);

                  // Regla clave de ruido cero estricta:
                  // 1. Si hay filtro de módulos activo, NUNCA conectar hacia un módulo que no esté seleccionado
                  if (!isModAll && !selectedNormMods.has(normSecId)) {
                      return;
                  }
                  // 2. Si solo hay 1 módulo seleccionado (no multiselección), NUNCA cruzar líneas a otros módulos
                  if (!isModAll && !isMultiModSelected && !showAllSecondaryLinks) {
                      return;
                  }
                  // 3. En multiselección, encender las líneas que correlacionan los módulos seleccionados entre sí
                  const isMultiModCorrelationLink = isMultiModSelected && pMatches && selectedNormMods.has(normContainerId) && selectedNormMods.has(normSecId);
                  if (!isModAll && !isMultiModCorrelationLink && !showAllSecondaryLinks) {
                      return;
                  }

                  const pX = pData.x;
                  const pY = pData.y;
                  const pIsLeft = pX < 0;

                  let startX, startY = secMy, endX, endY = pY;
                  let cp1X, cp2X;

                  if (secIsLeft && pIsLeft) {
                      startX = secMx - 165;
                      endX = pX + 160;
                      cp1X = startX - 70;
                      cp2X = endX + 70;
                  } else if (!secIsLeft && !pIsLeft) {
                      startX = secMx + 165;
                      endX = pX - 160;
                      cp1X = startX + 70;
                      cp2X = endX - 70;
                  } else if (secIsLeft && !pIsLeft) {
                      startX = secMx + 165;
                      endX = pX - 160;
                      cp1X = startX + 220;
                      cp2X = endX - 220;
                  } else {
                      startX = secMx - 165;
                      endX = pX + 160;
                      cp1X = startX - 220;
                      cp2X = endX + 220;
                  }

                  const pSec = document.createElementNS('http://www.w3.org/2000/svg', 'path');
                  pSec.classList.add('mindmap-connector', 'secondary-module-connector');
                  pSec.setAttribute('d', `M ${startX} ${startY} C ${cp1X} ${startY}, ${cp2X} ${endY}, ${endX} ${endY}`);
                  pSec.setAttribute('fill', 'none');
                  pSec.setAttribute('data-source-proj', String(p.id));
                  pSec.setAttribute('data-target-mod', String(secNodeId));

                  const pIdClean = String(p.id).replace(/[^a-zA-Z0-9_-]/g, '');
                  const secIdClean = String(secNodeId).replace(/[^a-zA-Z0-9_-]/g, '');
                  const secGradId = `grad-sec-${pIdClean}-${secIdClean}`;

                  const sGrad = document.createElementNS('http://www.w3.org/2000/svg', 'linearGradient');
                  sGrad.setAttribute('id', secGradId);
                  sGrad.setAttribute('gradientUnits', 'userSpaceOnUse');
                  sGrad.setAttribute('x1', `${startX}`);
                  sGrad.setAttribute('y1', `${startY}`);
                  sGrad.setAttribute('x2', `${endX}`);
                  sGrad.setAttribute('y2', `${endY}`);

                  const stop1 = document.createElementNS('http://www.w3.org/2000/svg', 'stop');
                  stop1.setAttribute('offset', '0%');
                  stop1.setAttribute('stop-color', secColor);
                  stop1.setAttribute('stop-opacity', '0.88');
                  sGrad.appendChild(stop1);

                  const stop2 = document.createElementNS('http://www.w3.org/2000/svg', 'stop');
                  stop2.setAttribute('offset', '100%');
                  stop2.setAttribute('stop-color', containerModColor);
                  stop2.setAttribute('stop-opacity', '0.92');
                  sGrad.appendChild(stop2);

                  dynamicDefs.appendChild(sGrad);

                  pSec.setAttribute('stroke', `url(#${secGradId})`);
                  pSec.setAttribute('stroke-width', '1.8');

                  if (!pMatches) {
                      pSec.classList.add('sec-connector-dimmed');
                  } else if (isProjectSel || (isSecModSel && isModAll) || isMultiModCorrelationLink) {
                      pSec.classList.add('sec-connector-selected');
                      pSec.setAttribute('stroke-width', isMultiModCorrelationLink ? '2.4' : '2.2');
                  }
                  mapFrag.appendChild(pSec);
              });
          });
      });

      [...lNodes, ...rNodes].forEach(n => {
        const modId = n.item ? n.item.id : (n.type === 'direct-hub' ? 'hub-direct' : 'mod');
        const isCollapsed = isModuleCollapsed(modId, n);
        const { x: mx, y: my } = n._renderData || { x: 0, y: 0 };
        if (!isCollapsed) {
          (n.projects || []).forEach((p, idx) => {
            if (!p._renderData) return;
            const { x, y, color, type: strictType, realId } = p._renderData; 
          const isSel = currentSelection.id === realId;
          const pMatches = isDefaultState || isFiltered(p);
          
          const riskInfo = window.getProjectRiskStatus(p);
          const isOver = riskInfo && riskInfo.level === 'critical';
          const isCooling = riskInfo && riskInfo.level === 'cooling';
          const sCol = p.status==='En Progreso'?'#ee6018':(isCompletedStatus(p.status)?'#a0ca92':(p.status==='No Iniciado'?'#4d4947':'#8a8380'));

          // 1. CREACIÓN DEL CONTENEDOR PRINCIPAL
          const g = document.createElementNS('http://www.w3.org/2000/svg', 'g');
          g.setAttribute('transform', `translate(${x - 160}, ${y - 28})`);
          const pCleanId = String(realId).replace(/[^a-zA-Z0-9_-]/g, '');
          g.setAttribute('data-project-id', String(realId));
          g.setAttribute('data-parent-mod', String(modId));
          g.classList.add('mindmap-project-node', `proj-node-${pCleanId}`);
          g.style.setProperty('--start-transform', `translate(${n._renderData.x - 160}px, ${n._renderData.y - 28}px)`);
          g.style.setProperty('--end-transform', `translate(${x - 160}px, ${y - 28}px)`);
          if (lastExpandedModuleId === modId) {
              g.classList.add('proj-animate-in');
              g.style.animationDelay = `${idx * 18}ms`;
          }
          
          // ESTADO DE VISIBILIDAD Y BLOQUEO DURO
          const forceInteractive = isDefaultState;
          if (!pMatches && !forceInteractive) {
              g.setAttribute('opacity', '0.15');
              g.style.pointerEvents = 'none';
              g.classList.remove('interactive-node'); 
          } else {
              g.setAttribute('opacity', '1');
              g.style.pointerEvents = 'all'; // Captura total en el contenedor
              g.classList.add('interactive-node');
          }

          // 2. CONGELAMIENTO LÉXICO (Cierre Perfecto)
          const currentNodeType = strictType;
          const currentNodeId = realId;
          
          g.addEventListener('click', function(e) {
              e.preventDefault();
              e.stopPropagation();
              try {
                  if (p._origProj && p._renderData) p._origProj._renderData = p._renderData;
                  window.selectNode(currentNodeType, currentNodeId);
              } catch (err) { console.error('No se pudo abrir el proyecto:', p, err); window.showToast('⚠️ No se pudo abrir "' + p.name + '": ' + err.message, true); }
          }, false);

          // ILUMINACIÓN INTERACTIVA ON-DEMAND PARA PROYECTOS MULTIMÓDULO
          if (Array.isArray(p.secondaryModules) && p.secondaryModules.length > 0) {
              g.addEventListener('mouseenter', function() {
                  const conns = canvasGroup.querySelectorAll(`.secondary-module-connector[data-source-proj="${currentNodeId}"]`);
                  conns.forEach(c => c.classList.add('sec-connector-highlight'));
                  
                  p.secondaryModules.forEach(sModId => {
                      const cleanId = String(sModId === 'DIRECT' ? 'hub-direct' : sModId).replace(/[^a-zA-Z0-9_-]/g, '');
                      const targetModG = canvasGroup.querySelector(`.mod-node-${cleanId}`);
                      if (targetModG) targetModG.classList.add('target-module-highlight');
                  });
              });
              g.addEventListener('mouseleave', function() {
                  const conns = canvasGroup.querySelectorAll(`.secondary-module-connector[data-source-proj="${currentNodeId}"]`);
                  conns.forEach(c => c.classList.remove('sec-connector-highlight'));
                  
                  p.secondaryModules.forEach(sModId => {
                      const cleanId = String(sModId === 'DIRECT' ? 'hub-direct' : sModId).replace(/[^a-zA-Z0-9_-]/g, '');
                      const targetModG = canvasGroup.querySelector(`.mod-node-${cleanId}`);
                      if (targetModG) targetModG.classList.remove('target-module-highlight');
                  });
              });
          }

          // 3. CAPA VISUAL (Factory Technical Card rx=10)
          // SENSOR DE ENFRIAMIENTO Y PULSO DE RIESGO TÉCNICO
          if (riskInfo) {
              const aura = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
              aura.setAttribute('x', '-4');
              aura.setAttribute('y', '-4');
              aura.setAttribute('width', '328');
              aura.setAttribute('height', '64');
              aura.setAttribute('rx', '12');
              aura.setAttribute('fill', riskInfo.bg);
              aura.setAttribute('stroke', riskInfo.color);
              aura.setAttribute('stroke-width', '1.4');
              aura.classList.add(isCooling ? 'risk-pulse-amber' : 'risk-pulse-red');
              aura.style.pointerEvents = 'none';
              
              const titleEl = document.createElementNS('http://www.w3.org/2000/svg', 'title');
              titleEl.textContent = riskInfo.detail;
              aura.appendChild(titleEl);
              g.appendChild(aura);

              // Indicador técnico luminoso (LED táctico en esquina superior derecha)
              const ledG = document.createElementNS('http://www.w3.org/2000/svg', 'g');
              ledG.setAttribute('transform', 'translate(306, 10)');
              ledG.style.pointerEvents = 'none';
              
              const ledPing = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
              ledPing.setAttribute('r', '4');
              ledPing.setAttribute('fill', riskInfo.color);
              ledPing.classList.add(isCooling ? 'risk-dot-amber' : 'risk-dot-red');
              ledG.appendChild(ledPing);

              const ledCore = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
              ledCore.setAttribute('r', '2');
              ledCore.setAttribute('fill', '#eeeeee');
              ledG.appendChild(ledCore);
              
              g.appendChild(ledG);
          }

          const isSynergyMatch = !activeFilterConsultants.includes('ALL') && activeFilterConsultants.length >= 2 && activeFilterConsultants.every(c => getProjectConsultants(p).includes(c));
          const isModCorrMatch = isProjectModCorrelated(p);
          const projStrokeColor = isOver ? '#ee6018' : (isSynergyMatch ? generateJointGradient(activeFilterConsultants) : (color || '#ee6018'));
          if (isSel) {
              const selFrame = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
              selFrame.setAttribute('x', '-3');
              selFrame.setAttribute('y', '-3');
              selFrame.setAttribute('width', '326');
              selFrame.setAttribute('height', '62');
              selFrame.setAttribute('rx', '12');
              selFrame.setAttribute('fill', 'none');
              selFrame.setAttribute('stroke', projStrokeColor);
              selFrame.setAttribute('stroke-width', '1');
              selFrame.setAttribute('stroke-dasharray', '4,3');
              selFrame.setAttribute('opacity', '0.85');
              selFrame.style.pointerEvents = 'none';
              g.appendChild(selFrame);
          }
          const r = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
          r.setAttribute('width', '320'); r.setAttribute('height', '56'); r.setAttribute('rx', '10'); 
          r.setAttribute('fill', '#1d1a18'); 
          r.setAttribute('stroke', projStrokeColor); 
          r.setAttribute('stroke-width', isSel ? '2.2' : (isOver ? '1.6' : ((isSynergyMatch || isModCorrMatch) ? '2' : '1.2'))); 
          r.style.pointerEvents = 'none';
          if (isOver) r.classList.add('overdue-capsule');
          if (isSynergyMatch || isModCorrMatch) r.classList.add('synergy-capsule-glow');
          g.appendChild(r);

          const sC = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
          sC.setAttribute('cx', '18'); sC.setAttribute('cy', '18'); sC.setAttribute('r', '3'); 
          sC.setAttribute('fill', isOver ? '#ee6018' : sCol); 
          sC.style.pointerEvents = 'none';
          if (isOver) {
              sC.classList.add('overdue-dot');
          }
          g.appendChild(sC);

          const pComps = window.getProjectCompanies(p);
          let compBadgeOffset = 0;
          if (pComps.length > 0) {
              const mainC = pComps[0];
              const cStyle = window.getCompanyStyle ? window.getCompanyStyle(mainC) : { color: '#ee6018', bg: 'rgba(238,96,24,0.15)' };
              const bText = pComps.length > 1 ? `${mainC} +${pComps.length - 1}` : mainC;
              const bWidth = pComps.length > 1 ? 46 : 34;

              const cG = document.createElementNS('http://www.w3.org/2000/svg', 'g');
              cG.setAttribute('transform', 'translate(32, 10)');
              cG.style.pointerEvents = 'none';

              const cP = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
              cP.setAttribute('width', String(bWidth));
              cP.setAttribute('height', '14');
              cP.setAttribute('rx', '3');
              cP.setAttribute('fill', cStyle.bg);
              cP.setAttribute('stroke', cStyle.color);
              cP.setAttribute('stroke-width', '1');
              cG.appendChild(cP);

              const cT = document.createElementNS('http://www.w3.org/2000/svg', 'text');
              cT.setAttribute('x', String(bWidth / 2));
              cT.setAttribute('y', '10.5');
              cT.setAttribute('text-anchor', 'middle');
              cT.setAttribute('fill', cStyle.color);
              cT.setAttribute('style', "font-size: 8px; font-weight: 500; font-family: 'Geist Mono', monospace; letter-spacing: 0.2px;");
              cT.textContent = bText;
              cG.appendChild(cT);

              g.appendChild(cG);
              compBadgeOffset = bWidth + 5;
          }

          const hasSecBadge = Array.isArray(p.secondaryModules) && p.secondaryModules.length > 0;
          const nT = document.createElementNS('http://www.w3.org/2000/svg', 'text');
          nT.setAttribute('x', String(32 + compBadgeOffset));
          nT.setAttribute('y', '22');
          nT.setAttribute('fill', '#eeeeee'); 
          nT.classList.add('svg-text', 'svg-text-bold');
          let fullText = (isOver ? "⚠️ " : "") + p.name;
          let fontSize = fullText.length > 35 ? 9.5 : (fullText.length > 25 ? 10.5 : 12);
          nT.setAttribute('style', `font-size: ${fontSize}px; font-weight: 400; pointer-events: none;`);
          const maxNameLen = (hasSecBadge || isSynergyMatch || isModCorrMatch) ? (compBadgeOffset ? 22 : 28) : (compBadgeOffset ? 35 : 55);
          nT.textContent = fullText.length > maxNameLen ? fullText.substring(0, maxNameLen - 3)+'...' : fullText;
          g.appendChild(nT);

          // Micro-badge de multimódulo en la tarjeta del proyecto
          if (hasSecBadge) {
              const multiG = document.createElementNS('http://www.w3.org/2000/svg', 'g');
              multiG.setAttribute('transform', 'translate(252, 9)');
              multiG.style.pointerEvents = 'auto';
              multiG.style.cursor = 'pointer';

              const secModNames = p.secondaryModules.map(smId => {
                  if (smId === 'DIRECT' || smId === 'hub-direct') return 'Proyectos Directos';
                  const m = (appData.modules || []).find(x => x.id === smId);
                  return m ? m.name : smId;
              }).join(', ');

              const mTitle = document.createElementNS('http://www.w3.org/2000/svg', 'title');
              mTitle.textContent = `🔗 Vinculado a: ${secModNames} (Posa el cursor para iluminar conexiones)`;
              multiG.appendChild(mTitle);

              const mPill = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
              mPill.setAttribute('width', '38');
              mPill.setAttribute('height', '14');
              mPill.setAttribute('rx', '3');
              mPill.setAttribute('fill', isModCorrMatch ? 'rgba(238, 96, 24, 0.22)' : '#101010');
              mPill.setAttribute('stroke', isModCorrMatch ? '#ee6018' : '#3d3a39');
              mPill.setAttribute('stroke-width', '1');
              multiG.appendChild(mPill);

              const mTxt = document.createElementNS('http://www.w3.org/2000/svg', 'text');
              mTxt.setAttribute('x', '19');
              mTxt.setAttribute('y', '10.5');
              mTxt.setAttribute('text-anchor', 'middle');
              mTxt.setAttribute('fill', '#eeeeee');
              mTxt.setAttribute('style', "font-size: 8px; font-weight: 500; font-family: 'Geist Mono', monospace;");
              mTxt.textContent = `🔗+${p.secondaryModules.length}`;
              multiG.appendChild(mTxt);

              g.appendChild(multiG);
          }

          // Micro-badge destacado de Sinergia (🤝 JUNTOS) o Correlación de Módulos (🔗 CORREL)
          if (isSynergyMatch || isModCorrMatch) {
              const synG = document.createElementNS('http://www.w3.org/2000/svg', 'g');
              const synX = hasSecBadge ? 192 : 248;
              synG.setAttribute('transform', `translate(${synX}, 9)`);
              synG.style.pointerEvents = 'none';

              const synBg = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
              synBg.setAttribute('width', '54');
              synBg.setAttribute('height', '14');
              synBg.setAttribute('rx', '3');
              synBg.setAttribute('fill', 'rgba(238, 96, 24, 0.18)');
              synBg.setAttribute('stroke', '#ee6018');
              synBg.setAttribute('stroke-width', '1');
              synG.appendChild(synBg);

              const synTxt = document.createElementNS('http://www.w3.org/2000/svg', 'text');
              synTxt.setAttribute('x', '27');
              synTxt.setAttribute('y', '10.5');
              synTxt.setAttribute('text-anchor', 'middle');
              synTxt.setAttribute('fill', '#eeeeee');
              synTxt.setAttribute('style', "font-size: 7.5px; font-weight: 500; font-family: 'Geist Mono', monospace;");
              synTxt.textContent = isSynergyMatch ? '🤝 JUNTOS' : '🔗 CORREL';
              synG.appendChild(synTxt);

              g.appendChild(synG);
          }

          // Micro-Avatares de consultores asignados en la zona inferior izquierda (y = 40)
          const pConsList = getProjectConsultants(p);
          let avatarOffset = 0;
          if (pConsList.length > 0) {
              const avG = document.createElementNS('http://www.w3.org/2000/svg', 'g');
              avG.style.pointerEvents = 'auto';
              
              const avTitle = document.createElementNS('http://www.w3.org/2000/svg', 'title');
              avTitle.textContent = `Asignado a: ${pConsList.join(', ')}`;
              avG.appendChild(avTitle);

              pConsList.forEach((cName, cIdx) => {
                  const cx = 38 + cIdx * 12;
                  const cData = consultants[cName];
                  const cColor = cData?.color || '#ee6018';
                  const initial = (cName || '?').trim().charAt(0).toUpperCase();

                  const avCircle = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
                  avCircle.setAttribute('cx', String(cx));
                  avCircle.setAttribute('cy', '40');
                  avCircle.setAttribute('r', '6');
                  avCircle.setAttribute('fill', cColor);
                  avCircle.setAttribute('stroke', '#1d1a18');
                  avCircle.setAttribute('stroke-width', '1.2');
                  avG.appendChild(avCircle);

                  const avTxt = document.createElementNS('http://www.w3.org/2000/svg', 'text');
                  avTxt.setAttribute('x', String(cx));
                  avTxt.setAttribute('y', '42.5');
                  avTxt.setAttribute('text-anchor', 'middle');
                  avTxt.setAttribute('fill', '#ffffff');
                  avTxt.setAttribute('style', "font-size: 7px; font-weight: 500; font-family: 'Geist Mono', monospace; pointer-events: none;");
                  avTxt.textContent = initial;
                  avG.appendChild(avTxt);
              });
              g.appendChild(avG);
              avatarOffset = pConsList.length * 12 + 6;
          }
          
          const prog = Math.round(p.progress || 0);
          const pbStartX = 32 + avatarOffset;
          const pbMaxWidth = Math.max(30, 258 - pbStartX);

          // Pista base de la barra de progreso
          const pbBg = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
          pbBg.setAttribute('x', String(pbStartX)); pbBg.setAttribute('y', '38.5');
          pbBg.setAttribute('width', String(pbMaxWidth)); pbBg.setAttribute('height', '3');
          pbBg.setAttribute('rx', '1.5');
          pbBg.setAttribute('fill', '#101010');
          pbBg.style.pointerEvents = 'none';
          g.appendChild(pbBg);

          if (prog > 0) {
             const pb = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
             pb.setAttribute('x', String(pbStartX)); pb.setAttribute('y', '38.5');
             pb.setAttribute('width', String(Math.max(4, pbMaxWidth * (prog / 100))));
             pb.setAttribute('height', '3'); pb.setAttribute('rx', '1.5');
             pb.setAttribute('fill', isOver ? '#ee6018' : sCol);
             pb.style.pointerEvents = 'none';
             g.appendChild(pb);
          }

          // Micro indicador numérico exacto de porcentaje a la derecha
          const pPerc = document.createElementNS('http://www.w3.org/2000/svg', 'text');
          pPerc.setAttribute('x', '304'); pPerc.setAttribute('y', '42.5');
          pPerc.setAttribute('text-anchor', 'end');
          pPerc.setAttribute('fill', prog > 0 ? (prog === 100 ? '#a0ca92' : '#b8b3b0') : '#8a8380');
          pPerc.setAttribute('style', "font-size: 9.5px; font-weight: 400; font-family: 'Geist Mono', monospace; pointer-events: none;");
          pPerc.textContent = `${prog}%`;
          g.appendChild(pPerc);

          // 3.5 BADGE DE NOTIFICACIÓN DE FORO (FILTRO DE INVOLUCRAMIENTO Y MENCIONES)
          if (localAuthor && Array.isArray(p.notes) && p.notes.length > 0 && (typeof window.shouldShowProjectForumBadge !== 'function' || window.shouldShowProjectForumBadge(p, localAuthor, currentUserRole))) {
              const unreadNotes = p.notes.filter(n => {
                  if (!n) return false;
                  if (!Array.isArray(n.readBy)) {
                      return n.by !== localAuthor;
                  }
                  return !n.readBy.some(r => (typeof r === 'string' ? r : (r && r.user)) === localAuthor);
              });

              const unreadCount = unreadNotes.length;
              if (unreadCount > 0) {
                  const hasMention = unreadNotes.some(n => window.isUserMentionedInText && window.isUserMentionedInText(n.text, localAuthor));
                  const hasBlocker = unreadNotes.some(n => n.tag === 'bloqueo');

                  const badgeColor = (hasMention || hasBlocker) ? '#ee6018' : '#eeeeee';
                  const badgeTextColor = (hasMention || hasBlocker) ? '#fafafa' : '#101010';
                  const animClass = hasMention ? 'unread-mention-pulse' : (hasBlocker ? 'unread-blocker-pulse' : 'unread-purple-pulse');
                  const badgeText = hasMention ? '@' : (unreadCount > 9 ? '9+' : String(unreadCount));

                  const badgeG = document.createElementNS('http://www.w3.org/2000/svg', 'g');
                  badgeG.setAttribute('class', 'project-unread-badge');
                  badgeG.style.pointerEvents = 'none';

                  if (hasMention || unreadCount < 10) {
                      const bCircle = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
                      bCircle.setAttribute('cx', '310');
                      bCircle.setAttribute('cy', '4');
                      bCircle.setAttribute('r', '8.5');
                      bCircle.setAttribute('fill', badgeColor);
                      bCircle.setAttribute('stroke', '#101010');
                      bCircle.setAttribute('stroke-width', '1.5');
                      bCircle.setAttribute('class', animClass);
                      badgeG.appendChild(bCircle);

                      const bTxt = document.createElementNS('http://www.w3.org/2000/svg', 'text');
                      bTxt.setAttribute('x', '310');
                      bTxt.setAttribute('y', hasMention ? '7.5' : '7');
                      bTxt.setAttribute('text-anchor', 'middle');
                      bTxt.setAttribute('fill', badgeTextColor);
                      bTxt.setAttribute('style', `font-size: ${hasMention ? '10px' : '9px'}; font-weight: 500; font-family: 'Geist Mono', monospace; pointer-events: none;`);
                      bTxt.textContent = badgeText;
                      badgeG.appendChild(bTxt);
                  } else {
                      const bPill = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
                      bPill.setAttribute('x', '298');
                      bPill.setAttribute('y', '-5');
                      bPill.setAttribute('width', '24');
                      bPill.setAttribute('height', '18');
                      bPill.setAttribute('rx', '3');
                      bPill.setAttribute('fill', badgeColor);
                      bPill.setAttribute('stroke', '#101010');
                      bPill.setAttribute('stroke-width', '1.5');
                      bPill.setAttribute('class', animClass);
                      badgeG.appendChild(bPill);

                      const bTxt = document.createElementNS('http://www.w3.org/2000/svg', 'text');
                      bTxt.setAttribute('x', '310');
                      bTxt.setAttribute('y', '7.5');
                      bTxt.setAttribute('text-anchor', 'middle');
                      bTxt.setAttribute('fill', badgeTextColor);
                      bTxt.setAttribute('style', "font-size: 8.5px; font-weight: 500; font-family: 'Geist Mono', monospace; pointer-events: none;");
                      bTxt.textContent = '9+';
                      badgeG.appendChild(bTxt);
                  }

                  g.appendChild(badgeG);
              }
          }

          // 4. CAPA DE INTERCEPCIÓN (Caja invisible final con silueta continua)
          const hitBox = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
          hitBox.setAttribute('width', '320'); hitBox.setAttribute('height', '56'); hitBox.setAttribute('rx', '10');
          hitBox.setAttribute('fill', 'transparent');
          hitBox.style.cursor = 'pointer';
          g.appendChild(hitBox);
          
          mapFrag.appendChild(g);
          });
        }

        // Evaluación estricta de módulos y ghosting de bloques
        const modName = n.item ? (n.item.name || '') : '';
        const modCol = (n.item && n.item.color) ? n.item.color : '#ee6018';
        const modMatches = isModuleMatchedByFilter(modId, n);
        const { x, y } = n._renderData || { x: 0, y: 0 };
        const isSel = currentSelection.id === modId;
        const g = document.createElementNS('http://www.w3.org/2000/svg', 'g');
        g.setAttribute('transform', `translate(${x - 165}, ${y - 25})`);
        const cleanModId = String(modId).replace(/[^a-zA-Z0-9_-]/g, '');
        g.setAttribute('data-module-id', String(modId));
        g.classList.add('mindmap-module-node', `mod-node-${cleanModId}`);

        if (prevModulePositions.has(modId)) {
            const prev = prevModulePositions.get(modId);
            if (prev && (prev.x !== x || prev.y !== y)) {
                g.style.setProperty('--mod-prev-transform', `translate(${prev.x - 165}px, ${prev.y - 25}px)`);
                g.style.setProperty('--mod-curr-transform', `translate(${x - 165}px, ${y - 25}px)`);
                g.classList.add('module-slide-anim');
            }
        }
        prevModulePositions.set(modId, { x, y });
        
        if (!modMatches) {
             g.setAttribute('opacity', '0.15');
             g.style.pointerEvents = 'none';
             g.classList.remove('interactive-node');
        } else {
             g.setAttribute('opacity', '1');
             g.style.pointerEvents = 'all';
             g.classList.add('interactive-node');
        }
        
        // Pulso de riesgo a nivel módulo cuando está colapsado
        if (isCollapsed) {
            const hasCrit = (n.projects || []).some(p => { const r = window.getProjectRiskStatus(p); return r && r.level === 'critical'; });
            const hasCool = !hasCrit && (n.projects || []).some(p => { const r = window.getProjectRiskStatus(p); return r && r.level === 'cooling'; });
            if (hasCrit || hasCool) {
                const modRiskAura = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
                modRiskAura.setAttribute('x', '-3');
                modRiskAura.setAttribute('y', '-3');
                modRiskAura.setAttribute('width', '336');
                modRiskAura.setAttribute('height', '56');
                modRiskAura.setAttribute('rx', '12');
                modRiskAura.setAttribute('fill', hasCrit ? 'rgba(255, 69, 58, 0.08)' : 'rgba(255, 159, 10, 0.08)');
                modRiskAura.setAttribute('stroke', hasCrit ? '#ff453a' : '#ff9f0a');
                modRiskAura.setAttribute('stroke-width', '1.2');
                modRiskAura.classList.add(hasCrit ? 'risk-pulse-red' : 'risk-pulse-amber');
                modRiskAura.style.pointerEvents = 'none';
                g.appendChild(modRiskAura);
            }
        }

        const currentModType = n.type === 'direct-hub' ? 'direct-hub' : 'module';
        const currentModId = modId;
        
        g.addEventListener('click', function(e) {
            e.preventDefault();
            e.stopPropagation();
            window.selectNode(currentModType, currentModId);
        }, false);

        // INTERACCIÓN HOVER EN MÓDULO PARA ILUMINAR VÍNCULOS ENTRANTES
        g.addEventListener('mouseenter', function() {
            const inConns = canvasGroup.querySelectorAll(`.secondary-module-connector[data-target-mod="${modId}"]${modId === 'hub-direct' ? ', .secondary-module-connector[data-target-mod="DIRECT"]' : ''}`);
            inConns.forEach(c => c.classList.add('sec-connector-highlight'));
        });
        g.addEventListener('mouseleave', function() {
            const inConns = canvasGroup.querySelectorAll(`.secondary-module-connector[data-target-mod="${modId}"]${modId === 'hub-direct' ? ', .secondary-module-connector[data-target-mod="DIRECT"]' : ''}`);
            inConns.forEach(c => c.classList.remove('sec-connector-highlight'));
        });

        const r = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
        r.setAttribute('width', '330'); r.setAttribute('height', '50'); r.setAttribute('rx', '10'); 
        r.setAttribute('fill', n.type==='direct-hub' ? '#101010' : '#1d1a18');
        r.setAttribute('stroke', modCol); r.setAttribute('stroke-width', isSel ? '2' : '1.2');
        r.style.pointerEvents = 'none';
        if(n.type==='direct-hub') r.setAttribute('stroke-dasharray', '4,4'); 
        g.appendChild(r);

        // Indicador de color del módulo a la izquierda (6px = r=3)
        const mDot = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
        mDot.setAttribute('cx', '18'); mDot.setAttribute('cy', '25'); mDot.setAttribute('r', '3.5');
        mDot.setAttribute('fill', modCol);
        mDot.style.pointerEvents = 'none';
        g.appendChild(mDot);
        
        // Título del módulo completo sin truncamiento
        const t = document.createElementNS('http://www.w3.org/2000/svg', 'text'); 
        t.setAttribute('x', '32'); t.setAttribute('y', '29'); 
        t.setAttribute('fill', '#eeeeee'); t.setAttribute('text-anchor', 'start'); 
        t.classList.add('svg-text', 'svg-text-bold'); 
        t.style.pointerEvents = 'none';
        
        let rawName = n.item.name || '';
        let len = rawName.length;
        let mFontSize = 12;
        if (len > 35) mFontSize = 9.5;
        else if (len > 28) mFontSize = 10.5;
        else if (len > 20) mFontSize = 11.5;
        let displayName = len > 45 ? rawName.substring(0, 42) + '…' : rawName;
        t.setAttribute('style', `font-size: ${mFontSize}px; font-weight: 400; letter-spacing: -0.02em; pointer-events: none;`);
        t.textContent = displayName; 
        g.appendChild(t);

        // Micro-badge técnico de conteo de proyectos a la derecha
        const pCount = (n.ownProjects || []).length;
        const allProjsList = (appData.directProjects || []).concat((appData.modules || []).flatMap(m => m.projects || []));
        const secCount = allProjsList.filter(p => Array.isArray(p.secondaryModules) && (
            p.secondaryModules.includes(modId) ||
            (modId === 'hub-direct' && p.secondaryModules.includes('DIRECT')) ||
            (modId === 'DIRECT' && p.secondaryModules.includes('hub-direct'))
        )).length;

        const titleEl = document.createElementNS('http://www.w3.org/2000/svg', 'title');
        titleEl.textContent = `${rawName} (${pCount} propios${secCount > 0 ? `, ${secCount} vinculados` : ''})`;
        g.appendChild(titleEl);

        const countG = document.createElementNS('http://www.w3.org/2000/svg', 'g');
        countG.setAttribute('transform', secCount > 0 ? 'translate(254, 16)' : 'translate(262, 16)');
        countG.style.pointerEvents = 'none';
        
        const countBg = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
        countBg.setAttribute('width', secCount > 0 ? '62' : '52'); countBg.setAttribute('height', '18');
        countBg.setAttribute('rx', '3');
        countBg.setAttribute('fill', '#101010');
        countBg.setAttribute('stroke', modCol);
        countBg.setAttribute('stroke-opacity', '0.5');
        countBg.setAttribute('stroke-width', '1');
        countG.appendChild(countBg);
        
        const countText = document.createElementNS('http://www.w3.org/2000/svg', 'text');
        countText.setAttribute('x', secCount > 0 ? '31' : '26'); countText.setAttribute('y', '12.5');
        countText.setAttribute('text-anchor', 'middle');
        countText.setAttribute('fill', modCol);
        countText.setAttribute('style', "font-size: 8.5px; font-weight: 500; font-family: 'Geist Mono', monospace; letter-spacing: 0.02em;");
        countText.textContent = secCount > 0 ? `${pCount}+${secCount}P` : `${pCount} ${pCount === 1 ? 'PROY' : 'PROYS'}`;
        countG.appendChild(countText);
        g.appendChild(countG);

        // Capa invisible para interacción de módulos
        const hitBox = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
        hitBox.setAttribute('width', '330'); hitBox.setAttribute('height', '50'); hitBox.setAttribute('rx', '10');
        hitBox.setAttribute('fill', 'transparent');
        hitBox.style.cursor = 'pointer';
        g.appendChild(hitBox);

        // Botón interactivo de colapso/expansión (+/-) del módulo
        if (pCount > 0 || secCount > 0) {
            const isCollapsed = isModuleCollapsed(modId, n);
            const isLeft = (n._renderData && n._renderData.isLeft);
            const toggleBtnG = document.createElementNS('http://www.w3.org/2000/svg', 'g');
            toggleBtnG.classList.add('mod-toggle-btn');
            const btnX = isLeft ? -11 : 341;
            const btnY = 25;
            toggleBtnG.setAttribute('transform', `translate(${btnX}, ${btnY})`);
            
            const btnCircle = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
            btnCircle.classList.add('btn-circle-bg');
            btnCircle.setAttribute('cx', '0');
            btnCircle.setAttribute('cy', '0');
            btnCircle.setAttribute('r', '10');
            btnCircle.setAttribute('fill', '#101010');
            btnCircle.setAttribute('stroke', modCol);
            btnCircle.setAttribute('stroke-width', '1.3');
            toggleBtnG.appendChild(btnCircle);
            
            const hLine = document.createElementNS('http://www.w3.org/2000/svg', 'line');
            hLine.setAttribute('x1', '-4'); hLine.setAttribute('y1', '0');
            hLine.setAttribute('x2', '4'); hLine.setAttribute('y2', '0');
            hLine.setAttribute('stroke', '#eeeeee');
            hLine.setAttribute('stroke-width', '1.5');
            hLine.setAttribute('stroke-linecap', 'round');
            toggleBtnG.appendChild(hLine);
            
            if (isCollapsed) {
                const vLine = document.createElementNS('http://www.w3.org/2000/svg', 'line');
                vLine.setAttribute('x1', '0'); vLine.setAttribute('y1', '-4');
                vLine.setAttribute('x2', '0'); vLine.setAttribute('y2', '4');
                vLine.setAttribute('stroke', '#eeeeee');
                vLine.setAttribute('stroke-width', '1.5');
                vLine.setAttribute('stroke-linecap', 'round');
                toggleBtnG.appendChild(vLine);
            }

            // Área invisible de clic amplia para interacción inmediata
            const hitArea = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
            hitArea.setAttribute('cx', '0'); hitArea.setAttribute('cy', '0');
            hitArea.setAttribute('r', '18');
            hitArea.setAttribute('fill', 'transparent');
            hitArea.style.cursor = 'pointer';
            toggleBtnG.appendChild(hitArea);
            
            const btnTitle = document.createElementNS('http://www.w3.org/2000/svg', 'title');
            const totalExpandable = pCount > 0 ? pCount : secCount;
            btnTitle.textContent = isCollapsed ? `Expandir ${rawName} (${totalExpandable} proyectos)` : `Colapsar ${rawName}`;
            toggleBtnG.appendChild(btnTitle);
            
            toggleBtnG.addEventListener('click', function(e) {
                e.preventDefault();
                e.stopPropagation();
                window.toggleModuleCollapse(modId);
            });
            
            g.appendChild(toggleBtnG);
        }

        mapFrag.appendChild(g);
      });

      if (appData.core) appData.core._renderData = { x: 0, y: 0 };
      const totalCoreProjects = (appData.directProjects || []).length + (appData.modules || []).reduce((acc, m) => acc + (m.projects || []).length, 0);
      const isCoreSel = currentSelection.id === 'sicom';
      const coreG = document.createElementNS('http://www.w3.org/2000/svg', 'g');
      coreG.setAttribute('transform', `translate(-60, -60)`);
      coreG.classList.add('interactive-node');
      coreG.onclick = (e) => { e.stopPropagation(); window.selectNode('core', 'sicom'); };
      
      // 1. Anillo perimetral técnico sutil
      const orbit = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
      orbit.setAttribute('cx', '60'); orbit.setAttribute('cy', '60'); orbit.setAttribute('r', '68');
      orbit.setAttribute('fill', 'none');
      orbit.setAttribute('stroke', '#3d3a39');
      orbit.setAttribute('stroke-width', '1');
      orbit.setAttribute('stroke-dasharray', '3 5');
      orbit.classList.add('core-orbit-ring');
      orbit.style.pointerEvents = 'none';
      coreG.appendChild(orbit);

      // 2. Chasis exterior Obsidian (#101010)
      const ccChassis = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
      ccChassis.setAttribute('cx', '60'); ccChassis.setAttribute('cy', '60'); ccChassis.setAttribute('r', '60');
      ccChassis.setAttribute('fill', '#101010');
      ccChassis.setAttribute('stroke', isCoreSel ? '#eeeeee' : '#3d3a39');
      ccChassis.setAttribute('stroke-width', '1.2');
      ccChassis.style.pointerEvents = 'none';
      coreG.appendChild(ccChassis);

      // 3. Superficie principal Carbon Lift (#1d1a18) integrada con el resto del mapa
      const cc = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
      cc.setAttribute('cx', '60'); cc.setAttribute('cy', '60'); cc.setAttribute('r', '55');
      cc.setAttribute('fill', '#1d1a18');
      cc.setAttribute('stroke', isCoreSel ? '#eeeeee' : '#4d4947');
      cc.setAttribute('stroke-width', isCoreSel ? '1.8' : '1.2');
      cc.classList.add('core-bg-circle');
      cc.style.pointerEvents = 'none';
      coreG.appendChild(cc);

      // 4. Anillo interno de calibración
      const innerRing = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
      innerRing.setAttribute('cx', '60'); innerRing.setAttribute('cy', '60'); innerRing.setAttribute('r', '47');
      innerRing.setAttribute('fill', 'none');
      innerRing.setAttribute('stroke', '#3d3a39');
      innerRing.setAttribute('stroke-opacity', '0.55');
      innerRing.setAttribute('stroke-width', '1');
      innerRing.style.pointerEvents = 'none';
      coreG.appendChild(innerRing);

      // 5. Puertos cardinales de conexión (N, S, E, O en los puntos exactos de salida de fibra)
      [
          { cx: 60, cy: 0 },
          { cx: 60, cy: 120 },
          { cx: 0, cy: 60 },
          { cx: 120, cy: 60 }
      ].forEach(pt => {
          const port = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
          port.setAttribute('cx', String(pt.cx)); port.setAttribute('cy', String(pt.cy)); port.setAttribute('r', '3');
          port.setAttribute('fill', '#101010');
          port.setAttribute('stroke', isCoreSel ? '#eeeeee' : '#8a8380');
          port.setAttribute('stroke-width', '1.2');
          port.style.pointerEvents = 'none';
          coreG.appendChild(port);
      });

      // 6. Cápsula superior STGT con faro #ee6018
      const stgtPill = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
      stgtPill.setAttribute('x', '39'); stgtPill.setAttribute('y', '29');
      stgtPill.setAttribute('width', '42'); stgtPill.setAttribute('height', '13');
      stgtPill.setAttribute('rx', '3');
      stgtPill.setAttribute('fill', '#101010');
      stgtPill.setAttribute('stroke', '#3d3a39');
      stgtPill.setAttribute('stroke-width', '1');
      stgtPill.style.pointerEvents = 'none';
      coreG.appendChild(stgtPill);

      const coreDot = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
      coreDot.setAttribute('cx', '46'); coreDot.setAttribute('cy', '35.5'); coreDot.setAttribute('r', '2');
      coreDot.setAttribute('fill', '#ee6018');
      coreDot.classList.add('core-status-beacon');
      coreDot.style.pointerEvents = 'none';
      coreG.appendChild(coreDot);

      const coreTag = document.createElementNS('http://www.w3.org/2000/svg', 'text');
      coreTag.setAttribute('x', '52'); coreTag.setAttribute('y', '38');
      coreTag.setAttribute('fill', '#b8b3b0');
      coreTag.setAttribute('text-anchor', 'start');
      coreTag.setAttribute('style', "font-size: 7px; font-weight: 500; letter-spacing: 0.14em; font-family: 'Geist Mono', monospace; pointer-events: none;");
      coreTag.textContent = 'STGT';
      coreG.appendChild(coreTag);

      // 7. Título Principal SICOM en Hueso (#eeeeee) sobre Carbon (#1d1a18)
      const ct = document.createElementNS('http://www.w3.org/2000/svg', 'text');
      ct.setAttribute('x', '60'); ct.setAttribute('y', '60');
      ct.setAttribute('fill', '#eeeeee');
      ct.setAttribute('text-anchor', 'middle');
      ct.classList.add('svg-text');
      ct.setAttribute('style', "font-size: 16px; font-weight: 500; letter-spacing: 0.14em; font-family: 'Geist Mono', monospace; pointer-events: none;");
      ct.textContent = 'SICOM';
      coreG.appendChild(ct);

      // 8. Divisor técnico de 1px
      const coreDiv = document.createElementNS('http://www.w3.org/2000/svg', 'line');
      coreDiv.setAttribute('x1', '36'); coreDiv.setAttribute('y1', '68');
      coreDiv.setAttribute('x2', '84'); coreDiv.setAttribute('y2', '68');
      coreDiv.setAttribute('stroke', '#3d3a39');
      coreDiv.setAttribute('stroke-width', '1');
      coreDiv.style.pointerEvents = 'none';
      coreG.appendChild(coreDiv);

      // 9. Telemetría en vivo inferior (conteo de proyectos)
      const cSub = document.createElementNS('http://www.w3.org/2000/svg', 'text');
      cSub.setAttribute('x', '60'); cSub.setAttribute('y', '79');
      cSub.setAttribute('fill', '#8a8380');
      cSub.setAttribute('text-anchor', 'middle');
      cSub.classList.add('svg-text');
      cSub.setAttribute('style', "font-size: 7.5px; font-weight: 500; letter-spacing: 0.1em; font-family: 'Geist Mono', monospace; pointer-events: none;");
      cSub.textContent = `${totalCoreProjects} PROYS`;
      coreG.appendChild(cSub);

      // HitBox
      const coreHit = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
      coreHit.setAttribute('cx', '60'); coreHit.setAttribute('cy', '60'); coreHit.setAttribute('r', '68');
      coreHit.setAttribute('fill', 'transparent');
      coreHit.style.cursor = 'pointer';
      coreG.appendChild(coreHit);

      mapFrag.appendChild(coreG);

      // Reconciliación atómica en 1 solo reflow eliminando parpadeo visual (PERF-01)
      if (typeof canvasGroup.replaceChildren === 'function') {
          canvasGroup.replaceChildren(mapFrag);
      } else {
          canvasGroup.innerHTML = '';
          canvasGroup.appendChild(mapFrag);
      }

      // Calcular caja delimitadora exacta de los módulos y proyectos filtrados para auto-enfoque de cámara
      if (!isDefaultState) {
          let fMinX = Infinity, fMaxX = -Infinity, fMinY = Infinity, fMaxY = -Infinity, fCount = 0;
          [...lNodes, ...rNodes].forEach(n => {
              const modId = n.item ? n.item.id : (n.type === 'direct-hub' ? 'hub-direct' : 'mod');
              if (isModuleMatchedByFilter(modId, n) && n._renderData) {
                  fMinX = Math.min(fMinX, n._renderData.x - 180);
                  fMaxX = Math.max(fMaxX, n._renderData.x + 180);
                  fMinY = Math.min(fMinY, n._renderData.y - 40);
                  fMaxY = Math.max(fMaxY, n._renderData.y + 40);
                  fCount++;
                  (n.projects || []).forEach(p => {
                      if (p._renderData) {
                          fMinX = Math.min(fMinX, p._renderData.x - 175);
                          fMaxX = Math.max(fMaxX, p._renderData.x + 175);
                          fMinY = Math.min(fMinY, p._renderData.y - 40);
                          fMaxY = Math.max(fMaxY, p._renderData.y + 40);
                          fCount++;
                      }
                  });
              }
          });
          window._lastFilteredBounds = fCount > 0 ? { minX: fMinX, maxX: fMaxX, minY: fMinY, maxY: fMaxY, count: fCount } : null;
      } else {
          window._lastFilteredBounds = null;
      }

      // Calcular caja delimitadora global de todo el contenido visible para encuadre y candado de zoom
      let totalMinX = -80, totalMaxX = 80, totalMinY = -80, totalMaxY = 80;
      [...lNodes, ...rNodes].forEach(n => {
          if (n._renderData) {
              totalMinX = Math.min(totalMinX, n._renderData.x - 190);
              totalMaxX = Math.max(totalMaxX, n._renderData.x + 190);
              totalMinY = Math.min(totalMinY, n._renderData.y - 45);
              totalMaxY = Math.max(totalMaxY, n._renderData.y + 45);
          }
          (n.projects || []).forEach(p => {
              if (p._renderData) {
                  totalMinX = Math.min(totalMinX, p._renderData.x - 180);
                  totalMaxX = Math.max(totalMaxX, p._renderData.x + 180);
                  totalMinY = Math.min(totalMinY, p._renderData.y - 45);
                  totalMaxY = Math.max(totalMaxY, p._renderData.y + 45);
              }
          });
      });
      window._currentMapBounds = { minX: totalMinX, maxX: totalMaxX, minY: totalMinY, maxY: totalMaxY };

      lastExpandedModuleId = null;
      if (typeof window.updateActiveFilterPill === 'function') window.updateActiveFilterPill();
    };

    let currentHistoryCategory = 'all'; // 'all' | 'validaciones' | 'tareas' | 'proyectos'
    let currentHistoryAuthor = 'all'; // 'all' | author name

    window.setHistoryAuthorFilter = function(author) {
        if (!author || author === 'all' || (currentHistoryAuthor && currentHistoryAuthor.toUpperCase() === author.toUpperCase())) {
            currentHistoryAuthor = 'all';
        } else {
            currentHistoryAuthor = author;
        }
        window.renderHistory();
        const histContainer = document.getElementById('historyListContainer');
        if (histContainer && typeof histContainer.scrollIntoView === 'function') {
            histContainer.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
        }
    };

    window.setHistoryCategoryFilter = function(cat) {
        currentHistoryCategory = cat;
        ['all', 'validaciones', 'tareas', 'proyectos'].forEach(c => {
            const btn = document.getElementById(`histCatBtn-${c}`);
            if (btn) {
                if (c === cat) {
                    btn.className = 'hist-cat-btn px-2.5 py-1 rounded-[3px] font-mono text-[10px] uppercase bg-[#eeeeee] text-[#101010] border border-[#eeeeee]';
                } else {
                    btn.className = 'hist-cat-btn px-2.5 py-1 rounded-[3px] font-mono text-[10px] uppercase text-[#8a8380] hover:text-[#eeeeee] bg-[#101010] border border-[#3d3a39]';
                }
            }
        });
        window.renderHistory();
    };

    window.setHistoryFilterToday = function() {
        const dateInput = document.getElementById('historyDateFilter');
        const today = new Date();
        const tDay = String(today.getDate()).padStart(2, '0');
        const tMonth = String(today.getMonth() + 1).padStart(2, '0');
        const tYear = today.getFullYear();
        if (dateInput) dateInput.value = `${tYear}-${tMonth}-${tDay}`;
        window.renderHistory();
    };

    window.clearHistoryFilter = function() {
        const dateInput = document.getElementById('historyDateFilter');
        if (dateInput) dateInput.value = '';
        const searchInput = document.getElementById('historySearchInput');
        if (searchInput) searchInput.value = '';
        currentHistoryCategory = 'all';
        currentHistoryAuthor = 'all';
        ['all', 'validaciones', 'tareas', 'proyectos'].forEach(c => {
            const btn = document.getElementById(`histCatBtn-${c}`);
            if (btn) {
                btn.className = c === 'all' 
                    ? 'hist-cat-btn px-2.5 py-1 rounded-[3px] font-mono text-[10px] uppercase bg-[#eeeeee] text-[#101010] border border-[#eeeeee]'
                    : 'hist-cat-btn px-2.5 py-1 rounded-[3px] font-mono text-[10px] uppercase text-[#8a8380] hover:text-[#eeeeee] bg-[#101010] border border-[#3d3a39]';
            }
        });
        window.renderHistory();
    };

    window.renderHistory = function() {
        const histTab = document.getElementById('tab-history');
        if (!isDrawerOpen || (histTab && histTab.classList.contains('hidden'))) return;
        const c = document.getElementById('historyListContainer');
        const e = document.getElementById('historyEmptyState');
        const emptyMsg = document.getElementById('historyEmptyMsg');
        const filterLabel = document.getElementById('historyFilterLabel');
        const countBadge = document.getElementById('historyCountBadge');
        if (!c) return;
        
        if (!appData.history || appData.history.length === 0) { 
            c.innerHTML = ''; 
            if (e) e.classList.remove('hidden'); 
            if (emptyMsg) emptyMsg.textContent = 'Aún no hay actividades registradas en la bitácora.';
            if (countBadge) countBadge.textContent = '0 registros';
            if (filterLabel) filterLabel.textContent = 'Historial vacío';
            const pillsCont = document.getElementById('historyAuthorsPillsList');
            if (pillsCont) pillsCont.innerHTML = '';
            return; 
        }

        // 1. Renderizado de las Píldoras de Autores / Operadores con contadores
        const authorCounts = {};
        appData.history.forEach(log => {
            if (!log || !log.by) return;
            const aName = log.by.trim();
            if (!aName) return;
            authorCounts[aName] = (authorCounts[aName] || 0) + 1;
        });
        const sortedAuthors = Object.keys(authorCounts).sort((a, b) => authorCounts[b] - authorCounts[a]);

        const authorBadge = document.getElementById('histAuthorActiveBadge');
        if (authorBadge) {
            if (currentHistoryAuthor && currentHistoryAuthor !== 'all') {
                authorBadge.textContent = `Filtro: ${currentHistoryAuthor}`;
                authorBadge.classList.remove('hidden');
            } else {
                authorBadge.classList.add('hidden');
            }
        }

        const authorPillsCont = document.getElementById('historyAuthorsPillsList');
        if (authorPillsCont) {
            const isAll = (!currentHistoryAuthor || currentHistoryAuthor === 'all');
            let pillsHtml = `
              <button type="button" onclick="window.setHistoryAuthorFilter('all')" class="author-pill px-2.5 py-1 rounded-[3px] font-mono text-[10px] uppercase shrink-0 transition ${isAll ? 'bg-[#eeeeee] text-[#101010] font-semibold border border-[#eeeeee]' : 'text-[#8a8380] hover:text-[#eeeeee] bg-[#101010] border border-[#3d3a39]'}" title="Ver todos los operadores">
                TODOS (${appData.history.length})
              </button>
            `;
            sortedAuthors.forEach(a => {
                const cData = consultants[a] || Object.values(consultants).find(c => (c.name || '').toUpperCase() === a.toUpperCase()) || {};
                const col = cData.color || '#8a8380';
                const isSel = (!isAll && currentHistoryAuthor.toUpperCase() === a.toUpperCase());
                pillsHtml += `
                  <button type="button" onclick="window.setHistoryAuthorFilter('${escapeHtml(a)}')" class="author-pill px-2.5 py-1 rounded-[3px] font-mono text-[10px] uppercase shrink-0 transition flex items-center gap-1.5 ${isSel ? 'bg-[#ee6018]/20 text-[#fafafa] font-semibold border border-[#ee6018]' : 'text-[#8a8380] hover:text-[#eeeeee] bg-[#101010] border border-[#3d3a39]'}" title="Filtrar actividad de ${escapeHtml(a)}">
                    <span class="w-1.5 h-1.5 rounded-full" style="background-color: ${col}"></span>
                    <span>${escapeHtml(a)}</span>
                    <span class="text-[9px] ${isSel ? 'text-[#ee6018]' : 'text-[#8a8380]'} font-normal">(${authorCounts[a]})</span>
                  </button>
                `;
            });
            authorPillsCont.innerHTML = pillsHtml;
        }
        
        const dateInput = document.getElementById('historyDateFilter');
        const selectedDateStr = dateInput ? dateInput.value : ''; // Formato yyyy-mm-dd
        const searchInput = document.getElementById('historySearchInput');
        const q = searchInput ? searchInput.value.toLowerCase().trim() : '';
        
        let filtered = appData.history.filter(log => {
            if (!log.timestamp) return false;

            // Filtro por persona / autor
            if (currentHistoryAuthor && currentHistoryAuthor !== 'all') {
                if ((log.by || '').toUpperCase() !== currentHistoryAuthor.toUpperCase()) return false;
            }
            
            // 1. Filtro por fecha si hay fecha seleccionada
            if (selectedDateStr) {
                const datePart = log.timestamp.split(',')[0].trim();
                const parts = datePart.split('/');
                if (parts.length === 3) {
                    const day = parts[0].padStart(2, '0');
                    const month = parts[1].padStart(2, '0');
                    const year = parts[2];
                    const logFormatted = `${year}-${month}-${day}`;
                    if (logFormatted !== selectedDateStr) return false;
                } else {
                    return false;
                }
            }

            // 2. Filtro por categoría
            if (currentHistoryCategory === 'validaciones') {
                const act = (log.action || '').toLowerCase();
                if (!act.includes('validó') && !act.includes('aprobó') && !act.includes('rechazó') && !act.includes('validada')) return false;
            } else if (currentHistoryCategory === 'tareas') {
                const act = (log.action || '').toLowerCase();
                const proj = (log.projectName || '').toLowerCase();
                if (!act.includes('tarea') && !proj.includes('diaria') && !proj.includes('general')) return false;
            } else if (currentHistoryCategory === 'proyectos') {
                const act = (log.action || '').toLowerCase();
                if (!act.includes('proyecto') && !act.includes('módulo') && !act.includes('estado') && !act.includes('avance') && !act.includes('reubicó')) return false;
            }

            // 3. Filtro por búsqueda de texto
            if (q) {
                const textMatch = (log.projectName || '').toLowerCase().includes(q) ||
                                  (log.action || '').toLowerCase().includes(q) ||
                                  (log.by || '').toLowerCase().includes(q) ||
                                  (log.timestamp || '').toLowerCase().includes(q);
                if (!textMatch) return false;
            }

            return true;
        });

        if (countBadge) countBadge.textContent = `${filtered.length} de ${appData.history.length}`;
        if (filterLabel) {
            let labelParts = [];
            if (selectedDateStr) {
                const [y, m, d] = selectedDateStr.split('-');
                labelParts.push(`Fecha: ${d}/${m}/${y}`);
            }
            if (currentHistoryAuthor && currentHistoryAuthor !== 'all') {
                labelParts.push(`Persona: ${currentHistoryAuthor}`);
            }
            if (currentHistoryCategory !== 'all') {
                labelParts.push(`Categoría: ${currentHistoryCategory}`);
            }
            if (q) {
                labelParts.push(`Búsqueda: "${q}"`);
            }
            filterLabel.textContent = labelParts.length > 0 ? labelParts.join(' | ') : 'Mostrando historial completo';
        }

        if (filtered.length === 0) { 
            c.innerHTML = ''; 
            if (e) e.classList.remove('hidden'); 
            const hasFilters = selectedDateStr || q || currentHistoryCategory !== 'all' || (currentHistoryAuthor && currentHistoryAuthor !== 'all');
            if (emptyMsg) emptyMsg.textContent = hasFilters ? 'No hay registros que coincidan con los filtros aplicados.' : 'No hay registros en la bitácora.';
            return; 
        }
        
        if (e) e.classList.add('hidden');
        c.innerHTML = filtered.map(log => {
            const col = consultants[log.by] ? consultants[log.by].color : '#8a8380';
            const isVal = (log.action || '').includes('Validó') || (log.action || '').includes('Aprobó');
            const isRej = (log.action || '').includes('Rechazó');
            const isDel = (log.action || '').includes('Borró') || (log.action || '').includes('Eliminó');
            
            let tagBadge = '';
            if (isVal) tagBadge = '<span class="font-mono text-[8px] bg-[#a0ca92]/15 text-[#a0ca92] border border-[#a0ca92]/40 px-1.5 py-0.5 rounded-[3px] uppercase">Validación</span>';
            else if (isRej || isDel) tagBadge = '<span class="font-mono text-[8px] bg-[#ee6018]/15 text-[#ee6018] border border-[#ee6018]/40 px-1.5 py-0.5 rounded-[3px] uppercase">Atención</span>';

            return `<div class="bg-[#101010] border border-[#3d3a39] rounded-[10px] p-3.5 relative overflow-hidden group hover:border-[#4d4947] transition">
                <div class="absolute left-0 top-0 bottom-0 w-1 opacity-90" style="background-color: ${col}"></div>
                <div class="flex justify-between items-start mb-1.5">
                    <span class="text-[10px] text-[#8a8380] font-mono pl-1.5">${log.timestamp}</span>
                    <div class="flex items-center gap-1.5">
                        ${tagBadge}
                        <button type="button" onclick="window.setHistoryAuthorFilter('${escapeHtml(log.by)}')" class="font-mono text-[9px] px-2 py-0.5 rounded-[3px] bg-[#1d1a18] hover:bg-[#1d1a18] border border-[#3d3a39] hover:border-[#ee6018] uppercase flex items-center gap-1 text-[#eeeeee] transition cursor-pointer" title="Clic para filtrar únicamente la actividad de ${escapeHtml(log.by)}">
                            <span class="w-1.5 h-1.5 rounded-full" style="background-color: ${col}"></span>
                            <span>${escapeHtml(log.by)}</span>
                        </button>
                    </div>
                </div>
                <p class="text-xs font-normal text-[#eeeeee] mb-1 leading-tight pl-1.5">${escapeHtml(log.projectName)}</p>
                <p class="text-[11px] text-[#b8b3b0] pl-1.5 leading-relaxed">${escapeHtml(log.action)}</p>
            </div>`;
        }).join('');
    };

    window.toggleTaskFromDashboard = function(pType, projId, taskId) {
        let item = null;
        if (pType === 'direct-project') item = (appData.directProjects || []).find(x => x.id === projId);
        else (appData.modules || []).forEach(m => { const found = (m.projects || []).find(x => x.id === projId); if (found) item = found; });
        if (!item || !Array.isArray(item.tasks)) return;
        const task = item.tasks.find(t => t.id === taskId);
        if (!task) return;

        const isSuper = (currentUserRole === 'Supremo' || currentUserRole === 'Supervisor');
        if (task.done === true) {
            if (isSuper) {
                task.done = false;
                archiveTaskFeedback(task);
                delete task.validatedDate; delete task.validatedTime; delete task.validatedBy;
                logActivity(item.id, item.name, `Reabrió tarea desde dashboard: ${task.text}`, localAuthor);
                window.saveData(true); 
      window.flushCloudWrite(true);
                window.renderDashboard();
                window.showToast("Tarea reactivada", false);
            } else {
                window.showToast("Solo Supervisores pueden reabrir tareas completadas", true);
                window.renderDashboard();
            }
        } else if (task.done === 'pending') {
            if (isSuper) {
                const now = new Date();
                task.done = true;
                task.validatedDate = now.toLocaleDateString('es-MX');
                task.validatedTime = now.toLocaleTimeString('es-MX', { hour: '2-digit', minute: '2-digit' });
                task.validatedBy = localAuthor;
                const timeTrace = task.assignDate ? ` [Asignada: ${task.assignDate} ${task.assignTime || ''} ➔ Validada: ${task.validatedDate} ${task.validatedTime}]` : '';
                logActivity(item.id, item.name, `Validó tarea desde dashboard de ${task.assignee || 'consultor'}: "${task.text}"${timeTrace}`, localAuthor);
                window.sendExternalAlert('TASK_VALIDATED', {
                    project: item.name,
                    task: task.text,
                    validatedBy: localAuthor,
                    consultant: task.assignee || 'Consultor'
                });
                window.saveData(true); 
      window.flushCloudWrite(true);
                window.renderDashboard();
                window.showToast("Tarea validada", false);
                window.triggerCelebration();
            } else {
                task.done = false;
                archiveTaskFeedback(task);
                logActivity(item.id, item.name, `Canceló envío a validación desde dashboard: ${task.text}`, localAuthor);
                window.saveData(true); 
      window.flushCloudWrite(true);
                window.renderDashboard();
                window.showToast("Envío a validación cancelado", false);
            }
        } else {
            // Completar / Enviar a validar con evidencia
            window.openTaskFeedbackModal(taskId, 'project', item.id);
            setTimeout(() => window.renderDashboard(), 100);
        }
    };

    window.renderDashboard = function() {
        // Selector de perspectiva
        const scopeContainer = document.getElementById('dashScopeSelectorContainer');
        const scopeSel = document.getElementById('dashScopeSelect');
        let targetConsultant = null;

        if (scopeSel) {
            const curVal = scopeSel.value || 'GLOBAL';
            if (scopeSel.options.length <= 1) {
                scopeSel.innerHTML = '<option value="GLOBAL">🌐 Visión Global (Empresa Completa)</option>';
                Object.keys(consultants || {}).sort().forEach(c => {
                    const opt = document.createElement('option');
                    opt.value = c;
                    opt.textContent = `👤 Resumen de: ${c}`;
                    if (c === curVal) opt.selected = true;
                    scopeSel.appendChild(opt);
                });
            }
            if (scopeSel.value !== 'GLOBAL') {
                targetConsultant = scopeSel.value;
            }
        }

        // Títulos según perspectiva
        const sectionTitle = document.getElementById('dashSectionTitle');
        const telemetryBadge = document.getElementById('dashTelemetryBadge');
        const globalTitle = document.getElementById('dashGlobalTitle');
        const totalUnit = document.getElementById('dashTotalUnit');
        const slaLbl = document.getElementById('dashSlaLabel');
        const riskLbl = document.getElementById('dashRiskLabel');
        const overLbl = document.getElementById('dashOverdueLabel');
        const docsLbl = document.getElementById('dashDocsLabel');

        if (targetConsultant) {
            if (sectionTitle) sectionTitle.textContent = `Rendimiento de ${targetConsultant}`;
            if (telemetryBadge) telemetryBadge.textContent = '● RESUMEN PERSONAL';
            if (globalTitle) globalTitle.textContent = `Avance de ${targetConsultant}`;
            if (totalUnit) totalUnit.textContent = 'MIS PROY';
            if (slaLbl) slaLbl.textContent = 'Mi SLA en Plazo';
            if (riskLbl) riskLbl.textContent = 'Mis Proyectos ≤ 72h';
            if (overLbl) overLbl.textContent = 'Mis Vencidos';
            if (docsLbl) docsLbl.textContent = 'Mis Docs Validados';
        } else {
            if (sectionTitle) sectionTitle.textContent = 'Métricas Ejecutivas & KPIs';
            if (telemetryBadge) telemetryBadge.textContent = '● LIVE TELEMETRY';
            if (globalTitle) globalTitle.textContent = 'Avance Ponderado Global';
            if (totalUnit) totalUnit.textContent = 'PROY';
            if (slaLbl) slaLbl.textContent = 'SLA en Plazo';
            if (riskLbl) riskLbl.textContent = 'Riesgo ≤ 72h';
            if (overLbl) overLbl.textContent = 'Vencidos';
            if (docsLbl) docsLbl.textContent = 'Docs Normativos';
        }

        let t = 0, c = 0, p = 0, o = 0, totalProg = 0;
        let withDeadline = 0;
        let riskCount = 0;
        let totalDocsRequired = 0, totalDocsChecked = 0;

        const now = new Date();
        const todayMidnight = new Date(now.getFullYear(), now.getMonth(), now.getDate());
        const in72Hours = new Date(todayMidnight.getTime() + (3 * 24 * 60 * 60 * 1000));

        const isOver = (proj) => { 
            if (!proj.deadline || isCompletedStatus(proj.status)) return false; 
            const [y, m, d] = proj.deadline.split('-'); 
            return new Date(y, m - 1, d) < todayMidnight; 
        };

        const isRisk = (proj) => {
            if (!proj.deadline || isCompletedStatus(proj.status)) return false;
            const [y, m, d] = proj.deadline.split('-');
            const dDate = new Date(y, m - 1, d);
            return dDate >= todayMidnight && dDate <= in72Hours && (proj.progress || 0) < 80;
        };

        const countDocs = (proj) => {
            if (globalDocs && globalDocs.length > 0) {
                globalDocs.forEach(d => {
                    totalDocsRequired++;
                    const docState = proj.docs ? proj.docs[d.id] : null;
                    if (docState && (docState.checked || (docState.na && docState.naValidated))) {
                        totalDocsChecked++;
                    }
                });
            }
        };

        const tally = (proj) => {
            const projCons = getProjectConsultants(proj);
            const isAssignedToTarget = targetConsultant ? projCons.includes(targetConsultant) : true;
            if (targetConsultant && !isAssignedToTarget) return;

            t++; 
            totalProg += (proj.progress || 0); 
            if (proj.deadline) withDeadline++;
            
            const over = isOver(proj);
            const risk = isRisk(proj);
            if (over) o++;
            if (risk) riskCount++;

            if (isCompletedStatus(proj.status)) c++; 
            else if (proj.status === 'En Progreso') p++; 

            countDocs(proj);
        };

        (appData.directProjects || []).forEach(proj => { proj.pType = 'direct-project'; tally(proj); }); 
        (appData.modules || []).forEach(m => (m.projects || []).forEach(proj => { proj.pType = 'project'; tally(proj); }));

        // 1. KPI Cálculos
        const slaRate = withDeadline > 0 ? Math.max(0, Math.round(((withDeadline - o) / withDeadline) * 100)) : 100;
        const docsRate = totalDocsRequired > 0 ? Math.round((totalDocsChecked / totalDocsRequired) * 100) : 100;
        const avgGlobal = t > 0 ? Math.round(totalProg / t) : 0;

        // 2. Renderizado de Elementos DOM KPI
        const elTotal = document.getElementById('dashTotal'); if (elTotal) elTotal.textContent = t;
        const elComp = document.getElementById('dashCompleted'); if (elComp) elComp.textContent = c;
        const elProg = document.getElementById('dashProgress'); if (elProg) elProg.textContent = p;
        const elOver = document.getElementById('dashOverdue'); if (elOver) elOver.textContent = o;
        const elOverBadge = document.getElementById('dashOverdueBadge'); if (elOverBadge) elOverBadge.textContent = o;
        
        const elSlaRate = document.getElementById('dashSlaRate'); if (elSlaRate) elSlaRate.textContent = `${slaRate}%`;
        const elSlaSub = document.getElementById('dashSlaSub');
        if (elSlaSub) {
            if (slaRate >= 85) { elSlaSub.textContent = 'Excelente ritmo'; elSlaSub.className = 'font-mono text-[10px] text-[#a0ca92] uppercase truncate'; }
            else if (slaRate >= 70) { elSlaSub.textContent = 'En margen regular'; elSlaSub.className = 'font-mono text-[10px] text-[#ee6018] uppercase truncate'; }
            else { elSlaSub.textContent = 'Atención requerida'; elSlaSub.className = 'font-mono text-[10px] text-[#ee6018] uppercase truncate'; }
        }

        const elRiskCount = document.getElementById('dashRiskCount'); if (elRiskCount) elRiskCount.textContent = riskCount;
        const elRiskSub = document.getElementById('dashRiskSub'); if (elRiskSub) elRiskSub.textContent = riskCount === 1 ? '1 en riesgo' : `${riskCount} en riesgo`;

        const elDocsRate = document.getElementById('dashDocsRate'); if (elDocsRate) elDocsRate.textContent = `${docsRate}%`;
        const elDocsSub = document.getElementById('dashDocsSub'); if (elDocsSub) elDocsSub.textContent = `${totalDocsChecked} de ${totalDocsRequired} validados`;

        const elGlobalBar = document.getElementById('dashGlobalBar'); if (elGlobalBar) elGlobalBar.style.width = `${avgGlobal}%`;
        const elGlobalText = document.getElementById('dashGlobalText'); if (elGlobalText) elGlobalText.textContent = `${avgGlobal}%`;
    };

        // === DRILL-DOWN INTERACTIVO DE KPIs DEL TABLERO ===
    window._lastDrillDownIndex = window._lastDrillDownIndex || { overdue: 0, risk: 0 };

    window.drillDownKpi = function(type) {
        // 1. Cerrar el modal/drawer del tablero (Centro de Control)
        if (typeof window.closeConfigDrawer === 'function') {
            window.closeConfigDrawer();
        }

        // 2. Activar automáticamente el "Modo Enfoque" en el grafo
        if (typeof window.toggleFocusMode === 'function') {
            window.toggleFocusMode(true);
        }

        // 3. Determinar el alcance actual (consultor o global)
        const dashScopeSelect = document.getElementById('dashScopeSelect');
        const targetConsultant = (dashScopeSelect && dashScopeSelect.value !== 'GLOBAL') ? dashScopeSelect.value : null;

        // 4. Recopilar todos los proyectos disponibles
        const now = new Date();
        const todayMidnight = new Date(now.getFullYear(), now.getMonth(), now.getDate());
        const in72Hours = new Date(todayMidnight.getTime() + (3 * 24 * 60 * 60 * 1000));

        const allProjects = [];
        (appData.directProjects || []).forEach(p => {
            allProjects.push({ ...p, pType: 'direct-project', parentModId: 'hub-direct', parentName: 'Directos' });
        });
        (appData.modules || []).forEach(m => {
            (m.projects || []).forEach(p => {
                allProjects.push({ ...p, pType: 'project', parentModId: m.id, parentName: m.name });
            });
        });

        // Filtrar según el consultor objetivo si hay perspectiva activa
        const filteredProjects = targetConsultant ? allProjects.filter(p => {
            const cons = getProjectConsultants(p);
            return cons.includes(targetConsultant);
        }) : allProjects;

        let candidateList = [];
        if (type === 'overdue') {
            candidateList = filteredProjects.filter(p => {
                if (!p.deadline || isCompletedStatus(p.status)) return false;
                const [y, m, d] = p.deadline.split('-');
                return new Date(y, m - 1, d) < todayMidnight;
            });
            candidateList.sort((a, b) => (a.deadline || '').localeCompare(b.deadline || ''));
        } else if (type === 'risk') {
            candidateList = filteredProjects.filter(p => {
                if (!p.deadline || isCompletedStatus(p.status)) return false;
                const [y, m, d] = p.deadline.split('-');
                const dDate = new Date(y, m - 1, d);
                return dDate >= todayMidnight && dDate <= in72Hours && (p.progress || 0) < 80;
            });
            candidateList.sort((a, b) => (a.deadline || '').localeCompare(b.deadline || ''));
        }

        if (candidateList.length === 0) {
            const label = type === 'overdue' ? 'vencidos' : 'en riesgo ≤ 72h';
            window.showToast(`Modo Enfoque: No hay proyectos ${label} actualmente`, false);
            setTimeout(() => {
                if (typeof window.focusFilteredMindMap === 'function') window.focusFilteredMindMap();
            }, 60);
            return;
        }

        // Selección circular de proyectos candidatos
        const idx = (window._lastDrillDownIndex[type] || 0) % candidateList.length;
        window._lastDrillDownIndex[type] = idx + 1;
        const targetProj = candidateList[idx];

        // Asegurar que el módulo contenedor esté desplegado si estaba colapsado
        if (targetProj.parentModId && targetProj.parentModId !== 'hub-direct') {
            if (collapsedModules.has(targetProj.parentModId)) {
                collapsedModules.delete(targetProj.parentModId);
                lastExpandedModuleId = targetProj.parentModId;
                window.updateCollapseAllButtonState();
            }
        }

        // Renderizar mapa para actualizar posiciones bajo Modo Enfoque
        window.renderMindMap();

        // Seleccionar nodo y hacer foco/zoom directo sobre el proyecto correspondiente
        setTimeout(() => {
            window.selectNode(targetProj.pType, targetProj.id);
            const total = candidateList.length;
            const pos = idx + 1;
            const label = type === 'overdue' ? 'Vencido' : 'Riesgo ≤ 72h';
            window.showToast(`🎯 Modo Enfoque // ${label} [${pos}/${total}]: "${targetProj.name}"`, false);
        }, 120);
    };

    window.exportCSV = function() {
        let csv = "Tipo,Módulo,Empresas,Proyecto,Ticket,Estado,Avance(%),Prioridad,Fecha Límite,Envío Propuesta,Autorización,Drive,Invgate,Consultores\n";
        const addRow = (t, m, p) => { 
            const comps = (window.getProjectCompanies(p) || []).join('; ');
            const tk = (typeof getProjectTicket === 'function' ? getProjectTicket(p) : (p.ticket || '')).trim();
            const cols = [
                sanitizeCsvCell(t),
                sanitizeCsvCell(m),
                sanitizeCsvCell(comps),
                sanitizeCsvCell(p.name),
                sanitizeCsvCell(tk),
                sanitizeCsvCell(p.status || 'Pendiente'),
                sanitizeCsvCell(p.progress || 0),
                sanitizeCsvCell(p.priority || 1),
                sanitizeCsvCell(p.deadline || ''),
                sanitizeCsvCell(p.clientDeliveryDate || ''),
                sanitizeCsvCell(p.clientReturnDate || ''),
                sanitizeCsvCell(p.driveLink || ''),
                sanitizeCsvCell(p.invgateLink || ''),
                sanitizeCsvCell((getProjectConsultants(p) || []).join(', '))
            ];
            csv += cols.join(',') + "\n";
        };
        (appData.directProjects || []).forEach(p => addRow('Directo', appData.directHub?.name || 'Directo', p));
        (appData.modules || []).forEach(m => (m.projects || []).forEach(p => addRow('Módulo', m.name, p)));
        const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' }), link = document.createElement("a");
        link.href = URL.createObjectURL(blob);
        link.download = `eosa_reporte_${new Date().toISOString().slice(0,10)}.csv`;
        link.click();
    };
    
    window.exportData = function() {
      const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify({ appData, consultants, globalDocs }));
      const downloadAnchorNode = document.createElement('a'); downloadAnchorNode.setAttribute("href", dataStr); downloadAnchorNode.setAttribute("download", `eosa_backup_${new Date().toISOString().slice(0,10)}.json`); document.body.appendChild(downloadAnchorNode); downloadAnchorNode.click(); downloadAnchorNode.remove();
    };

    window.safeImportJSON = function() {
        if (confirm("⚠️ ADVERTENCIA DE SEGURIDAD:\n\nAl importar un archivo JSON se reemplazará el estado completo del sistema y se sincronizará con la nube.\n\n¿Estás seguro de que deseas continuar?")) {
            document.getElementById('importFile').click();
        }
    };

    window.safeForceCloudSync = async function() {
        const confirmation = prompt("⚠️ PELIGRO DE SOBREESCRITURA GLOBAL:\n\nEsta acción forzará los datos que tienes en este navegador hacia la base de datos central en la nube, sobreescribiendo cualquier cambio reciente realizado por otros usuarios concurrentes.\n\nPara confirmar esta acción crítica, escribe exactamente 'CONFIRMAR':");
        if (confirmation === 'CONFIRMAR') {
            await window.forceCloudSync();
        } else if (confirmation !== null) {
            window.showToast("Acción cancelada. No se alteró la nube.", false);
        }
    };

    window.importData = function(event) {
      if (currentUserRole !== 'Supremo') {
        window.showToast("🔒 Solo el perfil Supremo puede importar respaldos.", true);
        return;
      }
      const file = event.target.files[0]; if (!file) return;
      if (!file.name.toLowerCase().endsWith('.json')) {
        window.showToast("⚠️ Solo se permiten archivos con extensión .json", true);
        event.target.value = '';
        return;
      }
      if (file.size > 10 * 1024 * 1024) {
        window.showToast("⚠️ El archivo excede el límite de seguridad (10 MB)", true);
        event.target.value = '';
        return;
      }
      const reader = new FileReader();
      reader.onload = function(e) {
        try {
          const imported = JSON.parse(e.target.result);
          if(imported && typeof imported === 'object' && imported.appData && Array.isArray(imported.appData.modules) && imported.consultants && typeof imported.consultants === 'object') {
            appData = imported.appData; consultants = imported.consultants; if(Array.isArray(imported.globalDocs)) globalDocs = imported.globalDocs;
            ensureDataStructure(); window.saveData(true); refreshUI();
            window.showToast("Datos importados y verificados con éxito");
          } else {
            window.showToast("⚠️ Estructura de respaldo inválida", true);
          }
        } catch (err) { window.showToast("Error al importar archivo JSON", true); }
        event.target.value = '';
      };
      reader.readAsText(file);
    };

