    // ==========================================================================
    // SISTEMA DE COMUNICADOS, MARQUESINA Y REGLAS AUTOMÁTICAS (FACTORY TICKER)
    // ==========================================================================
    let isTickerPaused = false;
    window._tempPreviewRule = null;

    window.getActiveAnnouncements = function() {
        ensureDataStructure();
        const list = [];
        const now = new Date();
        const day = now.getDate();
        const lastDay = new Date(now.getFullYear(), now.getMonth() + 1, 0).getDate();

        // 1. Regla Quincenal (días 10 a 15 de cada mes)
        const biweeklyCalendarActive = (appData.announcementConfig && appData.announcementConfig.autoBiweeklyEnabled !== false) && (day >= 10 && day <= 15);
        const biweeklyForced = Boolean(appData.announcementConfig && appData.announcementConfig.forceBiweeklyActive);
        const biweeklyPreview = (window._tempPreviewRule === 'biweekly');

        if (biweeklyPreview || biweeklyForced || biweeklyCalendarActive) {
            let tag = 'QUINCENA (10-15)';
            if (biweeklyPreview) tag = 'PRUEBA QUINCENA';
            else if (biweeklyForced && !biweeklyCalendarActive) tag = 'AVISO QUINCENAL';

            list.push({
                id: 'auto_biweekly',
                isAuto: true,
                type: 'reminder',
                tag: tag,
                text: 'Favor de enviar sus formatos de vacaciones válidos en tiempo y forma a Administración.'
            });
        }

        // 2. Regla Cierre de Mes (días 25 al último día del mes)
        const monthEndCalendarActive = (appData.announcementConfig && appData.announcementConfig.autoMonthEndEnabled !== false) && (day >= 25 && day <= lastDay);
        const monthEndForced = Boolean(appData.announcementConfig && appData.announcementConfig.forceMonthEndActive);
        const monthEndPreview = (window._tempPreviewRule === 'monthend');

        if (monthEndPreview || monthEndForced || monthEndCalendarActive) {
            let tag = 'CIERRE MENSUAL';
            if (monthEndPreview) tag = 'PRUEBA CIERRE';

            list.push({
                id: 'auto_monthend',
                isAuto: true,
                type: 'urgent',
                tag: tag,
                text: 'Favor de enviar formatos de vacaciones y actualizar proyectos para la realización de indicadores.'
            });
        }

        // 3. Anuncios personalizados manuales
        const todayStr = now.toISOString().slice(0, 10);
        (appData.announcements || []).forEach(a => {
            if (!a || !a.active || !a.text) return;
            if (a.validFrom && a.validFrom > todayStr) return;
            if (a.validTo && a.validTo < todayStr) return;
            list.push(a);
        });

        return list;
    };

    window.renderAnnouncementsTicker = function() {
        const bar = document.getElementById('announcementTickerBar');
        const track = document.getElementById('tickerTrack');
        if (!bar || !track) return;

        const items = window.getActiveAnnouncements();
        if (!items || items.length === 0) {
            bar.classList.add('hidden');
            return;
        }

        // El panel de avisos NUNCA se oculta si hay anuncios activos (no eliminable por consultores)
        bar.classList.remove('hidden');

        const itemsHtml = items.map(ann => {
            let tagStyle = 'bg-[#0071e3]/20 text-[#2997ff] border-[#0071e3]/40';
            let tagLabel = ann.tag || 'INFO';
            if (ann.type === 'urgent') {
                tagStyle = 'bg-[#ee6018]/25 text-[#ee6018] border-[#ee6018]/50';
                if (!ann.tag) tagLabel = 'URGENTE';
            } else if (ann.type === 'reminder') {
                tagStyle = 'bg-[#f59e0b]/20 text-[#fbbf24] border-[#f59e0b]/40';
                if (!ann.tag) tagLabel = 'RECORDATORIO';
            }

            return `<span class="inline-flex items-center gap-2 mx-6 shrink-0">
                <span class="shrink-0 whitespace-nowrap px-2 py-0.5 w-auto rounded-[3px] text-[9px] font-mono uppercase font-bold tracking-wider ${tagStyle} border inline-block" style="flex-shrink: 0; white-space: nowrap; padding: 2px 8px; width: auto;">${escapeHtml(tagLabel)}</span>
                <span class="text-[#f5f5f4]">${escapeHtml(ann.text)}</span>
                <span class="text-[#55504c] font-light select-none ml-2">//</span>
            </span>`;
        }).join('');

        let repeatedHtml = itemsHtml;
        while (repeatedHtml.length < 320) {
            repeatedHtml += itemsHtml;
        }

        track.innerHTML = repeatedHtml + repeatedHtml;

        const totalChars = repeatedHtml.length;
        const durationSec = Math.max(22, Math.min(80, Math.round(totalChars * 0.1)));
        track.style.setProperty('--ticker-duration', `${durationSec}s`);
    };

    window.toggleTickerPause = function() {
        isTickerPaused = !isTickerPaused;
        const track = document.getElementById('tickerTrack');
        const iconPause = document.getElementById('iconTickerPause');
        const iconPlay = document.getElementById('iconTickerPlay');
        if (track) {
            if (isTickerPaused) {
                track.classList.add('ticker-paused');
                if (iconPause) iconPause.classList.add('hidden');
                if (iconPlay) iconPlay.classList.remove('hidden');
            } else {
                track.classList.remove('ticker-paused');
                if (iconPause) iconPause.classList.remove('hidden');
                if (iconPlay) iconPlay.classList.add('hidden');
            }
        }
    };

