window.openExecutiveDashboard = function(tabName) {
    const modal = document.getElementById('executiveDashboardModal');
    if (!modal) return;
    modal.classList.remove('hidden');
    requestAnimationFrame(() => {
        modal.classList.remove('opacity-0');
    });
    window.switchExecutiveTab(tabName || currentExecutiveTab || 'charts');
};

window.closeExecutiveDashboard = function() {
    const modal = document.getElementById('executiveDashboardModal');
    if (!modal) return;
    
    // Destrucción estricta de instancias Chart.js
    if (typeof Chart !== 'undefined' && Chart.getChart) {
        const cv = document.getElementById('execChartEstatusCanvas');
        if (cv) Chart.getChart(cv)?.destroy();
    }
    if (execChartEstatus) { execChartEstatus.destroy(); execChartEstatus = null; }

    modal.classList.add('opacity-0');
    setTimeout(() => {
        modal.classList.add('hidden');
    }, 150);
};

window.switchExecutiveTab = function(tabName) {
    currentExecutiveTab = tabName;
    const btnCharts = document.getElementById('btnTabExecCharts');
    const btnTables = document.getElementById('btnTabExecTables');
    const subCharts = document.getElementById('execSubtabCharts');
    const subTables = document.getElementById('execSubtabTables');

    if (tabName === 'charts') {
        if (btnCharts) {
            btnCharts.className = "px-3 py-1.5 rounded-[3px] font-mono text-[11px] uppercase tracking-wider transition bg-[#3d3a39] text-[#fafafa] font-semibold cursor-pointer";
        }
        if (btnTables) {
            btnTables.className = "px-3 py-1.5 rounded-[3px] font-mono text-[11px] uppercase tracking-wider transition text-[#8a8380] hover:text-[#eeeeee] cursor-pointer";
        }
        if (subCharts) subCharts.classList.remove('hidden');
        if (subTables) subTables.classList.add('hidden');
        window.renderExecutiveMatrixAndCharts();
    } else {
        if (btnCharts) {
            btnCharts.className = "px-3 py-1.5 rounded-[3px] font-mono text-[11px] uppercase tracking-wider transition text-[#8a8380] hover:text-[#eeeeee] cursor-pointer";
        }
        if (btnTables) {
            btnTables.className = "px-3 py-1.5 rounded-[3px] font-mono text-[11px] uppercase tracking-wider transition bg-[#3d3a39] text-[#fafafa] font-semibold cursor-pointer";
        }
        if (subCharts) subCharts.classList.add('hidden');
        if (subTables) subTables.classList.remove('hidden');
        window.populateExecutiveFilterDropdowns();
        window.renderExecutiveTable();
    }
};

window.getAllProjectsFlat = function() {
    const list = [];
    (appData.directProjects || []).forEach(p => {
        list.push({ ...p, isDirect: true, moduleName: 'Directo', moduleColor: '#f59e0b' });
    });
    (appData.modules || []).forEach(m => {
        (m.projects || []).forEach(p => {
            list.push({ ...p, isDirect: false, moduleName: m.name, moduleColor: m.color || '#3b82f6' });
        });
    });
    return list;
};

window.renderExecutiveMatrixAndCharts = function() {
    // 1. Renderizar KPIs y telemetría superior
    if (typeof window.renderDashboard === 'function') {
        window.renderDashboard();
    }

    const allProjs = window.getAllProjectsFlat();
    const countBadge = document.getElementById('execTotalReqCount');
    if (countBadge) countBadge.textContent = `${allProjs.length} Total`;

    // 2. Agrupación por Paquete (Compacto & Elegante)
    const paqCounts = { 'Paquete 1': 0, 'Paquete 2': 0, 'Paquete 3': 0, 'Paquete 4': 0, 'Sin paquete': 0 };
    allProjs.forEach(p => {
        const paq = p.paquete || 'Sin paquete';
        if (paqCounts[paq] !== undefined) paqCounts[paq]++;
        else paqCounts['Sin paquete']++;
    });

    const paqContainer = document.getElementById('execPaquetesContainer');
    if (paqContainer) {
        const total = allProjs.length || 1;
        const paqColors = {
            'Paquete 1': '#ee6018',
            'Paquete 2': '#f97316',
            'Paquete 3': '#fb923c',
            'Paquete 4': '#fdba74',
            'Sin paquete': '#6b7280'
        };
        paqContainer.innerHTML = Object.keys(paqCounts).map(paq => {
            const count = paqCounts[paq];
            const pct = Math.round((count / total) * 100);
            const col = paqColors[paq] || '#8a8380';
            return `
            <div onclick="window.setExecutiveDrillDown({ paquete: '${paq}' })" class="p-1.5 rounded hover:bg-[#1d1a18] cursor-pointer transition group" title="Filtrar por ${paq}">
                <div class="flex items-center justify-between mb-1">
                    <span class="text-[#eeeeee] group-hover:text-white transition font-medium text-[10px] flex items-center gap-1.5">
                        <span class="w-1.5 h-1.5 rounded-full shrink-0" style="background-color: ${col}"></span>
                        ${paq}
                    </span>
                    <span class="text-[#8a8380] text-[9px]"><strong class="text-[#fafafa] font-bold">${count}</strong> (${pct}%)</span>
                </div>
                <div class="w-full h-1.5 bg-[#181513] border border-[#3d3a39] rounded-[2px] overflow-hidden">
                    <div class="h-full rounded-[2px] transition-all duration-300" style="width: ${pct}%; background-color: ${col};"></div>
                </div>
            </div>`;
        }).join('');
    }

    // 3. Tipo de Propuesta (Compacto & Elegante)
    const propCounts = { 'Mantenimiento': 0, 'Servicio Administrado': 0, 'Venta': 0, 'Innovación': 0 };
    allProjs.forEach(p => {
        const prop = p.tipo_propuesta || 'Mantenimiento';
        if (propCounts[prop] !== undefined) propCounts[prop]++;
        else propCounts['Mantenimiento']++;
    });

    const propContainer = document.getElementById('execPropuestasContainer');
    if (propContainer) {
        const total = allProjs.length || 1;
        const propColors = {
            'Mantenimiento': '#3b82f6',
            'Servicio Administrado': '#60a5fa',
            'Venta': '#93c5fd',
            'Innovación': '#a855f7'
        };
        propContainer.innerHTML = Object.keys(propCounts).map(prop => {
            const count = propCounts[prop];
            const pct = Math.round((count / total) * 100);
            const col = propColors[prop] || '#3b82f6';
            return `
            <div onclick="window.setExecutiveDrillDown({ tipo_propuesta: '${prop}' })" class="p-1.5 rounded hover:bg-[#1d1a18] cursor-pointer transition group" title="Filtrar por ${prop}">
                <div class="flex items-center justify-between mb-1">
                    <span class="text-[#eeeeee] group-hover:text-white transition font-medium text-[10px] flex items-center gap-1.5">
                        <span class="w-1.5 h-1.5 rounded-full shrink-0" style="background-color: ${col}"></span>
                        ${prop}
                    </span>
                    <span class="text-[#8a8380] text-[9px]"><strong class="text-[#fafafa] font-bold">${count}</strong> (${pct}%)</span>
                </div>
                <div class="w-full h-1.5 bg-[#181513] border border-[#3d3a39] rounded-[2px] overflow-hidden">
                    <div class="h-full rounded-[2px] transition-all duration-300" style="width: ${pct}%; background-color: ${col};"></div>
                </div>
            </div>`;
        }).join('');
    }

    // 4. Gráfica de Estatus Oficiales (Doughnut) + Tabla Lateral
    const statusKeys = Object.keys(window.STGT_STATUS_CATALOG);
    const statusCounts = {};
    statusKeys.forEach(k => statusCounts[k] = 0);

    allProjs.forEach(p => {
        const norm = window.normalizeProjectStatus(p.status);
        if (statusCounts[norm] !== undefined) statusCounts[norm]++;
        else statusCounts['Autorizado, sin iniciar']++;
    });

    const canvasStat = document.getElementById('execChartEstatusCanvas');
    const ctxStat = canvasStat?.getContext('2d');
    if (typeof Chart !== 'undefined' && Chart.getChart && canvasStat) { Chart.getChart(canvasStat)?.destroy(); }
    if (ctxStat) {
        if (execChartEstatus) { execChartEstatus.destroy(); execChartEstatus = null; }
        execChartEstatus = new Chart(ctxStat, {
            type: 'doughnut',
            data: {
                labels: statusKeys,
                datasets: [{
                    data: statusKeys.map(k => statusCounts[k]),
                    backgroundColor: statusKeys.map(k => window.STGT_STATUS_CATALOG[k].color),
                    borderWidth: 1,
                    borderColor: '#101010'
                }]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                plugins: { legend: { display: false } },
                cutout: '68%',
                onClick: (evt, elements) => {
                    if (elements.length > 0) {
                        const idx = elements[0].index;
                        const label = statusKeys[idx];
                        window.setExecutiveDrillDown({ estado: label });
                    }
                }
            }
        });
    }

    // Mini tabla lateral de conteo y porcentaje
    const miniTable = document.getElementById('execStatusMiniTable');
    if (miniTable) {
        const tot = allProjs.length || 1;
        miniTable.innerHTML = statusKeys.map(k => {
            const c = statusCounts[k];
            const pct = Math.round((c / tot) * 100);
            const cat = window.STGT_STATUS_CATALOG[k];
            return `
            <div onclick="window.setExecutiveDrillDown({ estado: '${k}' })" class="flex items-center justify-between p-1 rounded hover:bg-[#1d1a18] cursor-pointer transition">
                <div class="flex items-center gap-1.5 truncate">
                    <span class="w-2 h-2 rounded-full shrink-0" style="background-color: ${cat.color}"></span>
                    <span class="text-[#eeeeee] truncate text-[9px]">${k}</span>
                </div>
                <div class="flex items-center gap-2 shrink-0 text-[9px]">
                    <span class="text-[#fafafa] font-bold">${c}</span>
                    <span class="text-[#8a8380] w-7 text-right">${pct}%</span>
                </div>
            </div>`;
        }).join('');
    }

    // 5. Renderizar Matriz Cruzada 9x21 FOPR-OFP-01-01
    const companies = ['AFR', 'ZIN', 'TEO', 'AVM', 'ODM', 'STGT', 'CETRAM', 'ODA', 'ACAM', 'SATEL', 'SIG', 'CSP', 'TDN', 'OVN', 'ORO', 'MOD', 'TMT', 'SGC', 'CGT', 'SLLP', 'CAE'];
    const matrixCont = document.getElementById('execMatrixContainer');
    if (matrixCont) {
        let matrixHtml = `
        <table class="w-full border-collapse text-left font-mono text-[10px]">
            <thead>
                <tr class="border-b border-[#3d3a39] bg-[#101010] text-[#8a8380] uppercase">
                    <th class="p-2 sm:p-2.5 sticky left-0 bg-[#101010] z-10 min-w-[190px]">Estatus STGT</th>
                    ${companies.map(c => `<th class="p-2 text-center min-w-[42px] cursor-help" title="${STGT_COMPANIES_MAP[c] || c}">${c}</th>`).join('')}
                    <th class="p-2 text-center bg-[#1d1a18] text-[#ee6018] min-w-[50px]">TOTAL</th>
                </tr>
            </thead>
            <tbody>
        `;

        // Calcular celdas
        statusKeys.forEach((statusName) => {
            const cat = window.STGT_STATUS_CATALOG[statusName];
            let rowTotal = 0;
            matrixHtml += `
            <tr class="border-b border-[#252220] hover:bg-[#1d1a18]/60 transition">
                <td class="p-2 sm:p-2.5 sticky left-0 bg-[#101010] z-10 flex items-center gap-2 font-medium">
                    <span class="w-2 h-2 rounded-full shrink-0" style="background-color: ${cat.color}"></span>
                    <span class="truncate" style="color: ${cat.text}">${statusName}</span>
                </td>`;

            companies.forEach(comp => {
                const count = allProjs.filter(p => {
                    const norm = window.normalizeProjectStatus(p.status);
                    const matchesComp = (p.empresa === comp) || (Array.isArray(p.companies) && p.companies.includes(comp));
                    return norm === statusName && matchesComp;
                }).length;

                rowTotal += count;

                if (count > 0) {
                    matrixHtml += `
                    <td class="p-1 text-center">
                        <button type="button" onclick="window.setExecutiveDrillDown({ empresa: '${comp}', estado: '${statusName}' })" class="px-2 py-0.5 rounded-[3px] font-mono text-[10px] font-bold transition hover:scale-110 cursor-pointer" style="background-color: ${cat.bg}; color: ${cat.color}; border: 1px solid ${cat.color}60;" title="Filtrar ${comp} en ${statusName}">
                            ${count}
                        </button>
                    </td>`;
                } else {
                    matrixHtml += `<td class="p-1 text-center text-[#3d3a39]">-</td>`;
                }
            });

            matrixHtml += `
                <td class="p-2 text-center bg-[#1d1a18] font-bold text-[#fafafa]">
                    ${rowTotal > 0 ? `<button type="button" onclick="window.setExecutiveDrillDown({ estado: '${statusName}' })" class="hover:text-[#ee6018] transition cursor-pointer font-bold">${rowTotal}</button>` : '0'}
                </td>
            </tr>`;
        });

        // Fila Total Columnas
        matrixHtml += `
            <tr class="border-t-2 border-[#3d3a39] bg-[#101010] font-bold text-[#fafafa]">
                <td class="p-2.5 sticky left-0 bg-[#101010] z-10 text-[#ee6018]">TOTAL POR EMPRESA</td>
                ${companies.map(comp => {
                    const cTot = allProjs.filter(p => {
                        return (p.empresa === comp) || (Array.isArray(p.companies) && p.companies.includes(comp));
                    }).length;
                    return `<td class="p-2 text-center ${cTot > 0 ? 'text-[#fafafa]' : 'text-[#8a8380]'}">
                        ${cTot > 0 ? `<button type="button" onclick="window.setExecutiveDrillDown({ empresa: '${comp}' })" class="hover:text-[#ee6018] transition cursor-pointer font-bold">${cTot}</button>` : '0'}
                    </td>`;
                }).join('')}
                <td class="p-2 text-center bg-[#1d1a18] text-[#ee6018] text-xs font-bold">${allProjs.length}</td>
            </tr>
            </tbody>
        </table>`;

        matrixCont.innerHTML = matrixHtml;
    }
};

window.populateExecutiveFilterDropdowns = function() {
    const allProjs = window.getAllProjectsFlat();
    
    // Empresa
    const selEmp = document.getElementById('execFilterEmpresa');
    if (selEmp && selEmp.options && selEmp.options.length <= 1) {
        const companies = ['AFR', 'ZIN', 'TEO', 'AVM', 'ODM', 'STGT', 'CETRAM', 'ODA', 'ACAM', 'SATEL', 'SIG', 'CSP', 'TDN', 'OVN', 'ORO', 'MOD', 'TMT', 'SGC', 'CGT', 'SLLP', 'CAE'];
        companies.forEach(c => {
            const opt = document.createElement('option');
            opt.value = c;
            opt.textContent = `${c} - ${STGT_COMPANIES_MAP[c] || c}`;
            selEmp.appendChild(opt);
        });
    }

    // Estatus
    const selEst = document.getElementById('execFilterEstado');
    if (selEst && selEst.options && selEst.options.length <= 1 && window.STGT_STATUS_CATALOG) {
        Object.keys(window.STGT_STATUS_CATALOG).forEach(s => {
            const opt = document.createElement('option');
            opt.value = s;
            opt.textContent = s;
            selEst.appendChild(opt);
        });
    }

    // Consultor
    const selCons = document.getElementById('execFilterConsultor');
    if (selCons && selCons.options && selCons.options.length <= 1 && typeof consultants !== 'undefined') {
        Object.keys(consultants).sort().forEach(c => {
            const opt = document.createElement('option');
            opt.value = c;
            opt.textContent = c;
            selCons.appendChild(opt);
        });
    }

    // Sincronizar valores actuales
    if (selEmp) selEmp.value = executiveTableFilter.empresa;
    if (selEst) selEst.value = executiveTableFilter.estado;
    if (selCons) selCons.value = executiveTableFilter.consultor;
    const selPaq = document.getElementById('execFilterPaquete');
    if (selPaq) selPaq.value = executiveTableFilter.paquete;
    const selProp = document.getElementById('execFilterTipoPropuesta');
    if (selProp) selProp.value = executiveTableFilter.tipo_propuesta;
};

window.handleExecutiveDropdownFilter = function() {
    const selEmp = document.getElementById('execFilterEmpresa');
    const selEst = document.getElementById('execFilterEstado');
    const selCons = document.getElementById('execFilterConsultor');
    const selPaq = document.getElementById('execFilterPaquete');
    const selProp = document.getElementById('execFilterTipoPropuesta');

    executiveTableFilter.empresa = selEmp ? selEmp.value : 'ALL';
    executiveTableFilter.estado = selEst ? selEst.value : 'ALL';
    executiveTableFilter.consultor = selCons ? selCons.value : 'ALL';
    executiveTableFilter.paquete = selPaq ? selPaq.value : 'ALL';
    executiveTableFilter.tipo_propuesta = selProp ? selProp.value : 'ALL';

    window.updateExecutiveDrillDownPill();
    window.renderExecutiveTable();
};

window.updateExecutiveDrillDownPill = function() {
    const pillCont = document.getElementById('execActiveDrillDownPill');
    const pillText = document.getElementById('execActiveDrillDownText');
    if (!pillCont || !pillText) return;

    const parts = [];
    if (executiveTableFilter.empresa !== 'ALL') parts.push(executiveTableFilter.empresa);
    if (executiveTableFilter.estado !== 'ALL') parts.push(executiveTableFilter.estado);
    if (executiveTableFilter.consultor !== 'ALL') parts.push(executiveTableFilter.consultor);
    if (executiveTableFilter.paquete !== 'ALL') parts.push(executiveTableFilter.paquete);
    if (executiveTableFilter.tipo_propuesta !== 'ALL') parts.push(executiveTableFilter.tipo_propuesta);
    
    if (parts.length > 0) {
        pillText.textContent = `Filtro: ${parts.join(' + ')}`;
        pillCont.classList.remove('hidden');
        pillCont.classList.add('inline-flex');
    } else {
        pillCont.classList.add('hidden');
        pillCont.classList.remove('inline-flex');
    }
};

window.setExecutiveDrillDown = function(patchFilter) {
    executiveTableFilter = { ...executiveTableFilter, ...patchFilter };
    window.updateExecutiveDrillDownPill();
    window.switchExecutiveTab('tables');
};

window.clearExecutiveDrillDown = function() {
    executiveTableFilter = {
        empresa: 'ALL',
        estado: 'ALL',
        consultor: 'ALL',
        paquete: 'ALL',
        tipo_propuesta: 'ALL',
        preset: 'ALL',
        search: ''
    };
    
    const pillCont = document.getElementById('execActiveDrillDownPill');
    if (pillCont) {
        pillCont.classList.add('hidden');
        pillCont.classList.remove('inline-flex');
    }
    const sInput = document.getElementById('execSearchInput');
    if (sInput) sInput.value = '';

    window.populateExecutiveFilterDropdowns();
    window.setExecutivePreset('ALL');
};

window.setExecutivePreset = function(presetKey) {
    executiveTableFilter.preset = presetKey;
    document.querySelectorAll('.exec-pill-btn').forEach(btn => {
        btn.classList.remove('bg-[#3d3a39]', 'text-[#fafafa]');
        btn.classList.add('bg-[#101010]');
    });
    const activeBtn = document.getElementById(`execPill_${presetKey}`);
    if (activeBtn) {
        activeBtn.classList.add('bg-[#3d3a39]', 'text-[#fafafa]');
        activeBtn.classList.remove('bg-[#101010]');
    }
    window.renderExecutiveTable();
};

window.handleExecutiveSearch = function(val) {
    executiveTableFilter.search = val.trim().toLowerCase();
    window.renderExecutiveTable();
};

window.renderExecutiveTable = function() {
    const safeArg = (typeof jsArg === 'function') ? jsArg : ((u) => escapeHtml(u));
    const allProjs = window.getAllProjectsFlat();
    const cont = document.getElementById('execTableContainer');
    if (!cont) return;

    const now = new Date();
    const todayMidnight = new Date(now.getFullYear(), now.getMonth(), now.getDate());
    const in72Hours = new Date(todayMidnight.getTime() + (3 * 24 * 60 * 60 * 1000));

    const filtered = allProjs.filter(p => {
        const normStatus = window.normalizeProjectStatus(p.status);
        const pEmp = p.empresa || (p.companies && p.companies[0]) || '';
        const pPaq = p.paquete || 'Sin paquete';
        const pProp = p.tipo_propuesta || 'Mantenimiento';
        const pCons = (typeof getProjectConsultants === 'function') ? getProjectConsultants(p) : (p.consultants || []);

        const matchesEmpresa = (p.empresa === executiveTableFilter.empresa) || (Array.isArray(p.companies) && p.companies.includes(executiveTableFilter.empresa));
        if (executiveTableFilter.empresa !== 'ALL' && !matchesEmpresa) return false;
        if (executiveTableFilter.estado !== 'ALL' && normStatus !== executiveTableFilter.estado) return false;
        if (executiveTableFilter.consultor !== 'ALL' && !pCons.includes(executiveTableFilter.consultor)) return false;
        if (executiveTableFilter.paquete !== 'ALL' && pPaq !== executiveTableFilter.paquete) return false;
        if (executiveTableFilter.tipo_propuesta !== 'ALL' && pProp !== executiveTableFilter.tipo_propuesta) return false;

        // Presets rápidos
        if (executiveTableFilter.preset === 'retraso_stgt' && normStatus !== 'Retraso STGT') return false;
        if (executiveTableFilter.preset === 'alta_dir' && !p.es_relevante_alta_direccion) return false;
        if (executiveTableFilter.preset === 'stgt' && !p.es_relevante_stgt) return false;
        if (executiveTableFilter.preset === 'auditoria') {
            const docs = p.docs || {};
            const hasAuditDoc = Object.values(docs).some(d => d.fecha_compromiso);
            if (!hasAuditDoc) return false;
        }
        if (executiveTableFilter.preset === 'vencidos') {
            if (!p.deadline || isCompletedStatus(p.status)) return false;
            const [y, m, d] = p.deadline.split('-');
            if (new Date(y, m - 1, d) >= todayMidnight) return false;
        }
        if (executiveTableFilter.preset === 'riesgo') {
            if (!p.deadline || isCompletedStatus(p.status)) return false;
            const [y, m, d] = p.deadline.split('-');
            const dDate = new Date(y, m - 1, d);
            if (!(dDate >= todayMidnight && dDate <= in72Hours && (p.progress || 0) < 80)) return false;
        }

        // Búsqueda de texto libre
        if (executiveTableFilter.search) {
            const q = executiveTableFilter.search;
            const textToSearch = [
                p.name, pEmp, p.moduleName, normStatus, p.observacion_ejecutiva,
                p.lider_proyecto, p.consultor, p.tester, p.programador, p.ticket, p.area_solicitante, p.paquete, p.tipo_propuesta,
                ...(p.consultants || [])
            ].join(' ').toLowerCase();
            if (!textToSearch.includes(q)) return false;
        }
        return true;
    });

    // Contador de resultados
    const resCount = document.getElementById('execFilterResultCount');
    if (resCount) {
        resCount.textContent = `Mostrando ${filtered.length} de ${allProjs.length} reqs`;
    }

    if (filtered.length === 0) {
        cont.innerHTML = `<div class="p-8 text-center text-[#8a8380] font-mono text-xs uppercase">No se encontraron requerimientos con los filtros activos. <button type="button" onclick="window.clearExecutiveDrillDown()" class="text-[#3b82f6] underline ml-1 hover:text-white">Restablecer filtros</button></div>`;
        return;
    }

    let tableHtml = `
    <table class="w-full border-collapse text-left font-mono text-xs">
        <thead>
            <tr class="border-b border-[#3d3a39] bg-[#101010] text-[#8a8380] uppercase text-[10px]">
                <th class="p-3 w-10 text-center">#</th>
                <th class="p-3">Estatus</th>
                <th class="p-3">Empresa</th>
                <th class="p-3">Aplicativo</th>
                <th class="p-3 min-w-[220px]">Requerimiento</th>
                <th class="p-3 min-w-[150px]">Responsables</th>
                <th class="p-3 min-w-[190px]">Observaciones & Comercial</th>
            </tr>
        </thead>
        <tbody class="divide-y divide-[#252220]">
    `;

    filtered.forEach((p, idx) => {
        const normStatus = window.normalizeProjectStatus(p.status);
        const cat = window.STGT_STATUS_CATALOG[normStatus] || { color: '#9ca3af', bg: 'rgba(156,163,175,0.1)' };
        const pEmp = p.empresa || (p.companies && p.companies[0]) || 'Sin asignar';
        const pType = p.isDirect ? 'direct-project' : 'project';

        // Responsables badge list
        const resps = [
            p.lider_proyecto ? `L: ${p.lider_proyecto}` : null,
            p.consultor ? `C: ${p.consultor}` : (p.consultants?.[0] ? `C: ${p.consultants[0]}` : null),
            p.tester ? `T: ${p.tester}` : null,
            p.programador ? `P: ${p.programador}` : null
        ].filter(Boolean);

        tableHtml += `
        <tr onclick="window.selectExecutiveTableRow('${safeArg(p.id)}', '${safeArg(pType)}')" class="hover:bg-[#1d1a18] cursor-pointer transition">
            <td class="p-3 text-center text-[#8a8380] text-[10px] font-medium">${idx + 1}</td>
            <td class="p-3 whitespace-nowrap">
                <span class="inline-flex items-center gap-1.5 px-2 py-0.5 rounded-[3px] font-mono text-[10px] font-semibold" style="background-color: ${cat.bg}; color: ${cat.color}; border: 1px solid ${cat.color}50;">
                    <span class="w-1.5 h-1.5 rounded-full" style="background-color: ${cat.color}"></span>
                    ${normStatus}
                </span>
            </td>
            <td class="p-3 font-semibold text-[#fafafa] whitespace-nowrap">
                <span class="px-2 py-0.5 rounded bg-[#101010] border border-[#3d3a39] text-[10px] cursor-help" title="${STGT_COMPANIES_MAP[pEmp] || pEmp}">${escapeHtml(pEmp)}</span>
            </td>
            <td class="p-3 text-[#b8b3b0] text-[11px] truncate max-w-[140px]" title="${escapeHtml(p.moduleName)}">
                ${escapeHtml(p.moduleName)}
            </td>
            <td class="p-3 font-medium text-[#eeeeee]">
                <div class="flex items-center gap-1.5 flex-wrap">
                    <span class="hover:text-[#ee6018] transition font-sans text-xs">${escapeHtml(p.name)}</span>
                    ${p.ticket ? `<span class="bg-yellow-200 text-yellow-900 font-medium border border-yellow-400 px-1 py-0.2 rounded text-[9px]">#${escapeHtml(p.ticket)}</span>` : ''}
                    ${p.area_solicitante === 'Dir. General' ? '<span class="bg-[#ef4444] text-white px-1 py-0.2 rounded text-[8px] font-bold">DIR. GEN</span>' : ''}
                </div>
            </td>
            <td class="p-3 text-[10px] text-[#8a8380]">
                ${resps.length > 0 ? resps.map(r => `<span class="inline-block bg-[#101010] border border-[#3d3a39] px-1 py-0.2 rounded mr-1 mb-0.5 text-[#eeeeee]">${escapeHtml(r)}</span>`).join('') : '<span class="text-[#4d4947]">Sin asignar</span>'}
            </td>
            <td class="p-3 text-[11px]">
                <div class="flex flex-col gap-1">
                    <div class="flex items-center gap-1.5 flex-wrap">
                        ${p.paquete && p.paquete !== 'Sin paquete' ? `<span class="text-[#ee6018] border border-[#ee6018]/40 bg-[#ee6018]/10 px-1 py-0.2 rounded text-[9px]">${escapeHtml(p.paquete)}</span>` : ''}
                        ${p.tipo_propuesta ? `<span class="text-[#60a5fa] border border-[#60a5fa]/40 bg-[#60a5fa]/10 px-1 py-0.2 rounded text-[9px]">${escapeHtml(p.tipo_propuesta)}</span>` : ''}
                        ${p.es_relevante_alta_direccion ? '<span class="text-[#eab308] text-[9px] font-semibold">⭐ Alta Dir</span>' : ''}
                        ${p.es_relevante_stgt ? '<span class="text-[#60a5fa] text-[9px] font-semibold">⚡ STGT</span>' : ''}
                    </div>
                    <span class="text-[#b8b3b0] text-[10px] italic line-clamp-2">${escapeHtml(p.observacion_ejecutiva || 'Sin observaciones')}</span>
                </div>
            </td>
        </tr>`;
    });

    tableHtml += '</tbody></table>';
    cont.innerHTML = tableHtml;
};

window.selectExecutiveTableRow = function(projId, type) {
    if (typeof window.closeExecutiveDashboard === 'function') {
        window.closeExecutiveDashboard();
    }
    if (typeof window.selectNode === 'function') {
        window.selectNode(type, projId);
    }
};

document.addEventListener('click', function(e) {
    const container = document.getElementById('priorityCreateContainer');
    if (container && !container.contains(e.target)) {
        if (typeof window.closePriorityCreateMenu === 'function') window.closePriorityCreateMenu();
    }
    const calContainer = document.getElementById('calendarCreateContainer');
    if (calContainer && !calContainer.contains(e.target)) {
        if (typeof window.closeCalendarCreateMenu === 'function') window.closeCalendarCreateMenu(); if (typeof window.closeMobileTopCreateMenu === 'function') window.closeMobileTopCreateMenu();
    }
});

    // === CALENDARIO INTERACTIVO DE ENTREGAS (ESTILO GOOGLE CALENDAR) ===
    let calendarDate = new Date(); // Fecha actual seleccionada
    let calendarViewMode = 'month'; // 'month' | 'week'
    let calendarConsultantFilter = 'ALL';

    window.calendarToday = function() {
        calendarDate = new Date();
        window.renderCalendarView();
    };

    window.calendarPrev = function() {
        if (calendarViewMode === 'month') {
            calendarDate = new Date(calendarDate.getFullYear(), calendarDate.getMonth() - 1, 1);
        } else {
            calendarDate = new Date(calendarDate.getFullYear(), calendarDate.getMonth(), calendarDate.getDate() - 7);
        }
        window.renderCalendarView();
    };

    window.calendarNext = function() {
        if (calendarViewMode === 'month') {
            calendarDate = new Date(calendarDate.getFullYear(), calendarDate.getMonth() + 1, 1);
        } else {
            calendarDate = new Date(calendarDate.getFullYear(), calendarDate.getMonth(), calendarDate.getDate() + 7);
        }
        window.renderCalendarView();
    };

    window.setCalendarViewMode = function(mode) {
        calendarViewMode = mode;
        const btnM = document.getElementById('btnCalModeMonth');
        const btnW = document.getElementById('btnCalModeWeek');
        const inact = "px-2.5 sm:px-3 py-1 rounded-[3px] font-mono uppercase text-[10px] sm:text-[11px] tracking-[-0.24px] transition text-[#b8b3b0] hover:text-[#eeeeee] cursor-pointer";
        const act = "px-2.5 sm:px-3 py-1 rounded-[3px] font-mono uppercase text-[10px] sm:text-[11px] tracking-[-0.24px] transition bg-[#eeeeee] text-[#101010] font-medium cursor-pointer";
        if (btnM) btnM.className = mode === 'month' ? act : inact;
        if (btnW) btnW.className = mode === 'week' ? act : inact;
        window.renderCalendarView();
    };

    window.setCalendarConsultantFilter = function(cVal) {
        calendarConsultantFilter = cVal;
        window.renderCalendarView();
    };

    // Compatibilidad retroactiva
    window.setTimelineConsultantFilter = window.setCalendarConsultantFilter;

    window.onCalendarPillClick = function(pType, id, e) {
        if (e) e.stopPropagation();
        window.selectNode(pType, id);
    };

    let selectedCalendarDayStr = '';
    let dayModalFilter = 'ALL';

    window.openCalendarDayModal = function(dateStr) {
        selectedCalendarDayStr = dateStr;
        const modal = document.getElementById('calendarDayModal');
        const titleEl = document.getElementById('calDayModalTitle');
        const subTitleEl = document.getElementById('calDayModalSubtitle');
        const sel = document.getElementById('calDayConsultantSelect');
        if (!modal) return;

        // Formatear fecha amigable
        const [yStr, mStr, dStr] = dateStr.split('-');
        const y = parseInt(yStr, 10);
        const m = parseInt(mStr, 10) - 1;
        const d = parseInt(dStr, 10);
        const dObj = new Date(y, m, d);

        const days = ['Domingo', 'Lunes', 'Martes', 'Miércoles', 'Jueves', 'Viernes', 'Sábado'];
        const months = ['Enero', 'Febrero', 'Marzo', 'Abril', 'Mayo', 'Junio', 'Julio', 'Agosto', 'Septiembre', 'Octubre', 'Noviembre', 'Diciembre'];
        const dayName = days[dObj.getDay()];
        const monthName = months[m];

        if (titleEl) {
            titleEl.textContent = `Agenda del ${dayName}, ${d} de ${monthName} de ${y}`;
        }

        // Segmentación por Rol para el modal
        const isConsultant = (typeof currentUserRole !== 'undefined' ? currentUserRole : '') === 'Consultor';
        if (isConsultant) {
            dayModalFilter = (typeof localAuthor !== 'undefined' ? localAuthor : 'ALL');
            if (subTitleEl) subTitleEl.textContent = `Tus compromisos y entregas asignadas para esta fecha`;
        } else {
            dayModalFilter = calendarConsultantFilter;
            if (subTitleEl) subTitleEl.textContent = `Entregas del equipo, compromisos de auditoría y tareas`;
        }

        // Llenar selector de consultores para el modal
        if (sel) {
            let htmlOpts = '<option value="ALL">👤 Todos los Responsables</option>';
            Object.keys(consultants).sort().forEach(c => {
                htmlOpts += `<option value="${escapeHtml(c)}" ${dayModalFilter === c ? 'selected' : ''}>👤 ${escapeHtml(c)}</option>`;
            });
            sel.innerHTML = htmlOpts;
            sel.value = dayModalFilter;
        }

        window.renderCalendarDayModalItems();

        modal.classList.remove('hidden');
        if (typeof window.pushNavigationState === 'function') window.pushNavigationState('calendarDayModal');
        if (typeof requestAnimationFrame === 'function') {
            requestAnimationFrame(() => {
                modal.classList.remove('opacity-0');
            });
        } else {
            setTimeout(() => {
                modal.classList.remove('opacity-0');
            }, 10);
        }
    };

    window.closeCalendarDayModal = function() {
        const modal = document.getElementById('calendarDayModal');
        if (!modal) return;
        modal.classList.add('opacity-0');
        setTimeout(() => {
            modal.classList.add('hidden');
        }, 150);
    };

    window.filterCalendarDayModal = function(val) {
        dayModalFilter = val;
        window.renderCalendarDayModalItems();
    };

    window.renderCalendarDayModalItems = function() {
        const listEl = document.getElementById('calDayItemsList');
        const badgeEl = document.getElementById('calDayModalBadge');
        if (!listEl) return;

        const allEvents = getCalendarEvents();
        let dayEvents = allEvents.filter(e => e.date === selectedCalendarDayStr);

        if (dayModalFilter !== 'ALL') {
            dayEvents = dayEvents.filter(e => e.consultants && e.consultants.includes(dayModalFilter));
        }

        if (badgeEl) {
            badgeEl.textContent = `${dayEvents.length} ENTREGA${dayEvents.length === 1 ? '' : 'S'}`;
        }

        if (dayEvents.length === 0) {
            listEl.innerHTML = `
                <div class="py-12 px-4 flex flex-col items-center justify-center text-center bg-[#101010] border border-dashed border-[#3d3a39] rounded-[10px]">
                    <span class="text-2xl mb-2">🗓️</span>
                    <h4 class="font-mono text-xs uppercase text-[#eeeeee] mb-1">Sin entregas programadas</h4>
                    <p class="text-[11px] text-[#8a8380] mb-4">No hay proyectos, documentos ni tareas asignadas con vencimiento en esta fecha.</p>
                    <button type="button" onclick="window.addFastTaskForCalendarDay()" class="px-3 py-1.5 rounded-[3px] bg-[#fafafa] hover:bg-[#eeeeee] text-[#101010] font-mono text-[10px] font-bold uppercase transition cursor-pointer">
                        + Programar Tarea
                    </button>
                </div>`;
            return;
        }

        dayEvents.sort((a, b) => a.priority - b.priority);

        listEl.innerHTML = dayEvents.map(ev => {
            const statusIcon = ev.isDone ? '✓' : (ev.isOverdue ? '🔴' : '⚡');
            const statusClass = ev.isDone ? 'text-[#a0ca92] bg-[#a0ca92]/10 border-[#a0ca92]/30' : (ev.isOverdue ? 'text-[#ef4444] bg-[#ef4444]/10 border-[#ef4444]/30' : 'text-[#ee6018] bg-[#ee6018]/10 border-[#ee6018]/30');
            const consStr = ev.consultants && ev.consultants.length > 0 ? ev.consultants.join(', ') : 'Sin asignar';
            const typeLabel = ev.type === 'doc' ? 'Auditoría PMO' : 'Entrega Proyecto';

            return `
            <div class="bg-[#101010] border border-[#3d3a39] hover:border-[#eeeeee]/60 rounded-[10px] p-3.5 transition flex flex-col gap-2.5" style="border-left: 3px solid ${ev.color}">
                <div class="flex items-center justify-between gap-2">
                    <div class="flex items-center gap-1.5">
                        <span class="font-mono text-[9px] font-bold px-1.5 py-0.2 rounded-[3px] bg-[#101010] border border-[#3d3a39] text-[#ee6018]">* ${ev.priority}</span>
                        <span class="font-mono text-[9px] uppercase px-1.5 py-0.5 rounded-[3px] border ${statusClass} font-semibold">${statusIcon} ${escapeHtml(ev.status)}</span>
                        <span class="font-mono text-[9px] uppercase px-1.5 py-0.5 rounded-[3px] bg-[#101010] border border-[#3d3a39] text-[#8a8380] hidden sm:inline">${typeLabel}</span>
                    </div>
                    <span class="font-mono text-[10px] text-[#a0ca92] font-bold">${ev.progress}% Avance</span>
                </div>

                <h4 class="text-sm font-medium text-[#eeeeee] leading-snug">${escapeHtml(ev.title)}</h4>

                <div class="flex flex-wrap items-center justify-between gap-2 pt-2 border-t border-[#3d3a39] font-mono text-[10px]">
                    <div class="flex items-center gap-2 text-[#8a8380]">
                        <span class="text-[#ee6018] font-semibold">👤 ${escapeHtml(consStr)}</span>
                        <span>·</span>
                        <span class="truncate">${escapeHtml(ev.parentName)}</span>
                    </div>

                    <div class="flex items-center gap-1.5 shrink-0">
                        <button type="button" onclick="closeCalendarDayModal(); window.selectNode('${ev.pType}', '${ev.id}')" class="px-2 py-1 rounded-[3px] bg-[#1d1a18] hover:bg-[#ee6018] hover:text-[#101010] text-[#eeeeee] border border-[#3d3a39] transition cursor-pointer font-bold">
                            Ficha Técnica ↗
                        </button>
                        <button type="button" onclick="closeCalendarDayModal(); window.jumpToMapNode('${ev.pType}', '${ev.id}')" class="px-2 py-1 rounded-[3px] bg-[#1d1a18] hover:bg-[#24211f] text-[#8a8380] hover:text-[#eeeeee] border border-[#3d3a39] transition cursor-pointer">
                            Mapa ↗
                        </button>
                    </div>
                </div>
            </div>`;
        }).join('');
    };

    window.addFastTaskForCalendarDay = function() {
        window.closeCalendarDayModal();
        if (typeof window.openFastDailyTaskModal === 'function') {
            window.openFastDailyTaskModal();
            setTimeout(() => {
                const dueIn = document.getElementById('fastTaskDueDate');
                if (dueIn && selectedCalendarDayStr) {
                    dueIn.value = selectedCalendarDayStr;
                }
            }, 100);
        }
    };

    window.onCalendarDayClick = function(dateStr, e) {
        if (e && e.target && e.target.closest('[data-cal-pill]')) return;
        window.openCalendarDayModal(dateStr);
    };

    function getCalendarEvents() {
        const events = [];
        const now = new Date();
        const todayStr = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;

        const collectProject = (p, pType, parentName, modColor) => {
            const pCons = getProjectConsultants(p);
            if (calendarConsultantFilter !== 'ALL' && !pCons.includes(calendarConsultantFilter)) {
                return;
            }

            const dLine = (p.deadline || p.clientDeliveryDate || '').trim();
            if (dLine && /^\d{4}-\d{2}-\d{2}$/.test(dLine)) {
                const isDone = isCompletedStatus(p.status);
                const isOver = !isDone && dLine < todayStr;
                events.push({
                    id: p.id,
                    pType: pType,
                    title: p.name || 'Proyecto sin nombre',
                    date: dLine,
                    type: 'project',
                    priority: parseInt(p.priority, 10) || 1,
                    status: p.status || 'No Iniciado',
                    progress: p.progress || 0,
                    consultants: pCons,
                    parentName: parentName || 'Directos',
                    color: modColor || '#ee6018',
                    isDone: isDone,
                    isOverdue: isOver
                });
            }

            if (p.docs && typeof p.docs === 'object') {
                Object.keys(p.docs).forEach(k => {
                    const doc = p.docs[k];
                    if (doc && doc.fecha_compromiso && /^\d{4}-\d{2}-\d{2}$/.test(doc.fecha_compromiso.trim())) {
                        const cDate = doc.fecha_compromiso.trim();
                        const isDocDone = !!doc.checked;
                        const isDocOver = !isDocDone && cDate < todayStr;
                        events.push({
                            id: p.id,
                            pType: pType,
                            title: `📄 ${doc.nombre || 'Doc'}: ${p.name}`,
                            date: cDate,
                            type: 'doc',
                            priority: parseInt(p.priority, 10) || 1,
                            status: isDocDone ? 'Entregado' : 'Pendiente',
                            progress: isDocDone ? 100 : 0,
                            consultants: pCons,
                            parentName: parentName || 'Directos',
                            color: isDocDone ? '#a0ca92' : '#3b82f6',
                            isDone: isDocDone,
                            isOverdue: isDocOver
                        });
                    }
                });
            }
        };

        (appData.directProjects || []).forEach(p => collectProject(p, 'direct-project', (appData.directHub && appData.directHub.name) || 'Directos', '#f59e0b'));
        (appData.modules || []).forEach(m => (m.projects || []).forEach(p => collectProject(p, 'project', m.name, m.color)));

        return events;
    }

    function getMonthGridDays(year, month) {
        const firstDay = new Date(year, month, 1);
        const lastDay = new Date(year, month + 1, 0);
        const prevMonthLastDay = new Date(year, month, 0);

        const daysInMonth = lastDay.getDate();
        const daysInPrevMonth = prevMonthLastDay.getDate();
        const startDayIndex = (firstDay.getDay() + 6) % 7; // Lunes = 0

        const days = [];

        // Días del mes anterior
        for (let i = startDayIndex - 1; i >= 0; i--) {
            const d = daysInPrevMonth - i;
            const prevMonth = month === 0 ? 11 : month - 1;
            const prevYear = month === 0 ? year - 1 : year;
            const dateStr = `${prevYear}-${String(prevMonth + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
            days.push({ dayNumber: d, dateStr, isCurrentMonth: false, dayOfWeek: (days.length) % 7 });
        }

        // Días del mes actual
        for (let d = 1; d <= daysInMonth; d++) {
            const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
            days.push({ dayNumber: d, dateStr, isCurrentMonth: true, dayOfWeek: (days.length) % 7 });
        }

        // Días del mes siguiente
        const totalSlots = days.length <= 35 ? 35 : 42;
        let nextDay = 1;
        while (days.length < totalSlots) {
            const nextMonth = month === 11 ? 0 : month + 1;
            const nextYear = month === 11 ? year + 1 : year;
            const dateStr = `${nextYear}-${String(nextMonth + 1).padStart(2, '0')}-${String(nextDay).padStart(2, '0')}`;
            days.push({ dayNumber: nextDay, dateStr, isCurrentMonth: false, dayOfWeek: (days.length) % 7 });
            nextDay++;
        }

        return days;
    }

    function getWeekDays(date) {
        const d = new Date(date);
        const day = (d.getDay() + 6) % 7; // Lunes = 0
        const monday = new Date(d);
        monday.setDate(d.getDate() - day);
        monday.setHours(0,0,0,0);

        const days = [];
        for (let i = 0; i < 7; i++) {
            const cur = new Date(monday);
            cur.setDate(monday.getDate() + i);
            const dateStr = `${cur.getFullYear()}-${String(cur.getMonth() + 1).padStart(2, '0')}-${String(cur.getDate()).padStart(2, '0')}`;
            days.push({ dayNumber: cur.getDate(), dateStr, date: cur, dayOfWeek: i });
        }
        return days;
    }

    window.renderCalendarView = function() {
        try {
            const container = document.getElementById('timelineBoardColumns');
            const countBadge = document.getElementById('timelineCountBadge');
            const cFilter = document.getElementById('timelineConsultantFilter');
            const monthLabel = document.getElementById('calMonthYearLabel');
            if (!container) return;

            if (!appData || !Array.isArray(appData.modules) || appData.modules.length === 0) {
                try { if (typeof loadLocalFallback === 'function') loadLocalFallback(); } catch(e) {}
            }

        const monthsLong = ['Enero', 'Febrero', 'Marzo', 'Abril', 'Mayo', 'Junio', 'Julio', 'Agosto', 'Septiembre', 'Octubre', 'Noviembre', 'Diciembre'];
        const y = calendarDate.getFullYear();
        const m = calendarDate.getMonth();

        if (monthLabel) {
            if (calendarViewMode === 'month') {
                monthLabel.textContent = `${monthsLong[m]} ${y}`;
            } else {
                const wDays = getWeekDays(calendarDate);
                const firstD = wDays[0].dayNumber;
                const lastD = wDays[6].dayNumber;
                const lastM = wDays[6].date.getMonth();
                monthLabel.textContent = `${firstD} - ${lastD} ${monthsLong[lastM].slice(0,3)} ${y}`;
            }
        }

        // Llenar selector de consultores si está vacío
        if (cFilter && cFilter.options.length <= 1) {
            let htmlOpts = '<option value="ALL">👤 Todos</option>';
            Object.keys(consultants).sort().forEach(c => {
                htmlOpts += `<option value="${escapeHtml(c)}">👤 ${escapeHtml(c)}</option>`;
            });
            cFilter.innerHTML = htmlOpts;
            cFilter.value = calendarConsultantFilter;
        }

        const events = getCalendarEvents();
        if (countBadge) {
            countBadge.textContent = `${events.length} ENTREGA${events.length === 1 ? '' : 'S'}`;
        }

        const now = new Date();
        const todayStr = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;

        if (calendarViewMode === 'month') {
            // === VISTA MENSUAL (CUADRÍCULA 7 COLUMNAS) ===
            const gridDays = getMonthGridDays(y, m);
            const dayHeaders = [
                { name: 'LUN', full: 'Lunes' },
                { name: 'MAR', full: 'Martes' },
                { name: 'MIÉ', full: 'Miércoles' },
                { name: 'JUE', full: 'Jueves' },
                { name: 'VIE ★', full: 'Viernes', isFriday: true },
                { name: 'SÁB', full: 'Sábado' },
                { name: 'DOM', full: 'Domingo' }
            ];

            let html = '<div class="flex-1 flex flex-col min-h-0 bg-[#101010]">';
            
            // Fila de encabezados de días
            html += '<div class="grid grid-cols-7 border-b border-[#3d3a39] bg-[#101010] shrink-0">';
            dayHeaders.forEach(dh => {
                html += `
                <div class="py-2 px-1 text-center font-mono text-[10px] sm:text-[11px] font-semibold tracking-wider ${dh.isFriday ? 'text-[#ee6018] bg-[#ee6018]/10' : 'text-[#8a8380]'}">
                    <span class="sm:hidden">${dh.name.slice(0, 1)}${dh.isFriday ? '★' : ''}</span>
                    <span class="hidden sm:inline">${dh.name}</span>
                </div>`;
            });
            html += '</div>';

            // Cuadrícula de días
            const numRows = gridDays.length / 7;
            html += `<div class="flex-1 grid grid-cols-7 min-h-0 border-b border-[#3d3a39] divide-x divide-y divide-[#24211f] overflow-y-auto" style="grid-template-rows: repeat(${numRows}, minmax(0, 1fr));">`;

            gridDays.forEach(gd => {
                const isToday = gd.dateStr === todayStr;
                const isFriday = gd.dayOfWeek === 4;
                const dayEvents = events.filter(e => e.date === gd.dateStr);

                dayEvents.sort((a, b) => a.priority - b.priority);

                let pillsHtml = '';
                const maxDisplay = 3;
                dayEvents.slice(0, maxDisplay).forEach(ev => {
                    const statusIcon = ev.isDone ? '✓' : (ev.isOverdue ? '🔴' : '⚡');
                    pillsHtml += `
                    <div data-cal-pill="true" onclick="window.onCalendarPillClick('${ev.pType}', '${ev.id}', event)" class="group flex items-center justify-between gap-1 px-1.5 py-0.5 rounded-[3px] bg-[#181615] hover:bg-[#1d1a18] border border-[#3d3a39] hover:border-[#eeeeee] transition text-[9px] sm:text-[10px] font-mono cursor-pointer select-none truncate" style="border-left: 2px solid ${ev.color}" title="${escapeHtml(ev.title)} (${ev.status})">
                      <span class="text-[8px] sm:text-[9px] shrink-0">${statusIcon}</span>
                      <span class="truncate text-[#eeeeee] group-hover:text-[#fafafa]">${escapeHtml(ev.title)}</span>
                      <span class="text-[#8a8380] text-[8px] shrink-0 hidden sm:inline">${ev.progress}%</span>
                    </div>`;
                });

                if (dayEvents.length > maxDisplay) {
                    const remaining = dayEvents.length - maxDisplay;
                    pillsHtml += `<div onclick="event.stopPropagation(); window.openCalendarDayModal('${gd.dateStr}')" class="text-[8px] sm:text-[9px] font-mono text-[#ee6018] hover:underline px-1 cursor-pointer font-bold">+ ${remaining} más...</div>`;
                }

                html += `
                <div onclick="window.onCalendarDayClick('${gd.dateStr}', event)" class="flex flex-col p-1 sm:p-1.5 min-h-0 overflow-hidden ${gd.isCurrentMonth ? 'bg-[#121110]' : 'bg-[#0a0a09]'} ${isToday ? 'ring-1 ring-[#ee6018] ring-inset bg-[#1a1512]' : ''} hover:bg-[#181615] transition cursor-pointer group relative">
                  <div class="flex items-center justify-between mb-1 shrink-0">
                    <span class="${isToday ? 'w-5 h-5 rounded-full bg-[#ee6018] text-[#101010] font-bold flex items-center justify-center text-[10px]' : (gd.isCurrentMonth ? 'text-[#eeeeee] text-[10px] sm:text-[11px] font-mono' : 'text-[#55504d] text-[10px]')}">
                      ${gd.dayNumber}
                    </span>
                    ${isFriday ? '<span class="hidden sm:inline font-mono text-[8px] text-[#ee6018] font-bold tracking-tight">VIE</span>' : ''}
                    ${dayEvents.length > 0 ? `<span class="sm:hidden font-mono text-[8px] px-1 rounded-[3px] bg-[#1d1a18] text-[#ee6018] font-bold">${dayEvents.length}</span>` : ''}
                  </div>
                  <div class="flex-1 overflow-y-auto space-y-1 scrollbar-none">
                    ${pillsHtml}
                  </div>
                </div>`;
            });

            html += '</div></div>';
            container.innerHTML = html;

        } else {
            // === VISTA SEMANAL (7 COLUMNAS DETALLADAS) ===
            const weekDays = getWeekDays(calendarDate);
            const dayNames = ['Lunes', 'Martes', 'Miércoles', 'Jueves', 'Viernes', 'Sábado', 'Domingo'];

            let html = '<div class="flex-1 flex overflow-x-auto divide-x divide-[#24211f] bg-[#101010] p-2 sm:p-4 gap-2 sm:gap-3">';

            weekDays.forEach(wd => {
                const isToday = wd.dateStr === todayStr;
                const isFriday = wd.dayOfWeek === 4;
                const dayEvents = events.filter(e => e.date === wd.dateStr);
                dayEvents.sort((a, b) => a.priority - b.priority);

                let cardsHtml = '';
                if (dayEvents.length === 0) {
                    cardsHtml = `<div class="h-32 flex flex-col items-center justify-center text-center p-3 font-mono text-[10px] text-[#55504d] border border-dashed border-[#3d3a39] rounded-[10px]">Sin entregas</div>`;
                } else {
                    cardsHtml = dayEvents.map(ev => {
                        const statusIcon = ev.isDone ? '✓' : (ev.isOverdue ? '🔴' : '⚡');
                        const statusClass = ev.isDone ? 'text-[#a0ca92]' : (ev.isOverdue ? 'text-[#ef4444]' : 'text-[#ee6018]');
                        const isSelected = currentSelection && currentSelection.id === ev.id;

                        return `
                        <div data-node-id="${ev.id}" onclick="window.selectNode('${ev.pType}', '${ev.id}')" class="bg-[#101010] hover:bg-[#1c1917] border ${isSelected ? 'border-[#ee6018] ring-2 ring-[#ee6018]' : 'border-[#3d3a39] hover:border-[#eeeeee]/60'} rounded-[10px] p-2.5 transition cursor-pointer flex flex-col gap-1.5" style="border-left: 3px solid ${ev.color}">
                          <div class="flex items-center justify-between gap-1">
                            <span class="font-mono text-[9px] font-bold px-1.5 py-0.2 rounded-[3px] bg-[#101010] border border-[#3d3a39] text-[#ee6018]">* ${ev.priority}</span>
                            <span class="font-mono text-[9px] ${statusClass} font-semibold">${statusIcon} ${ev.status}</span>
                          </div>
                          <h4 class="text-xs font-medium text-[#eeeeee] leading-snug line-clamp-2 hover:text-[#fafafa]">${escapeHtml(ev.title)}</h4>
                          <div class="flex items-center justify-between gap-1 pt-1 border-t border-[#3d3a39] font-mono text-[9px] text-[#8a8380]">
                            <span class="truncate">${ev.consultants && ev.consultants.length > 0 ? '👤 ' + escapeHtml(ev.consultants.join(', ')) : 'Sin asignar'}</span>
                            <div class="flex items-center gap-1 shrink-0" onclick="event.stopPropagation()">
                              <button type="button" onclick="window.jumpToMapNode('${ev.pType}', '${ev.id}', event)" class="px-1.5 py-0.5 rounded-[3px] bg-[#1d1a18] hover:bg-[#ee6018] hover:text-[#101010] text-[#b8b3b0] transition" title="Ver en el mapa">Mapa ↗</button>
                            </div>
                          </div>
                        </div>`;
                    }).join('');
                }

                html += `
                <div class="w-64 sm:w-72 shrink-0 bg-[#121110] border ${isToday ? 'border-[#ee6018]' : 'border-[#3d3a39]'} rounded-[10px] flex flex-col overflow-hidden">
                  <div class="p-2.5 sm:p-3 bg-[#181615] border-b border-[#3d3a39] flex items-center justify-between ${isFriday ? 'border-t-2 border-t-[#ee6018]' : ''}">
                    <div class="flex items-center gap-2">
                      <span class="${isToday ? 'w-5 h-5 rounded-full bg-[#ee6018] text-[#101010] font-bold flex items-center justify-center text-[10px]' : 'font-mono text-xs font-semibold text-[#fafafa]'}">
                        ${wd.dayNumber}
                      </span>
                      <span class="font-mono text-[11px] sm:text-xs font-semibold uppercase text-[#eeeeee]">${dayNames[wd.dayOfWeek]}</span>
                      ${isFriday ? '<span class="font-mono text-[8px] px-1 py-0.5 rounded-[3px] bg-[#ee6018]/20 text-[#ee6018] font-bold">ENTREGA</span>' : ''}
                    </div>
                    <span class="font-mono text-[10px] px-1.5 py-0.5 rounded-[3px] bg-[#101010] border border-[#3d3a39] text-[#8a8380] font-medium">${dayEvents.length}</span>
                  </div>
                  <div class="flex-1 overflow-y-auto p-2 sm:p-2.5 pb-28 sm:pb-2.5 space-y-2 scrollbar-thin">
                    ${cardsHtml}
                  </div>
                </div>`;
            });

            html += '</div>';
            container.innerHTML = html;
        }
        } catch (err) {
            console.error('⚠️ [Calendario] Error al renderizar vista:', err);
        }
    };

    // Alias para compatibilidad
    window.renderTimelineBoard = window.renderCalendarView;

