window.ensurePdfLibReady = async function() {
    if (typeof PDFLib !== 'undefined' && PDFLib.PDFDocument) return true;
    return new Promise((resolve) => {
        const s = document.createElement('script');
        s.src = 'https://cdn.jsdelivr.net/npm/pdf-lib@1.17.1/dist/pdf-lib.min.js';
        s.onload = () => resolve(typeof PDFLib !== 'undefined');
        s.onerror = () => resolve(false);
        document.head.appendChild(s);
    });
};

window.ensurePdfJsReady = async function() {
    if (typeof pdfjsLib !== 'undefined' && pdfjsLib.getDocument) {
        if (pdfjsLib.GlobalWorkerOptions && !pdfjsLib.GlobalWorkerOptions.workerSrc) {
            pdfjsLib.GlobalWorkerOptions.workerSrc = 'https://cdn.jsdelivr.net/npm/pdfjs-dist@3.11.174/build/pdf.worker.min.js';
        }
        return true;
    }
    return new Promise((resolve) => {
        const s = document.createElement('script');
        s.src = 'https://cdn.jsdelivr.net/npm/pdfjs-dist@3.11.174/build/pdf.min.js';
        s.onload = () => {
            if (typeof pdfjsLib !== 'undefined' && pdfjsLib.GlobalWorkerOptions) {
                pdfjsLib.GlobalWorkerOptions.workerSrc = 'https://cdn.jsdelivr.net/npm/pdfjs-dist@3.11.174/build/pdf.worker.min.js';
            }
            const w = document.createElement('script');
            w.src = 'https://cdn.jsdelivr.net/npm/pdfjs-dist@3.11.174/build/pdf.worker.min.js';
            w.onload = () => resolve(typeof pdfjsLib !== 'undefined');
            w.onerror = () => resolve(typeof pdfjsLib !== 'undefined');
            document.head.appendChild(w);
        };
        s.onerror = () => resolve(false);
        document.head.appendChild(s);
    });
};

// Extrae con exactitud matemática todas las filas de la tabla "Firmas de Aceptación" (y "Historial de Actualizaciones")
async function extractSignatureTableRows(page) {
    try {
        const tc = await page.getTextContent();
        const items = tc.items || [];
        const norm = (s) => (s || '').toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").trim();

        let footerY = 90;
        for (const it of items) {
            const s = norm(it.str);
            if (s.startsWith('elaboro') || s.startsWith('codigo:')) {
                if (it.transform[5] < 200 && it.transform[5] > footerY) {
                    footerY = it.transform[5];
                }
            }
        }

        let acceptIdx = items.findIndex(it => norm(it.str).includes('firmas de aceptacion'));
        const hasAcceptSection = (acceptIdx !== -1);
        if (acceptIdx === -1) acceptIdx = 0;

        let headerY = 650;
        for (let i = acceptIdx; i < items.length; i++) {
            const s = norm(items[i].str);
            if (s === 'nombre' || s.includes('autorizacion') || s.includes('puesto')) {
                headerY = items[i].transform[5];
                break;
            }
        }

        const rowMap = new Map();
        for (let i = acceptIdx; i < items.length; i++) {
            const it = items[i];
            const str = (it.str || '').trim();
            if (!str) continue;
            const x = it.transform[4];
            const y = it.transform[5];
            if (y >= headerY - 10 || y <= footerY + 12) continue;

            let matchedKey = null;
            for (const k of rowMap.keys()) {
                if (Math.abs(k - y) <= 8) { matchedKey = k; break; }
            }
            if (matchedKey === null) {
                matchedKey = Math.round(y);
                rowMap.set(matchedKey, { y: matchedKey, roleParts: [], nameParts: [] });
            }
            const row = rowMap.get(matchedKey);
            if (x >= 140 && x < 295) row.roleParts.push(str);
            else if (x >= 295 && x <= 465) row.nameParts.push(str);
        }

        const acceptRows = Array.from(rowMap.values())
            .filter(r => r.nameParts.length > 0 || r.roleParts.length > 0)
            .sort((a, b) => b.y - a.y)
            .map(r => ({
                section: 'aceptacion',
                role: r.roleParts.join(' ') || 'Autorización',
                name: r.nameParts.join(' '),
                rowY: r.y,
                stampX: 480,
                stampY: Math.round(r.y - 10)
            }));

        // Detectar también fila de "Historial de Actualizaciones" / "Solicitante" si existe arriba de Firmas de Aceptación
        const histIdx = items.findIndex(it => norm(it.str).includes('historial de actualizaciones'));
        if (histIdx !== -1 && hasAcceptSection && acceptIdx > histIdx) {
            const acceptTitleY = items[acceptIdx].transform[5] || 490;
            let histHeaderY = 572;
            for (let i = histIdx; i < acceptIdx; i++) {
                const s = norm(items[i].str);
                if (s.includes('solicitante') || s === 'firma') {
                    histHeaderY = items[i].transform[5];
                    break;
                }
            }
            const histNames = [];
            const histYs = [];
            for (let i = histIdx; i < acceptIdx; i++) {
                const it = items[i];
                const str = (it.str || '').trim();
                if (!str) continue;
                const x = it.transform[4];
                const y = it.transform[5];
                if (y < histHeaderY - 8 && y > acceptTitleY + 15 && x >= 310 && x <= 465) {
                    histNames.push(str);
                    histYs.push(y);
                }
            }
            if (histNames.length > 0) {
                const avgY = Math.round(histYs.reduce((a, b) => a + b, 0) / histYs.length);
                acceptRows.push({
                    section: 'historial',
                    role: 'Solicitante / Elaboró',
                    name: histNames.join(' '),
                    rowY: avgY,
                    stampX: 480,
                    stampY: Math.round(avgY - 12)
                });
            }
        }

        return acceptRows;
    } catch (e) {
        console.warn("Error extrayendo filas de tabla de firmas:", e);
        return [];
    }
}

window.analyzePdfSignatureTable = async function() {
    if (!activeSignDocCtx.pdfBytes) return [];
    try {
        await window.ensurePdfJsReady();
        if (typeof pdfjsLib === 'undefined') return [];

        let bytesCopy = null;
        if (activeSignDocCtx.pdfBytes instanceof Uint8Array) {
            bytesCopy = new Uint8Array(activeSignDocCtx.pdfBytes.buffer.slice(activeSignDocCtx.pdfBytes.byteOffset, activeSignDocCtx.pdfBytes.byteOffset + activeSignDocCtx.pdfBytes.byteLength));
        } else if (activeSignDocCtx.pdfBytes instanceof ArrayBuffer) {
            bytesCopy = new Uint8Array(activeSignDocCtx.pdfBytes.slice(0));
        } else {
            bytesCopy = new Uint8Array(activeSignDocCtx.pdfBytes);
        }

        const pdf = await pdfjsLib.getDocument({ data: bytesCopy }).promise;
        activeSignDocCtx.pdfPageCount = pdf.numPages;
        const page = await pdf.getPage(pdf.numPages);
        const rows = await extractSignatureTableRows(page);
        activeSignDocCtx.detectedRows = rows;
        return rows;
    } catch (e) {
        console.warn("Fallo en analyzePdfSignatureTable:", e);
        return [];
    }
};

// Resuelve con precisión matemática la casilla exacta enfrente del nombre del firmante, evitando colisiones o encabezados
window.resolveExactStampCoordsForSigner = function(signer, signerIdx = 0, circuit = [], detectedRows = []) {
    const norm = (s) => (s || '').toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").trim();
    const signerNameNorm = norm(signer?.name);
    const signerRoleNorm = norm(signer?.role);
    const nameTokens = signerNameNorm.split(/\s+/).filter(w => w.length > 2);
    const roleTokens = signerRoleNorm.split(/\s+/).filter(w => w.length > 3);

    const rows = (Array.isArray(detectedRows) && detectedRows.length > 0)
        ? detectedRows
        : (activeSignDocCtx.detectedRows || []);

    // Coordenadas Y ya ocupadas por firmantes anteriores en el mismo circuito
    const usedYs = [];
    for (let i = 0; i < circuit.length; i++) {
        if (i === signerIdx) continue;
        const other = circuit[i];
        if (other && other.status === 'signed' && other.coords && typeof other.coords.y === 'number' && other.coords.y <= 585 && other.coords.y >= 150) {
            usedYs.push(other.coords.y);
        }
    }
    const isYUsed = (y) => usedYs.some(uY => Math.abs(uY - y) < 12);

    if (rows.length > 0) {
        // 1. Buscar coincidencia directa por NOMBRE o ALIAS en la tabla del PDF
        for (const r of rows) {
            const rNameNorm = norm(r.name);
            const matchesByToken = nameTokens.length > 0 && nameTokens.some(t => rNameNorm.includes(t));
            const matchesByAlias = window.isSameUserOrAlias(r.name, signer?.name);
            if ((matchesByToken || matchesByAlias) && !isYUsed(r.stampY)) {
                return { x: r.stampX, y: r.stampY, label: `${r.name} (${r.role})` };
            }
        }
        // Si el nombre coincide aunque otra firma ya haya usado esa fila (ej. si no hay otra con ese nombre), permitir coincidencia exacta de nombre si no hay otra libre
        for (const r of rows) {
            const rNameNorm = norm(r.name);
            const matchesByToken = nameTokens.length > 0 && nameTokens.some(t => rNameNorm.includes(t));
            const matchesByAlias = window.isSameUserOrAlias(r.name, signer?.name);
            if (matchesByToken || matchesByAlias) {
                if (!isYUsed(r.stampY)) {
                    return { x: r.stampX, y: r.stampY, label: `${r.name} (${r.role})` };
                }
            }
        }

        // 2. Buscar coincidencia por PUESTO / ROL en filas libres de "Firmas de Aceptación"
        const acceptOnly = rows.filter(r => r.section === 'aceptacion');
        for (const r of acceptOnly) {
            const rRoleNorm = norm(r.role);
            const matchesRole = roleTokens.length > 0 && roleTokens.some(t => rRoleNorm.includes(t));
            if (matchesRole && !isYUsed(r.stampY)) {
                return { x: r.stampX, y: r.stampY, label: `${r.name} (${r.role})` };
            }
        }

        // 3. Asignar la primera fila libre de "Firmas de Aceptación" según el orden del firmante
        const freeAccept = acceptOnly.filter(r => !isYUsed(r.stampY));
        if (freeAccept.length > 0) {
            const chosen = freeAccept[Math.min(signerIdx, freeAccept.length - 1)] || freeAccept[0];
            return { x: chosen.stampX, y: chosen.stampY, label: `${chosen.name} (${chosen.role})` };
        }

        const chosenAny = rows[Math.min(signerIdx, rows.length - 1)];
        return { x: chosenAny.stampX, y: chosenAny.stampY, label: `${chosenAny.name} (${chosenAny.role})` };
    }

    // 4. Mapa de respaldo oficial STGT cuando aún no hay filas extraídas
    const standardSlots = [
        { key: 'romero', x: 480, y: 300, label: 'Rafael Romero (Coordinador)' },
        { key: 'barbosa', x: 480, y: 333, label: 'Miguel Ángel Barbosa (Gerente)' },
        { key: 'perez', x: 480, y: 367, label: 'Jesús Perez (Gerente TI)' },
        { key: 'osvaldo', x: 480, y: 535, label: 'Emmanuel Osvaldo Sánchez (Solicitante)' }
    ];

    if (signerNameNorm.includes('barbosa') && !isYUsed(333)) return standardSlots[1];
    if (signerNameNorm.includes('romero') && !isYUsed(300)) return standardSlots[0];
    if (signerNameNorm.includes('perez') && !isYUsed(367)) return standardSlots[2];
    if ((signerNameNorm.includes('osvaldo') || signerNameNorm.includes('avil') || signerNameNorm.includes('sanchez') || signerNameNorm.includes('emmanuel')) && !isYUsed(535)) {
        return standardSlots[3];
    }

    const freeStd = standardSlots.filter(s => !isYUsed(s.y));
    if (freeStd.length > 0) return freeStd[Math.min(signerIdx, freeStd.length - 1)];
    return standardSlots[signerIdx % standardSlots.length];
};

window.renderDetectedSlotsBar = function() {
    const bar = document.getElementById('docSignDetectedSlotsBar');
    const list = document.getElementById('docSignDetectedSlotsList');
    if (!bar || !list) return;

    const rows = activeSignDocCtx.detectedRows || [];
    if (!activeSignDocCtx.pdfBytes || rows.length === 0) {
        bar.classList.add('hidden');
        bar.classList.remove('flex');
        return;
    }

    bar.classList.remove('hidden');
    bar.classList.add('flex');

    const curY = Number(activeSignDocCtx.stampY) || 300;
    list.innerHTML = rows.map((r, idx) => {
        const isSelected = Math.abs(r.stampY - curY) <= 10;
        const isMobile = (window.innerWidth < 640);
        const nameTokens = r.name.split(/\s+/).filter(Boolean);
        const shortName = isMobile 
            ? (nameTokens[0] + (nameTokens[1] ? ' ' + nameTokens[1][0] + '.' : ''))
            : nameTokens.slice(0, 2).join(' ');
        return `<button type="button" onclick="window.selectDetectedSignatureSlot(${idx})" class="px-2 py-0.5 rounded font-mono text-[9px] transition cursor-pointer border ${isSelected ? 'bg-[#ee6018] text-white border-[#ee6018] font-bold shadow-sm' : 'bg-[#101010] text-[#b8b3b0] border-[#3d3a39] hover:border-[#ee6018] hover:text-white'}" title="Colocar firma exactamente enfrente de ${escapeHtml(r.name)} (${escapeHtml(r.role)})">
            ${isSelected ? '✓ ' : ''}${escapeHtml(shortName)}
        </button>`;
    }).join('');
};

window.selectDetectedSignatureSlot = function(idx) {
    const rows = activeSignDocCtx.detectedRows || [];
    const r = rows[idx];
    if (!r) return;
    activeSignDocCtx.stampX = r.stampX;
    activeSignDocCtx.stampY = r.stampY;
    activeSignDocCtx.selectedSlotLabel = `${r.name} (${r.role})`;
    activeSignDocCtx.userManuallyPickedCoords = true;

    // Si estamos en otra página, regresar a la última página donde está la tabla de firmas
    if (activeSignDocCtx.pdfPageCount && activeSignDocCtx.currentPageNum !== activeSignDocCtx.pdfPageCount) {
        activeSignDocCtx.currentPageNum = activeSignDocCtx.pdfPageCount;
        window.renderLastPdfPage();
    } else {
        window.updateStampTargetVisual();
        window.renderDetectedSlotsBar();
    }
    window.showToast(`🎯 Casilla seleccionada: Enfrente de ${r.name}`, false);
};

window.syncCircuitFromPdfTable = async function() {
    const item = getProjectById(activeSignDocCtx.projectId);
    if (!item || !item.docs || !item.docs[activeSignDocCtx.docId]) return;
    const docData = item.docs[activeSignDocCtx.docId];

    if (!activeSignDocCtx.detectedRows || activeSignDocCtx.detectedRows.length === 0) {
        await window.analyzePdfSignatureTable();
    }
    const rows = (activeSignDocCtx.detectedRows || []).filter(r => r.section === 'aceptacion');
    if (rows.length === 0) {
        window.showToast("⚠️ Sube primero el PDF oficial para leer la tabla de firmantes.", true);
        return;
    }

    // Ordenar de abajo hacia arriba (Coordinador -> Gerente Consultoría -> Gerente TI) o en el orden de la tabla
    const ordered = [...rows].reverse();
    docData.signatureCircuit = ordered.map((r, i) => ({
        id: `sig_pdf_${Date.now()}_${i}`,
        role: r.role || 'Autorizó',
        name: r.name,
        status: 'pending',
        coords: { x: r.stampX, y: r.stampY, page: activeSignDocCtx.pdfPageCount || 1 }
    }));

    activeSignDocCtx.lastAutoSignerId = null;
    activeSignDocCtx.userManuallyPickedCoords = false;
    window.saveData(false);
    window.renderDocSignCircuitList();
    window.updateDocSignStatusBadge();
    await window.renderLastPdfPage();
    if (typeof window.renderDailyTasks === 'function') window.renderDailyTasks();
    window.showToast(`⚡ Circuito actualizado con los ${ordered.length} firmantes de la tabla del PDF.`, false);
};

window.resetDocumentSignatures = async function() {
    if (!confirm("¿Deseas reiniciar todas las firmas de este documento para comenzar de nuevo el circuito?")) return;
    const item = getProjectById(activeSignDocCtx.projectId);
    if (!item || !item.docs || !item.docs[activeSignDocCtx.docId]) return;
    const docData = item.docs[activeSignDocCtx.docId];
    const circuit = docData.signatureCircuit || [];

    circuit.forEach(s => {
        s.status = 'pending';
        delete s.signedAt;
        delete s.signedBy;
        delete s.signaturePng;
        delete s.injectedInPdf;
        delete s.coords;
    });
    docData.checked = false;
    delete docData.pdfPurged;
    delete docData.lastStampX;
    delete docData.lastStampY;

    // Restaurar el PDF limpio sin firmas
    if (activeSignDocCtx.cleanPdfBytes) {
        activeSignDocCtx.pdfBytes = new Uint8Array(activeSignDocCtx.cleanPdfBytes);
        if (window.SICOM_IDB && activeSignDocCtx.pdfKey) {
            await window.SICOM_IDB.save(activeSignDocCtx.pdfKey, activeSignDocCtx.pdfBytes);
        }
    } else if (activeSignDocCtx.pdfBytes) {
        await window.restoreCleanPdfPageInMemory();
    } else {
        // Si no hay PDF cargado o fue purgado
        document.getElementById('docSignCanvasWrapper')?.classList.add('hidden');
        const placeholder = document.getElementById('docSignNoPdfPlaceholder');
        if (placeholder) {
            placeholder.classList.remove('hidden');
            placeholder.innerHTML = `
                <svg class="w-8 h-8 mx-auto mb-1.5 opacity-30 text-[#8a8380]" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="1.5" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"/></svg>
                <p class="text-[10.5px] font-mono uppercase">Carga el PDF oficial para firmar</p>
                <p class="text-[9px] text-[#635d5a] mt-0.5 font-mono">Las casillas se detectan automáticamente</p>`;
        }
        const infoEl = document.getElementById('docSignPdfInfo');
        if (infoEl) infoEl.textContent = 'Ningún PDF';
        const nameEl = document.getElementById('docSignPdfNameContainer');
        if (nameEl) nameEl.textContent = 'Arrastra o sube el PDF para firmar';
    }

    activeSignDocCtx.lastAutoSignerId = null;
    activeSignDocCtx.userManuallyPickedCoords = false;
    window.clearSignaturePad();
    window.saveData(false);
    window.flushCloudWrite(true);
    window.renderDocSignCircuitList();
    window.updateDocSignStatusBadge();

    if (activeSignDocCtx.pdfBytes) {
        await window.renderLastPdfPage();
    }

    if (circuit.length > 0) {
        window.focusSignaturePadFor(circuit[0].name, circuit[0].role);
    }

    if (activeSignDocCtx.prefix === 'quick') {
        window.renderDocChecklists('quick', item.docs);
    } else if (activeSignDocCtx.prefix === 'edit') {
        window.renderDocChecklists('edit', item.docs);
    }
    if (typeof window.renderDailyTasks === 'function') window.renderDailyTasks();
    window.showToast(`🔄 Circuito reiniciado en limpio. Turno de: ${circuit[0]?.name || 'Primer firmante'}`, false);
};

// Permite a Administradores y Supervisores eliminar el PDF actual para cargar una versión nueva y reiniciar el flujo
window.deleteDocumentPdfAndRestart = async function() {
    const isSuper = (currentUserRole === 'Supremo' || currentUserRole === 'Supervisor');
    if (!isSuper) {
        window.showToast("⚠️ Solo un Administrador o Supervisor puede eliminar el archivo y reiniciar el proceso.", true);
        return;
    }

    if (!confirm("⚠️ ¿Deseas eliminar el archivo PDF cargado y reiniciar todo el proceso de firmas?\n\nEsta acción borrará el archivo de la memoria y reiniciará el circuito para que puedas subir una nueva versión del documento.")) {
        return;
    }

    const item = getProjectById(activeSignDocCtx.projectId);
    if (!item || !item.docs || !item.docs[activeSignDocCtx.docId]) return;
    const docData = item.docs[activeSignDocCtx.docId];

    // 1. Eliminar binario y respaldo limpio de IndexedDB
    if (window.SICOM_IDB && activeSignDocCtx.pdfKey) {
        try {
            await window.SICOM_IDB.delete(activeSignDocCtx.pdfKey);
            await window.SICOM_IDB.delete(activeSignDocCtx.pdfKey + '_clean');
        } catch (e) {
            console.warn("Fallo al eliminar PDF de IndexedDB:", e);
        }
    }

    // 2. Limpiar contexto en memoria
    activeSignDocCtx.pdfBytes = null;
    activeSignDocCtx.cleanPdfBytes = null;
    activeSignDocCtx.pdfFileName = '';
    activeSignDocCtx.pdfPageCount = 1;
    activeSignDocCtx.currentPageNum = 1;
    activeSignDocCtx.detectedRows = [];
    activeSignDocCtx.selectedSlotLabel = '';
    activeSignDocCtx.userManuallyPickedCoords = false;
    activeSignDocCtx.lastAutoSignerId = null;

    // 3. Limpiar documento en el proyecto
    docData.checked = false;
    delete docData.pdfFileName;
    delete docData.pdfUploadedAt;
    delete docData.pdfPageCount;
    delete docData.pdfKey;
    delete docData.pdfPurged;
    delete docData.lastStampX;
    delete docData.lastStampY;
    delete docData.signatureSheetPreview;

    if (isFirebaseReady && db && globalDoc && globalDeleteDoc && activeSignDocCtx.pdfKey) {
        try {
            const pdfDocRef = globalDoc(db, 'artifacts', appId, 'public', 'data', 'sicom_pdfs', activeSignDocCtx.pdfKey);
            globalDeleteDoc(pdfDocRef).catch(() => {});
        } catch (_) {}
    }

    const circuit = docData.signatureCircuit || [];
    circuit.forEach(s => {
        s.status = 'pending';
        delete s.signedAt;
        delete s.signedBy;
        delete s.signaturePng;
        delete s.injectedInPdf;
        delete s.coords;
    });

    // 4. Limpiar UI
    const fileInput = document.getElementById('docSignPdfInput');
    if (fileInput) fileInput.value = '';

    document.getElementById('docSignCanvasWrapper')?.classList.add('hidden');
    const placeholder = document.getElementById('docSignNoPdfPlaceholder');
    if (placeholder) {
        placeholder.classList.remove('hidden');
        placeholder.innerHTML = `
            <svg class="w-8 h-8 mx-auto mb-1.5 opacity-30 text-[#8a8380]" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="1.5" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"/></svg>
            <p class="text-[10.5px] font-mono uppercase">Carga el PDF oficial para firmar</p>
            <p class="text-[9px] text-[#635d5a] mt-0.5 font-mono">Las casillas se detectan automáticamente</p>`;
    }

    const infoEl = document.getElementById('docSignPdfInfo');
    if (infoEl) infoEl.textContent = 'Ningún PDF';
    const nameEl = document.getElementById('docSignPdfNameContainer');
    if (nameEl) nameEl.textContent = 'Arrastra o sube el PDF para firmar';

    document.getElementById('docSignStampControls')?.classList.add('hidden');
    document.getElementById('docSignDetectedSlotsBar')?.classList.add('hidden');
    document.getElementById('docSignPaginationControls')?.classList.add('hidden');

    window.clearSignaturePad();
    window.saveData(false);
    window.flushCloudWrite(true);
    window.renderDocSignCircuitList();
    window.updateDocSignStatusBadge();

    if (activeSignDocCtx.prefix === 'quick') {
        window.renderDocChecklists('quick', item.docs);
    } else if (activeSignDocCtx.prefix === 'edit') {
        window.renderDocChecklists('edit', item.docs);
    }
    if (typeof window.renderDailyTasks === 'function') window.renderDailyTasks();

    window.showToast("🗑️ Archivo PDF eliminado. El documento está listo para subir una nueva versión.", false);
};

// Restaura la última página del PDF a su estado original limpio (removiendo estampados previos de pdf-lib)
window.restoreCleanPdfPageInMemory = async function() {
    if (activeSignDocCtx.cleanPdfBytes) {
        activeSignDocCtx.pdfBytes = new Uint8Array(activeSignDocCtx.cleanPdfBytes);
        if (window.SICOM_IDB && activeSignDocCtx.pdfKey) {
            await window.SICOM_IDB.save(activeSignDocCtx.pdfKey, activeSignDocCtx.pdfBytes);
        }
        return activeSignDocCtx.pdfBytes;
    }
    if (!activeSignDocCtx.pdfBytes) return null;

    try {
        await window.ensurePdfLibReady();
        if (typeof PDFLib === 'undefined' || !PDFLib.PDFDocument) return activeSignDocCtx.pdfBytes;

        let rawBytes = activeSignDocCtx.pdfBytes;
        if (rawBytes instanceof ArrayBuffer) rawBytes = new Uint8Array(rawBytes.slice(0));
        else if (rawBytes && rawBytes.buffer instanceof ArrayBuffer) rawBytes = new Uint8Array(rawBytes.buffer.slice(rawBytes.byteOffset, rawBytes.byteOffset + rawBytes.byteLength));
        else if (Array.isArray(rawBytes) || (typeof rawBytes === 'object' && rawBytes !== null)) rawBytes = new Uint8Array(Object.values(rawBytes));

        const pdfDoc = await PDFLib.PDFDocument.load(rawBytes, { ignoreEncryption: true, updateMetadata: false });
        const pages = pdfDoc.getPages();
        const lastPage = pages[pages.length - 1];
        const contents = lastPage.node.Contents();

        if (PDFLib.PDFArray && contents instanceof PDFLib.PDFArray && contents.size() > 1) {
            // El stream 0 es el contenido original de la página; los posteriores son las firmas agregadas con drawImage
            lastPage.node.set(PDFLib.PDFName.of('Contents'), contents.get(0));
        }

        const cleaned = await pdfDoc.save({ useObjectStreams: false });
        activeSignDocCtx.cleanPdfBytes = new Uint8Array(cleaned);
        activeSignDocCtx.pdfBytes = new Uint8Array(cleaned);
        if (window.SICOM_IDB && activeSignDocCtx.pdfKey) {
            await window.SICOM_IDB.save(activeSignDocCtx.pdfKey + '_clean', activeSignDocCtx.cleanPdfBytes);
            await window.SICOM_IDB.save(activeSignDocCtx.pdfKey, activeSignDocCtx.pdfBytes);
        }
        return activeSignDocCtx.pdfBytes;
    } catch (e) {
        console.warn("No se pudo limpiar stream previo:", e);
        return activeSignDocCtx.pdfBytes;
    }
};

function uint8ToBase64(bytes) {
    let binary = '';
    const len = bytes.byteLength;
    const chunkSize = 8192;
    for (let i = 0; i < len; i += chunkSize) {
        binary += String.fromCharCode.apply(null, bytes.subarray(i, Math.min(i + chunkSize, len)));
    }
    return btoa(binary);
}

function base64ToUint8(base64) {
    const binary = atob(base64);
    const len = binary.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
        bytes[i] = binary.charCodeAt(i);
    }
    return bytes;
}

window.renderSignatureSheetFromPreview = async function(previewDataUrl, docData) {
    const canvas = document.getElementById('docSignPdfCanvas');
    const wrapper = document.getElementById('docSignCanvasWrapper');
    const placeholder = document.getElementById('docSignNoPdfPlaceholder');
    const controls = document.getElementById('docSignStampControls');
    const info = document.getElementById('docSignPdfInfo');
    const nameCont = document.getElementById('docSignPdfNameContainer');

    if (!canvas || !previewDataUrl) return;

    return new Promise((resolve) => {
        const img = new Image();
        img.onload = () => {
            const parentWidth = wrapper?.parentElement?.clientWidth || 500;
            const targetWidth = Math.max(340, Math.min(580, parentWidth - 20));
            const aspect = (img.height && img.width) ? (img.height / img.width) : (792 / 612);
            const w = Math.round(targetWidth);
            const h = Math.round(targetWidth * aspect);

            canvas.width = w;
            canvas.height = h;
            canvas.style.width = `${w}px`;
            canvas.style.height = `${h}px`;
            canvas.style.backgroundColor = '#ffffff';

            const ctx = canvas.getContext('2d');
            ctx.fillStyle = '#ffffff';
            ctx.fillRect(0, 0, w, h);
            ctx.drawImage(img, 0, 0, w, h);

            activeSignDocCtx.pagePdfWidth = docData.pagePdfWidth || 612;
            activeSignDocCtx.pagePdfHeight = docData.pagePdfHeight || 792;
            activeSignDocCtx.detectedRows = docData.detectedRows || [];
            activeSignDocCtx.stampWidth = 82;
            activeSignDocCtx.stampHeight = 26;

            if (placeholder) placeholder.classList.add('hidden');
            if (wrapper) wrapper.classList.remove('hidden');
            if (controls) controls.classList.remove('hidden');
            if (info) info.textContent = `✓ Hoja oficial sincronizada`;
            if (nameCont) nameCont.textContent = docData.pdfFileName || 'Documento Oficial.pdf';

            // Auto-posicionar casilla frente al firmante activo
            const item = getProjectById(activeSignDocCtx.projectId);
            const circuit = item?.docs?.[activeSignDocCtx.docId]?.signatureCircuit || [];
            const activeSignerIdx = circuit.findIndex(s => s.status !== 'signed');
            const activeSigner = activeSignerIdx !== -1 ? circuit[activeSignerIdx] : null;

            if (activeSigner && (!activeSignDocCtx.lastAutoSignerId || activeSignDocCtx.lastAutoSignerId !== activeSigner.id || !activeSignDocCtx.userManuallyPickedCoords)) {
                activeSignDocCtx.lastAutoSignerId = activeSigner.id;
                const resolved = window.resolveExactStampCoordsForSigner(activeSigner, activeSignerIdx, circuit, activeSignDocCtx.detectedRows);
                activeSignDocCtx.stampX = resolved.x;
                activeSignDocCtx.stampY = resolved.y;
                activeSignDocCtx.selectedSlotLabel = resolved.label || activeSigner.name;
            }

            window.renderDetectedSlotsBar();
            window.updateStampTargetVisual();

            // Desplazar automáticamente el visor para centrar la tabla de firmas en la pantalla
            const viewportElem = document.getElementById('docSignPdfViewport');
            if (viewportElem && canvas) {
                const sY = activeSignDocCtx.stampY || 333;
                const targetCanvasY = ((activeSignDocCtx.pagePdfHeight - sY) / activeSignDocCtx.pagePdfHeight) * canvas.height;
                viewportElem.scrollTo({ top: Math.max(0, targetCanvasY - 110), behavior: 'smooth' });
            }

            canvas.onclick = function(e) {
                const rect = canvas.getBoundingClientRect();
                if (!rect.width || !rect.height) return;
                const clickX = e.clientX - rect.left;
                const clickY = e.clientY - rect.top;

                const pdfX = (clickX / rect.width) * activeSignDocCtx.pagePdfWidth;
                const pdfY = activeSignDocCtx.pagePdfHeight - ((clickY / rect.height) * activeSignDocCtx.pagePdfHeight);

                if (!isNaN(pdfX) && !isNaN(pdfY)) {
                    const sW = activeSignDocCtx.stampWidth || 82;
                    const sH = activeSignDocCtx.stampHeight || 26;
                    activeSignDocCtx.stampX = Math.round(Math.max(10, Math.min(activeSignDocCtx.pagePdfWidth - sW - 10, pdfX - (sW / 2))));
                    activeSignDocCtx.stampY = Math.round(Math.max(10, Math.min(activeSignDocCtx.pagePdfHeight - sH - 10, pdfY - (sH / 2))));
                    activeSignDocCtx.userManuallyPickedCoords = true;
                    activeSignDocCtx.selectedSlotLabel = `Manual (X:${activeSignDocCtx.stampX}, Y:${activeSignDocCtx.stampY})`;

                    window.updateStampTargetVisual();
                    window.renderDetectedSlotsBar();
                }
            };

            resolve();
        };
        img.onerror = (e) => {
            console.warn("Fallo al cargar preview de hoja de firmas:", e);
            resolve();
        };
        img.src = previewDataUrl;
    });
};

window.handleDocPdfFileSelected = async function(event) {
    const file = event.target?.files?.[0];
    if (!file) return;

    if (!file.type.includes('pdf') && !file.name.toLowerCase().endsWith('.pdf')) {
        window.showToast("⚠️ Solo se admiten archivos formato PDF.", true);
        return;
    }

    const reader = new FileReader();
    reader.onload = async function(e) {
        try {
            const arrayBuffer = e.target.result;
            const uint8 = new Uint8Array(arrayBuffer);

            await window.ensurePdfLibReady();
            if (typeof PDFLib === 'undefined') {
                window.showToast("⚠️ Biblioteca PDFLib no cargada.", true);
                return;
            }
            const pdfDoc = await PDFLib.PDFDocument.load(uint8, { ignoreEncryption: true, updateMetadata: false });
            const pageCount = pdfDoc.getPageCount();

            activeSignDocCtx.pdfBytes = new Uint8Array(uint8);
            activeSignDocCtx.cleanPdfBytes = new Uint8Array(uint8);
            activeSignDocCtx.pdfFileName = file.name;
            activeSignDocCtx.pdfPageCount = pageCount;
            activeSignDocCtx.currentPageNum = pageCount;
            activeSignDocCtx.lastAutoSignerId = null;
            activeSignDocCtx.userManuallyPickedCoords = false;

            // Guardar binario y respaldo limpio en IndexedDB nativo
            if (window.SICOM_IDB) {
                await window.SICOM_IDB.save(activeSignDocCtx.pdfKey, activeSignDocCtx.pdfBytes);
                await window.SICOM_IDB.save(activeSignDocCtx.pdfKey + '_clean', activeSignDocCtx.cleanPdfBytes);
            }

            // Analizar la tabla de firmas en la última hoja del PDF recién subido
            await window.analyzePdfSignatureTable();

            // Guardar metadatos ligeros en el proyecto
            const item = getProjectById(activeSignDocCtx.projectId);
            if (item && item.docs && item.docs[activeSignDocCtx.docId]) {
                const d = item.docs[activeSignDocCtx.docId];
                d.pdfFileName = file.name;
                d.pdfUploadedAt = new Date().toLocaleDateString('es-MX');
                d.pdfPageCount = pageCount;
                d.pdfKey = activeSignDocCtx.pdfKey;
                delete d.lastStampX;
                delete d.lastStampY;

                // Si habían firmas previas en el circuito, re-sincronizarlas sobre el PDF nuevo en sus casillas exactas
                const circuit = d.signatureCircuit || [];
                circuit.forEach(s => { s.injectedInPdf = false; });
                window.saveData(false);
            }

            // Sincronizar binario a la nube Firestore si es menor a 850 KB para disponibilidad inmediata en móviles
            if (isFirebaseReady && db && globalDoc && globalSetDoc && uint8.byteLength < 850000) {
                try {
                    const pdfDocRef = globalDoc(db, 'artifacts', appId, 'public', 'data', 'sicom_pdfs', activeSignDocCtx.pdfKey);
                    const b64 = uint8ToBase64(uint8);
                    globalSetDoc(pdfDocRef, {
                        pdfKey: activeSignDocCtx.pdfKey,
                        fileName: file.name,
                        base64: b64,
                        pageCount: pageCount,
                        uploadedAt: Date.now()
                    }, { merge: false }).catch(err => console.warn("Firestore PDF sync warning:", err));
                } catch (e) {
                    console.warn("Error al preparar sync de PDF:", e);
                }
            }

            if (typeof window.syncCircuitSignaturesToPdf === 'function') {
                await window.syncCircuitSignaturesToPdf();
            }
            await window.renderLastPdfPage();
            window.showToast(`📄 PDF cargado (${pageCount} págs) y casillas de firma detectadas.`, false);
        } catch (err) {
            console.error("Error al procesar PDF:", err);
            window.showToast("⚠️ Error al leer el archivo PDF.", true);
        }
    };
    reader.readAsArrayBuffer(file);
};

window.changeDocSignPage = function(delta) {
    if (!activeSignDocCtx.pdfPageCount || activeSignDocCtx.pdfPageCount <= 1) return;
    const current = Number(activeSignDocCtx.currentPageNum) || activeSignDocCtx.pdfPageCount;
    const next = Math.max(1, Math.min(activeSignDocCtx.pdfPageCount, current + delta));
    if (next !== current) {
        activeSignDocCtx.currentPageNum = next;
        window.renderLastPdfPage();
    }
};

// Detección automática e inteligente de casillas de firmas en planos y actas oficiales
async function detectSignerCoordsOnPage(page, signerName, signerRole) {
    const rows = await extractSignatureTableRows(page);
    activeSignDocCtx.detectedRows = rows;
    const item = getProjectById(activeSignDocCtx.projectId);
    const circuit = item?.docs?.[activeSignDocCtx.docId]?.signatureCircuit || [];
    const idx = circuit.findIndex(s => s.status !== 'signed');
    return window.resolveExactStampCoordsForSigner(
        { name: signerName, role: signerRole },
        idx !== -1 ? idx : 0,
        circuit,
        rows
    );
}

let activePdfRenderTask = null;

window.renderLastPdfPage = async function() {
    if (!activeSignDocCtx.pdfBytes) return;
    const canvas = document.getElementById('docSignPdfCanvas');
    const wrapper = document.getElementById('docSignCanvasWrapper');
    const placeholder = document.getElementById('docSignNoPdfPlaceholder');
    const controls = document.getElementById('docSignStampControls');
    const info = document.getElementById('docSignPdfInfo');
    const nameCont = document.getElementById('docSignPdfNameContainer');
    const pagControls = document.getElementById('docSignPaginationControls');
    const curPageSpan = document.getElementById('docSignCurrentPageNum');
    const totalPagesSpan = document.getElementById('docSignTotalPagesNum');

    try {
        await window.ensurePdfJsReady();
        if (typeof pdfjsLib === 'undefined') {
            console.error("pdfjsLib no está disponible");
            return;
        }

        if (activePdfRenderTask && typeof activePdfRenderTask.cancel === 'function') {
            try { activePdfRenderTask.cancel(); } catch (e) {}
            activePdfRenderTask = null;
        }

        let bytesCopy = null;
        if (activeSignDocCtx.pdfBytes instanceof Uint8Array) {
            bytesCopy = new Uint8Array(activeSignDocCtx.pdfBytes.buffer.slice(activeSignDocCtx.pdfBytes.byteOffset, activeSignDocCtx.pdfBytes.byteOffset + activeSignDocCtx.pdfBytes.byteLength));
        } else if (activeSignDocCtx.pdfBytes instanceof ArrayBuffer) {
            bytesCopy = new Uint8Array(activeSignDocCtx.pdfBytes.slice(0));
        } else {
            bytesCopy = new Uint8Array(activeSignDocCtx.pdfBytes);
        }

        const loadingTask = pdfjsLib.getDocument({ data: bytesCopy });
        const pdf = await loadingTask.promise;
        activeSignDocCtx.pdfPageCount = pdf.numPages;

        // Por defecto, mostrar siempre la última hoja donde residen las firmas oficiales
        if (!activeSignDocCtx.currentPageNum || activeSignDocCtx.currentPageNum > pdf.numPages) {
            activeSignDocCtx.currentPageNum = pdf.numPages;
        }
        const activePageNum = activeSignDocCtx.currentPageNum;
        const page = await pdf.getPage(activePageNum);

        // Si estamos en la última página, extraer las filas de la tabla de firmas
        if (activePageNum === pdf.numPages) {
            activeSignDocCtx.detectedRows = await extractSignatureTableRows(page);
        }

        // Obtener firmante activo para auto-posicionamiento ANTES de renderizar
        const item = getProjectById(activeSignDocCtx.projectId);
        const circuit = item?.docs?.[activeSignDocCtx.docId]?.signatureCircuit || [];
        const activeSignerIdx = circuit.findIndex(s => s.status !== 'signed');
        const activeSigner = activeSignerIdx !== -1 ? circuit[activeSignerIdx] : null;

        if (activeSigner && (!activeSignDocCtx.lastAutoSignerId || activeSignDocCtx.lastAutoSignerId !== activeSigner.id || !activeSignDocCtx.userManuallyPickedCoords)) {
            activeSignDocCtx.lastAutoSignerId = activeSigner.id;
            const resolved = window.resolveExactStampCoordsForSigner(activeSigner, activeSignerIdx, circuit, activeSignDocCtx.detectedRows);
            activeSignDocCtx.stampX = resolved.x;
            activeSignDocCtx.stampY = resolved.y;
            activeSignDocCtx.selectedSlotLabel = resolved.label || activeSigner.name;
        }

        activeSignDocCtx.stampWidth = 82;
        activeSignDocCtx.stampHeight = 26;

        if (placeholder) placeholder.classList.add('hidden');
        if (wrapper) wrapper.classList.remove('hidden');
        if (controls) controls.classList.remove('hidden');

        if (info) info.textContent = `${activeSignDocCtx.pdfPageCount} pág${activeSignDocCtx.pdfPageCount > 1 ? 's' : ''}`;
        if (nameCont) nameCont.textContent = activeSignDocCtx.pdfFileName || 'Documento Oficial.pdf';

        if (pagControls) {
            if (pdf.numPages > 1) {
                pagControls.classList.remove('hidden');
                pagControls.classList.add('flex');
                if (curPageSpan) curPageSpan.textContent = activePageNum;
                if (totalPagesSpan) totalPagesSpan.textContent = pdf.numPages;
            } else {
                pagControls.classList.add('hidden');
            }
        }

        const unscaledViewport = page.getViewport({ scale: 1.0 });
        activeSignDocCtx.pagePdfWidth = unscaledViewport.width || 612;
        activeSignDocCtx.pagePdfHeight = unscaledViewport.height || 792;

        const parentWidth = wrapper?.parentElement?.clientWidth || 500;
        const targetWidth = Math.max(340, Math.min(580, parentWidth - 20));
        const baseScale = targetWidth / activeSignDocCtx.pagePdfWidth;
        const zoom = activeSignDocCtx.zoomLevel || 1.15;
        const scale = Math.max(0.60, baseScale * zoom);
        const viewport = page.getViewport({ scale: scale });

        const zoomLabel = document.getElementById('docSignZoomLabel');
        if (zoomLabel) zoomLabel.textContent = `${Math.round(zoom * 100)}%`;

        canvas.width = Math.round(viewport.width);
        canvas.height = Math.round(viewport.height);
        canvas.style.width = `${Math.round(viewport.width)}px`;
        canvas.style.height = `${Math.round(viewport.height)}px`;
        canvas.style.backgroundColor = '#ffffff';

        // PINTAR FONDO BLANCO PAPEL OBLIGATORIO
        const ctx = canvas.getContext('2d');
        ctx.save();
        ctx.fillStyle = '#ffffff';
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.restore();

        const renderCtx = {
            canvasContext: ctx,
            viewport: viewport
        };
        activePdfRenderTask = page.render(renderCtx);
        await activePdfRenderTask.promise;
        activePdfRenderTask = null;

        window.renderDetectedSlotsBar();
        window.updateStampTargetVisual();

        // Capturar vista previa visual de la hoja de firmas oficial (para sincronización multidispositivo y móvil)
        try {
            const previewDataUrl = canvas.toDataURL('image/jpeg', 0.65);
            if (previewDataUrl && previewDataUrl.length > 100) {
                const item = getProjectById(activeSignDocCtx.projectId);
                if (item && item.docs && item.docs[activeSignDocCtx.docId]) {
                    const d = item.docs[activeSignDocCtx.docId];
                    d.signatureSheetPreview = previewDataUrl;
                    d.pagePdfWidth = activeSignDocCtx.pagePdfWidth || 612;
                    d.pagePdfHeight = activeSignDocCtx.pagePdfHeight || 792;
                    d.detectedRows = activeSignDocCtx.detectedRows || [];
                }
            }
        } catch (e) {
            console.warn("Captura de preview visual:", e);
        }

        // Desplazar automáticamente el visor para centrar la tabla de firmas en la pantalla
        const viewportElem = document.getElementById('docSignPdfViewport');
        if (viewportElem && canvas) {
            const sY = activeSignDocCtx.stampY || 333;
            const targetCanvasY = ((activeSignDocCtx.pagePdfHeight - sY) / activeSignDocCtx.pagePdfHeight) * canvas.height;
            viewportElem.scrollTo({ top: Math.max(0, targetCanvasY - 110), behavior: 'smooth' });
        }

        canvas.onclick = function(e) {
            const rect = canvas.getBoundingClientRect();
            if (!rect.width || !rect.height) return;
            const clickX = e.clientX - rect.left;
            const clickY = e.clientY - rect.top;

            const pdfX = (clickX / rect.width) * activeSignDocCtx.pagePdfWidth;
            const pdfY = activeSignDocCtx.pagePdfHeight - ((clickY / rect.height) * activeSignDocCtx.pagePdfHeight);

            if (!isNaN(pdfX) && !isNaN(pdfY)) {
                const sW = activeSignDocCtx.stampWidth || 82;
                const sH = activeSignDocCtx.stampHeight || 26;
                activeSignDocCtx.stampX = Math.round(Math.max(10, Math.min(activeSignDocCtx.pagePdfWidth - sW - 10, pdfX - (sW / 2))));
                activeSignDocCtx.stampY = Math.round(Math.max(10, Math.min(activeSignDocCtx.pagePdfHeight - sH - 10, pdfY - (sH / 2))));
                activeSignDocCtx.userManuallyPickedCoords = true;
                activeSignDocCtx.selectedSlotLabel = `Manual (X:${activeSignDocCtx.stampX}, Y:${activeSignDocCtx.stampY})`;

                window.updateStampTargetVisual();
                window.renderDetectedSlotsBar();
            }
        };

    } catch (err) {
        if (err && err.name === 'RenderingCancelledException') return;
        console.error("Error al renderizar PDF con pdf.js:", err);
    }
};

window.updateStampTargetVisual = function() {
    const target = document.getElementById('docSignStampTarget');
    const targetLabel = document.getElementById('docSignStampTargetLabel');
    const canvas = document.getElementById('docSignPdfCanvas');
    const label = document.getElementById('docSignPosLabel');
    if (!target || !canvas) return;

    let sX = Number(activeSignDocCtx.stampX);
    let sY = Number(activeSignDocCtx.stampY);
    if (isNaN(sX)) sX = 480;
    if (isNaN(sY)) sY = 333;
    const pW = activeSignDocCtx.pagePdfWidth || 612;
    const pH = activeSignDocCtx.pagePdfHeight || 792;
    const sW = activeSignDocCtx.stampWidth || 82;
    const sH = activeSignDocCtx.stampHeight || 26;

    const item = getProjectById(activeSignDocCtx.projectId);
    const circuit = item?.docs?.[activeSignDocCtx.docId]?.signatureCircuit || [];
    const activeSigner = circuit.find(s => s.status !== 'signed');

    if (!activeSigner) {
        target.style.display = 'none';
        return;
    }

    if (label) {
        const slotDesc = activeSignDocCtx.selectedSlotLabel
            ? `Enfrente de: ${activeSignDocCtx.selectedSlotLabel} (X:${sX}, Y:${sY})`
            : `X: ${sX}, Y: ${sY}`;
        label.textContent = slotDesc;
    }

    if (targetLabel) {
        targetLabel.textContent = `📍 Firma: ${activeSigner ? activeSigner.name.split(' ')[0] : 'Aquí'}`;
    }

    const rect = canvas.getBoundingClientRect();
    if (!rect.width || !rect.height) {
        target.style.display = 'none';
        return;
    }

    const cssX = (sX / pW) * rect.width;
    const cssY = ((pH - (sY + sH)) / pH) * rect.height;
    const cssWidth = (sW / pW) * rect.width;
    const cssHeight = (sH / pH) * rect.height;

    target.style.display = 'flex';
    target.style.left = `${Math.round(cssX)}px`;
    target.style.top = `${Math.round(cssY)}px`;
    target.style.width = `${Math.max(60, Math.round(cssWidth))}px`;
    target.style.height = `${Math.max(22, Math.round(cssHeight))}px`;
};

window.adjustStampPos = function(dx, dy) {
    let curX = Number(activeSignDocCtx.stampX);
    let curY = Number(activeSignDocCtx.stampY);
    if (isNaN(curX)) curX = 480;
    if (isNaN(curY)) curY = 333;

    const maxW = activeSignDocCtx.pagePdfWidth || 612;
    const maxH = activeSignDocCtx.pagePdfHeight || 792;
    const sW = activeSignDocCtx.stampWidth || 82;
    const sH = activeSignDocCtx.stampHeight || 26;

    activeSignDocCtx.stampX = Math.max(10, Math.min(maxW - sW - 10, curX + dx));
    activeSignDocCtx.stampY = Math.max(10, Math.min(maxH - sH - 10, curY + dy));
    activeSignDocCtx.userManuallyPickedCoords = true;
    activeSignDocCtx.selectedSlotLabel = `Manual (X:${activeSignDocCtx.stampX}, Y:${activeSignDocCtx.stampY})`;

    window.updateStampTargetVisual();
    window.renderDetectedSlotsBar();
};

window.resizeSignaturePad = function() {
    const canvas = document.getElementById('signaturePadCanvas');
    if (!canvas) return;
    const container = canvas.parentElement;
    const computedWidth = container ? container.clientWidth : 0;
    const finalWidth = (computedWidth > 50) ? computedWidth : Math.min(window.innerWidth - 40, 500);

    // En pantallas táctiles móviles (< 1024px), dar una altura holgada (160px) para máxima comodidad táctil al firmar con el dedo
    // En escritorio (>= 1024px), altura espaciosa (150px) para firmar cómodamente con ratón o stylus
    const isMobileView = (window.innerWidth < 1024);
    const padHeight = isMobileView ? 160 : 150;
    if (canvas.width !== finalWidth || canvas.height !== padHeight) {
        canvas.width = finalWidth;
        canvas.height = padHeight;
        canvas.style.height = `${padHeight}px`;
        if (sigPadCtx) {
            sigPadCtx.strokeStyle = '#0055cc';
            sigPadCtx.lineWidth = 2.5;
            sigPadCtx.lineCap = 'round';
            sigPadCtx.lineJoin = 'round';
        }
        if (window.activeSignatureMode && window.activeSignatureMode !== 'draw') {
            window.renderTypedSignatureOnCanvas();
        }
    }
};

window.activeSignatureMode = 'draw';

window.switchSignatureMode = function(mode) {
    window.activeSignatureMode = mode || 'draw';
    const btnDraw = document.getElementById('docSignModeBtn_draw');
    const btnType = document.getElementById('docSignModeBtn_type');
    const btnInitials = document.getElementById('docSignModeBtn_initials');
    const controls = document.getElementById('docSignTypeControls');
    const input = document.getElementById('docSignTypedNameInput');
    const helpText = document.getElementById('docSignPadHelpText');

    [btnDraw, btnType, btnInitials].forEach(b => {
        if (!b) return;
        b.className = 'px-1.5 py-0.5 rounded font-bold transition text-[#8a8380] hover:text-white cursor-pointer';
    });

    if (mode === 'draw') {
        if (btnDraw) btnDraw.className = 'px-1.5 py-0.5 rounded font-bold transition bg-[#0055cc] text-white cursor-pointer';
        if (controls) {
            controls.classList.add('hidden');
            controls.classList.remove('flex');
        }
        if (helpText) helpText.textContent = '✍️ Dibuja con el dedo o ratón en tinta azul';
        window.clearSignaturePad();
    } else {
        if (controls) {
            controls.classList.remove('hidden');
            controls.classList.add('flex');
        }

        let currentSignerName = '';
        if (typeof getProjectById === 'function' && activeSignDocCtx && activeSignDocCtx.projectId) {
            const item = getProjectById(activeSignDocCtx.projectId);
            const circuit = item?.docs?.[activeSignDocCtx.docId]?.signatureCircuit || [];
            const nextSigner = circuit.find(s => s.status !== 'signed');
            if (nextSigner && nextSigner.name) {
                currentSignerName = nextSigner.name;
            }
        }
        if (!currentSignerName) {
            const activeSignerEl = document.getElementById('docSignPadActiveSigner');
            if (activeSignerEl && activeSignerEl.textContent) {
                const match = activeSignerEl.textContent.match(/Turno:\s*([^(]+)/);
                if (match) currentSignerName = match[1].trim();
            }
        }
        if (!currentSignerName && typeof currentUserEmail !== 'undefined' && currentUserEmail) {
            currentSignerName = currentUserEmail.split('@')[0];
        }

        if (mode === 'type') {
            if (btnType) btnType.className = 'px-1.5 py-0.5 rounded font-bold transition bg-[#0055cc] text-white cursor-pointer';
            if (helpText) helpText.textContent = '🖋️ Escribe tu nombre o apodo caligráfico';
            if (input) {
                input.value = currentSignerName || 'Firmante Autorizado';
            }
        } else if (mode === 'initials') {
            if (btnInitials) btnInitials.className = 'px-1.5 py-0.5 rounded font-bold transition bg-[#0055cc] text-white cursor-pointer';
            if (helpText) helpText.textContent = '⚡ Genera una rúbrica rápida con iniciales';
            if (input) {
                const parts = (currentSignerName || 'Firma Autorizada').trim().split(/\s+/).filter(Boolean);
                let initialsText = '';
                if (parts.length === 1) {
                    initialsText = parts[0];
                } else if (parts.length === 2) {
                    initialsText = `${parts[0][0]}. ${parts[1]}`;
                } else {
                    const initialsPrefix = parts.slice(0, -1).map(p => p[0].toUpperCase() + '.').join(' ');
                    initialsText = `${initialsPrefix} ${parts[parts.length - 1]}`;
                }
                input.value = initialsText;
            }
        }
        window.renderTypedSignatureOnCanvas();
    }
};

window.renderTypedSignatureOnCanvas = function() {
    const canvas = document.getElementById('signaturePadCanvas');
    if (!canvas) return;
    if (!sigPadCtx) sigPadCtx = canvas.getContext('2d');
    const ctx = sigPadCtx;

    const input = document.getElementById('docSignTypedNameInput');
    const fontSelect = document.getElementById('docSignTypedFontSelect');
    const text = (input ? input.value : '') || 'Firma';
    const fontFam = (fontSelect ? fontSelect.value : "'Dancing Script', cursive");

    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    let fontSize = Math.min(Math.round(canvas.height * 0.44), 48);
    ctx.font = `600 ${fontSize}px ${fontFam}`;
    
    const maxAllowedWidth = canvas.width * 0.82;
    while (ctx.measureText(text).width > maxAllowedWidth && fontSize > 16) {
        fontSize -= 2;
        ctx.font = `600 ${fontSize}px ${fontFam}`;
    }

    ctx.fillStyle = '#0055cc';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';

    const centerX = canvas.width / 2;
    const centerY = canvas.height * 0.42;

    ctx.fillText(text, centerX, centerY);

    const textMetrics = ctx.measureText(text);
    const rubWidth = Math.min(canvas.width * 0.78, Math.max(textMetrics.width * 0.95, 60));
    const startX = centerX - rubWidth / 2;
    const endX = centerX + rubWidth / 2;
    const rubY = centerY + fontSize * 0.44;

    ctx.save();
    ctx.beginPath();
    ctx.strokeStyle = '#0055cc';
    ctx.lineWidth = 2.2;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.moveTo(startX, rubY);
    ctx.bezierCurveTo(
        startX + rubWidth * 0.35, rubY + 10,
        startX + rubWidth * 0.65, rubY - 6,
        endX, rubY + 5
    );
    ctx.bezierCurveTo(
        endX - 15, rubY + 14,
        endX - 35, rubY + 7,
        endX - 8, rubY + 3
    );
    ctx.stroke();
    ctx.restore();

    hasSignatureDrawn = true;
};

window.initSignaturePad = function() {
    const canvas = document.getElementById('signaturePadCanvas');
    if (!canvas) return;

    window.resizeSignaturePad();

    sigPadCtx = canvas.getContext('2d');
    sigPadCtx.strokeStyle = '#0055cc'; // Tinta azul corporativa
    sigPadCtx.lineWidth = 2.5;
    sigPadCtx.lineCap = 'round';
    sigPadCtx.lineJoin = 'round';

    window.clearSignaturePad();

    const getPos = (e) => {
        const r = canvas.getBoundingClientRect();
        if (e.touches && e.touches.length > 0) {
            return {
                x: (e.touches[0].clientX - r.left) * (canvas.width / r.width),
                y: (e.touches[0].clientY - r.top) * (canvas.height / r.height)
            };
        }
        return {
            x: (e.clientX - r.left) * (canvas.width / r.width),
            y: (e.clientY - r.top) * (canvas.height / r.height)
        };
    };

    const startDraw = (e) => {
        e.preventDefault();
        isDrawingSignature = true;
        const pos = getPos(e);
        lastSigX = pos.x;
        lastSigY = pos.y;
        sigPadCtx.beginPath();
        sigPadCtx.moveTo(lastSigX, lastSigY);
    };

    const draw = (e) => {
        if (!isDrawingSignature) return;
        e.preventDefault();
        const pos = getPos(e);
        sigPadCtx.lineTo(pos.x, pos.y);
        sigPadCtx.stroke();
        lastSigX = pos.x;
        lastSigY = pos.y;
        hasSignatureDrawn = true;
    };

    const stopDraw = (e) => {
        if (!isDrawingSignature) return;
        e.preventDefault();
        isDrawingSignature = false;
        sigPadCtx.closePath();
    };

    canvas.onmousedown = startDraw;
    canvas.onmousemove = draw;
    canvas.onmouseup = stopDraw;
    canvas.onmouseleave = stopDraw;

    canvas.ontouchstart = startDraw;
    canvas.ontouchmove = draw;
    canvas.ontouchend = stopDraw;
    canvas.ontouchcancel = stopDraw;
};

window.clearSignaturePad = function() {
    const canvas = document.getElementById('signaturePadCanvas');
    if (!canvas || !sigPadCtx) return;
    sigPadCtx.clearRect(0, 0, canvas.width, canvas.height);
    hasSignatureDrawn = false;
    if (window.activeSignatureMode !== 'draw') {
        const input = document.getElementById('docSignTypedNameInput');
        if (input) input.value = '';
    }
};

// Sincronizador y auto-reparador de firmas registradas en el circuito hacia el binario del PDF
window.syncCircuitSignaturesToPdf = async function() {
    if (!activeSignDocCtx.pdfBytes) return;
    const item = getProjectById(activeSignDocCtx.projectId);
    if (!item || !item.docs || !item.docs[activeSignDocCtx.docId]) return;
    const docData = item.docs[activeSignDocCtx.docId];
    const circuit = docData.signatureCircuit || [];

    const signedMembers = circuit.filter(s => s.status === 'signed' && s.signaturePng);
    if (signedMembers.length === 0) return;

    // Detectar si alguna firma anterior quedó mal posicionada (ej. Y > 585 debajo de Fecha, o dos firmas encimadas en la misma Y)
    let needsCleanRebuild = false;
    const seenYs = [];
    for (const s of signedMembers) {
        const y = Number(s.coords?.y);
        if (isNaN(y) || y > 585 || y < 150) {
            needsCleanRebuild = true;
            delete s.coords;
            s.injectedInPdf = false;
        } else if (seenYs.some(prevY => Math.abs(prevY - y) < 12)) {
            needsCleanRebuild = true;
            delete s.coords;
            s.injectedInPdf = false;
        } else {
            seenYs.push(y);
        }
    }

    if (needsCleanRebuild) {
        await window.restoreCleanPdfPageInMemory();
        signedMembers.forEach(s => { s.injectedInPdf = false; });
    }

    const pendingStamps = circuit.filter(s => s.status === 'signed' && s.signaturePng && !s.injectedInPdf);
    if (pendingStamps.length === 0) return;

    try {
        await window.ensurePdfLibReady();
        if (typeof PDFLib === 'undefined' || !PDFLib.PDFDocument) return;

        if (!activeSignDocCtx.detectedRows || activeSignDocCtx.detectedRows.length === 0) {
            await window.analyzePdfSignatureTable();
        }

        let rawBytes = activeSignDocCtx.pdfBytes;
        if (rawBytes instanceof ArrayBuffer) rawBytes = new Uint8Array(rawBytes.slice(0));
        else if (rawBytes && rawBytes.buffer instanceof ArrayBuffer) rawBytes = new Uint8Array(rawBytes.buffer.slice(rawBytes.byteOffset, rawBytes.byteOffset + rawBytes.byteLength));
        else if (Array.isArray(rawBytes) || (typeof rawBytes === 'object' && rawBytes !== null)) rawBytes = new Uint8Array(Object.values(rawBytes));

        const pdfDoc = await PDFLib.PDFDocument.load(rawBytes, { ignoreEncryption: true, updateMetadata: false });
        const pages = pdfDoc.getPages();
        const lastPage = pages[pages.length - 1];

        for (let idx = 0; idx < circuit.length; idx++) {
            const signer = circuit[idx];
            if (signer.status !== 'signed' || !signer.signaturePng || signer.injectedInPdf) continue;

            try {
                const base64Data = signer.signaturePng.split(',')[1];
                const binaryString = atob(base64Data);
                const pngBytes = new Uint8Array(binaryString.length);
                for (let i = 0; i < binaryString.length; i++) pngBytes[i] = binaryString.charCodeAt(i);

                const sigImg = await pdfDoc.embedPng(pngBytes);
                let sX = Number(signer.coords?.x);
                let sY = Number(signer.coords?.y);

                if (isNaN(sX) || isNaN(sY) || sY > 585 || sY < 150) {
                    const resolved = window.resolveExactStampCoordsForSigner(signer, idx, circuit, activeSignDocCtx.detectedRows);
                    sX = resolved.x;
                    sY = resolved.y;
                    signer.coords = { x: sX, y: sY, page: pages.length };
                }

                lastPage.drawImage(sigImg, { x: sX, y: sY, width: 82, height: 26 });
                signer.injectedInPdf = true;
            } catch (errSig) {
                console.warn("Fallo inyectando firma en PDF:", errSig);
            }
        }

        const newBytes = await pdfDoc.save({ useObjectStreams: false });
        activeSignDocCtx.pdfBytes = newBytes;
        if (window.SICOM_IDB && activeSignDocCtx.pdfKey) {
            await window.SICOM_IDB.save(activeSignDocCtx.pdfKey, newBytes);
        }
        window.saveData(false);
    } catch (e) {
        console.warn("Error en syncCircuitSignaturesToPdf:", e);
    }
};

window.stampSignatureOnActiveDocument = async function() {
    if (!hasSignatureDrawn) {
        window.showToast("⚠️ Ingresa o dibuja tu firma antes de estampar.", true);
        return;
    }

    const item = getProjectById(activeSignDocCtx.projectId);
    if (!item || !item.docs || !item.docs[activeSignDocCtx.docId]) return;
    const docData = item.docs[activeSignDocCtx.docId];
    const circuit = docData.signatureCircuit || [];

    const activeSignerIndex = circuit.findIndex(s => s.status !== 'signed');
    if (activeSignerIndex === -1) {
        window.showToast("El circuito de firmas ya está 100% completado.", false);
        return;
    }
    const signer = circuit[activeSignerIndex];

    const canSign = (currentUserRole === 'Supremo' || currentUserRole === 'Supervisor' || window.isSameUserOrAlias(signer.name, localAuthor));
    if (!canSign) {
        window.showToast(`⚠️ Turno exclusivo de firma para: ${signer.name} (${signer.role}).`, true);
        return;
    }

    const padCanvas = document.getElementById('signaturePadCanvas');
    const signaturePngDataUrl = padCanvas.toDataURL('image/png');

    const now = new Date();
    const stampDateStr = `${now.toLocaleDateString('es-MX')} ${now.toLocaleTimeString('es-MX', { hour: '2-digit', minute: '2-digit' })}`;

    // Asegurar que las filas de la tabla han sido analizadas si hay PDF
    if (activeSignDocCtx.pdfBytes && (!activeSignDocCtx.detectedRows || activeSignDocCtx.detectedRows.length === 0)) {
        await window.analyzePdfSignatureTable();
    }

    // Determinar las coordenadas exactas enfrente del nombre de la persona
    let stampedX = Number(activeSignDocCtx.stampX);
    let stampedY = Number(activeSignDocCtx.stampY);

    if (!activeSignDocCtx.userManuallyPickedCoords || isNaN(stampedX) || isNaN(stampedY) || stampedY > 585 || stampedY < 150) {
        const resolved = window.resolveExactStampCoordsForSigner(signer, activeSignerIndex, circuit, activeSignDocCtx.detectedRows);
        stampedX = resolved.x;
        stampedY = resolved.y;
    }

    let stampedInPdf = false;

    // Si el archivo PDF está disponible en memoria:
    if (activeSignDocCtx.pdfBytes) {
        try {
            await window.ensurePdfLibReady();
            if (typeof PDFLib !== 'undefined' && PDFLib.PDFDocument) {
                let rawBytes = activeSignDocCtx.pdfBytes;
                if (rawBytes instanceof ArrayBuffer) {
                    rawBytes = new Uint8Array(rawBytes.slice(0));
                } else if (rawBytes && rawBytes.buffer instanceof ArrayBuffer) {
                    rawBytes = new Uint8Array(rawBytes.buffer.slice(rawBytes.byteOffset, rawBytes.byteOffset + rawBytes.byteLength));
                } else if (Array.isArray(rawBytes) || (typeof rawBytes === 'object' && rawBytes !== null)) {
                    rawBytes = new Uint8Array(Object.values(rawBytes));
                }

                const pdfDoc = await PDFLib.PDFDocument.load(rawBytes, {
                    ignoreEncryption: true,
                    updateMetadata: false
                });

                // Convertir base64 a Uint8Array binario puro
                const base64Data = signaturePngDataUrl.split(',')[1];
                const binaryString = atob(base64Data);
                const pngBytes = new Uint8Array(binaryString.length);
                for (let i = 0; i < binaryString.length; i++) {
                    pngBytes[i] = binaryString.charCodeAt(i);
                }

                const signatureImage = await pdfDoc.embedPng(pngBytes);
                const pages = pdfDoc.getPages();
                const lastPage = pages[pages.length - 1];
                const pWidth = lastPage.getWidth() || 612;
                const pHeight = lastPage.getHeight() || 792;

                let sW = 82;
                let sH = 26;
                if (stampedX + sW > pWidth) stampedX = Math.max(10, pWidth - sW - 10);
                if (stampedY + sH > pHeight) stampedY = Math.max(10, pHeight - sH - 10);

                lastPage.drawImage(signatureImage, {
                    x: stampedX,
                    y: stampedY,
                    width: sW,
                    height: sH
                });

                const newPdfBytes = await pdfDoc.save({ useObjectStreams: false });
                activeSignDocCtx.pdfBytes = newPdfBytes;

                if (window.SICOM_IDB && activeSignDocCtx.pdfKey) {
                    await window.SICOM_IDB.save(activeSignDocCtx.pdfKey, newPdfBytes);
                }
                stampedInPdf = true;
            }
        } catch (err) {
            console.error("Error al inyectar firma en PDF con pdf-lib:", err);
        }
    }

    // Registrar estado de la firma en el circuito
    signer.status = 'signed';
    signer.signedAt = stampDateStr;
    signer.signedBy = localAuthor;
    signer.signaturePng = signaturePngDataUrl;
    signer.injectedInPdf = stampedInPdf;
    signer.coords = {
        x: stampedX,
        y: stampedY,
        page: activeSignDocCtx.pdfPageCount || 1
    };

    logActivity(item.id, item.name, `Estampó firma digital [${signer.role}]: ${signer.name} en ${activeSignDocCtx.docName}`, localAuthor);

    // Reiniciar banderas para que el siguiente firmante se posicione automáticamente enfrente de su propio nombre
    activeSignDocCtx.lastAutoSignerId = null;
    activeSignDocCtx.userManuallyPickedCoords = false;

    const remaining = circuit.filter(s => s.status !== 'signed').length;
    if (remaining === 0) {
        docData.checked = true;
        const requester = window.getDocSignRequester(item, docData);
        const isReqOrSuper = window.isCurrentUserDocRequesterOrSuper(item, docData);

        // Disparar alerta externa y Web Push al Solicitante
        if (typeof window.sendExternalAlert === 'function') {
            window.sendExternalAlert('DOCUMENT_SIGNED_COMPLETE', {
                project: item.name,
                projectId: item.id,
                projectType: activeSignDocCtx.pType,
                docName: activeSignDocCtx.docName,
                docId: activeSignDocCtx.docId,
                targetUser: requester,
                consultant: requester
            });
        }

        if (isReqOrSuper) {
            window.showToast("🎉 ¡Documento 100% firmado! Puedes descargarlo ahora para guardarlo en la carpeta de Drive.", false);
        } else {
            window.showToast(`🎉 ¡Documento 100% firmado! Tu firma se estampó correctamente y se notificó a ${requester} para descargar el PDF y respaldarlo en Drive.`, false);
        }
        window.triggerCelebration();
    } else {
        const nextSigner = circuit.find(s => s.status !== 'signed');
        const nextName = nextSigner ? `${nextSigner.name} (${nextSigner.role})` : 'el siguiente firmante';
        if (stampedInPdf) {
            window.showToast(`✅ Firma de ${signer.name} estampada enfrente de su nombre. Turno de ${nextName}.`, false);
        } else {
            window.showToast(`✅ Firma de ${signer.name} autorizada y registrada. Turno de ${nextName}.`, false);
        }
    }

    window.saveData(false);
    window.flushCloudWrite(true);
    window.clearSignaturePad();
    window.renderDocSignCircuitList();
    window.updateDocSignStatusBadge();

    // Actualizar inmediatamente la vista previa para que la firma recién estampada se vea reflejada
    if (activeSignDocCtx.pdfBytes) {
        if (isFirebaseReady && db && globalDoc && globalSetDoc && activeSignDocCtx.pdfBytes.byteLength < 850000) {
            try {
                const pdfDocRef = globalDoc(db, 'artifacts', appId, 'public', 'data', 'sicom_pdfs', activeSignDocCtx.pdfKey);
                const b64 = uint8ToBase64(activeSignDocCtx.pdfBytes);
                globalSetDoc(pdfDocRef, {
                    pdfKey: activeSignDocCtx.pdfKey,
                    fileName: activeSignDocCtx.pdfFileName || 'Documento Oficial.pdf',
                    base64: b64,
                    pageCount: activeSignDocCtx.pdfPageCount || 1,
                    uploadedAt: Date.now()
                }, { merge: false }).catch(() => {});
            } catch (_) {}
        }
        await window.renderLastPdfPage();
    } else if (docData && docData.signatureSheetPreview) {
        await window.renderSignatureSheetFromPreview(docData.signatureSheetPreview, docData);
    }

    if (typeof window.renderDailyTasks === 'function') window.renderDailyTasks();
};

window.downloadCurrentSignedPdf = async function() {
    const item = getProjectById(activeSignDocCtx.projectId);
    const docData = item?.docs?.[activeSignDocCtx.docId];
    const isReqOrSuper = window.isCurrentUserDocRequesterOrSuper(item, docData);

    if (!isReqOrSuper) {
        const requester = window.getDocSignRequester(item, docData);
        window.showToast(`ℹ️ La descarga oficial está asignada al solicitante (${requester}) para evitar sobrecargar tu equipo y respaldar en Drive.`, false);
        return;
    }

    if (!activeSignDocCtx.pdfBytes && isFirebaseReady && db && globalDoc && globalGetDoc && activeSignDocCtx.pdfKey) {
        try {
            window.showToast("⏳ Descargando documento original desde la nube...", false);
            const pdfDocRef = globalDoc(db, 'artifacts', appId, 'public', 'data', 'sicom_pdfs', activeSignDocCtx.pdfKey);
            const snap = await globalGetDoc(pdfDocRef);
            if (snap.exists() && snap.data()?.base64) {
                const uint8 = base64ToUint8(snap.data().base64);
                activeSignDocCtx.pdfBytes = uint8;
                if (window.SICOM_IDB) {
                    await window.SICOM_IDB.save(activeSignDocCtx.pdfKey, uint8);
                }
            }
        } catch (e) {
            console.warn("Fallo al rescatar PDF para descarga:", e);
        }
    }

    if (!activeSignDocCtx.pdfBytes) {
        window.showToast("⚠️ El archivo PDF original reside en la computadora donde se subió y en Google Drive. Descárgalo desde ahí con las firmas sincronizadas.", true);
        return;
    }

    // Sincronizar infaliblemente todas las firmas del circuito antes de exportar
    if (typeof window.syncCircuitSignaturesToPdf === 'function') {
        await window.syncCircuitSignaturesToPdf();
    }

    const cleanStr = (s) => (s || '').replace(/[^a-zA-Z0-9_\-]/g, '_').replace(/_+/g, '_');
    const tkMadre = cleanStr(activeSignDocCtx.parentTicket || 'S_T');
    const tkHijo = cleanStr(activeSignDocCtx.childTicket || 'DOC');
    const dName = cleanStr(activeSignDocCtx.docName || 'Documento');
    const fileName = `${tkMadre}_${tkHijo}_${dName}_FIRMADO.pdf`;

    const blob = new Blob([activeSignDocCtx.pdfBytes], { type: 'application/pdf' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = fileName;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);

    window.showToast(`⬇️ Descargando ${fileName}. Súbelo a la carpeta de Drive del proyecto.`, false);
};

window.purgeCurrentDocumentLocalPdf = async function() {
    if (!confirm("¿Deseas liberar las 146 páginas del PDF del almacenamiento local del navegador?\n\nEl documento permanecerá 100% firmado y validado en SICOM con su ticket y enlace a Drive.")) return;

    if (window.SICOM_IDB && activeSignDocCtx.pdfKey) {
        await window.SICOM_IDB.delete(activeSignDocCtx.pdfKey);
        await window.SICOM_IDB.delete(activeSignDocCtx.pdfKey + '_clean');
    }

    activeSignDocCtx.pdfBytes = null;
    activeSignDocCtx.cleanPdfBytes = null;
    activeSignDocCtx.detectedRows = [];

    // Ocultar visor y controles de estampado
    document.getElementById('docSignCanvasWrapper')?.classList.add('hidden');
    document.getElementById('docSignNoPdfPlaceholder')?.classList.remove('hidden');
    document.getElementById('docSignStampControls')?.classList.add('hidden');
    document.getElementById('docSignDetectedSlotsBar')?.classList.add('hidden');
    document.getElementById('docSignPaginationControls')?.classList.add('hidden');

    const infoEl = document.getElementById('docSignPdfInfo');
    if (infoEl) infoEl.textContent = 'Espacio liberado';
    const nameEl = document.getElementById('docSignPdfNameContainer');
    if (nameEl) nameEl.textContent = 'PDF local liberado (Firmado en SICOM y respaldado en Drive)';

    const placeholderText = document.getElementById('docSignNoPdfPlaceholder');
    if (placeholderText) {
        placeholderText.innerHTML = `
            <div class="text-center p-8 text-[#22c55e] my-auto space-y-2">
                <div class="w-12 h-12 rounded-full bg-[#22c55e]/20 border border-[#22c55e] flex items-center justify-center text-[#22c55e] text-xl font-bold mx-auto">✓</div>
                <p class="text-xs font-mono uppercase font-bold text-[#22c55e]">Documento 100% Firmado y Autorizado</p>
                <p class="text-[11px] text-[#b8b3b0] max-w-md mx-auto">El archivo de 146 páginas fue liberado del navegador para no consumir memoria. El registro oficial y el enlace residen en Google Drive.</p>
                <div class="pt-2">
                    <button type="button" onclick="openDocDriveLink()" class="pill-btn px-3 py-1.5 bg-[#1d1a18] hover:bg-[#282523] border border-[#3d3a39] hover:border-[#3b82f6] text-[#fafafa] font-mono text-[10px] uppercase transition inline-flex items-center gap-1.5 cursor-pointer">
                        <svg class="w-3.5 h-3.5 text-[#3b82f6]" fill="currentColor" viewBox="0 0 24 24"><path d="M19.35 10.04C18.67 6.59 15.64 4 12 4 9.11 4 6.6 5.64 5.35 8.04 2.34 8.36 0 10.91 0 14c0 3.31 2.69 6 6 6h13c2.76 0 5-2.24 5-5 0-2.64-2.05-4.78-4.65-4.96zM19 18H6c-2.21 0-4-1.79-4-4 0-2.05 1.53-3.76 3.56-3.97l1.07-.11.5-.95C8.08 7.14 9.94 6 12 6c2.62 0 4.88 1.86 5.39 4.43l.3 1.5 1.53.11c1.56.1 2.78 1.41 2.78 2.96 0 1.65-1.35 3-3 3z"/></svg>
                        <span>Abrir Documento en Google Drive ↗</span>
                    </button>
                </div>
            </div>`;
    }

    const item = getProjectById(activeSignDocCtx.projectId);
    if (item && item.docs && item.docs[activeSignDocCtx.docId]) {
        item.docs[activeSignDocCtx.docId].pdfPurged = true;
        window.saveData(false);
    }

    window.showToast("🧹 Memoria liberada. El PDF pesado fue retirado del navegador sin perder el estatus firmado.", false);
};
